    default,
    jsonb_path_ops,
    array_ops,
    vector_l2_ops,
    vector_ip_ops,
    vector_cosine_ops,
};

pub fn ddlIndexMethodIsDerived(method: DdlIndexMethod) bool {
    return switch (method) {
        .antfly_full_text, .hnsw, .antfly_aknn, .antfly_graph, .antfly_graph_metric, .antfly_hybrid, .antfly_algebraic => true,
        .btree, .gin => false,
    };
}

pub fn runtimeSchemaFromCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    plan: CreateTablePlan,
) !runtime_schema.TableSchema {
    if (plan.storage_mode == .document) {
        const schema_json = try documentSchemaJsonFromCreateTablePlanAlloc(alloc, plan);
        defer alloc.free(schema_json);
        var parsed_schema = try schema_api.parseValidatedTableSchema(alloc, schema_json);
        defer parsed_schema.deinit(alloc);
        const runtime = try schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
        if (runtime.storage_mode != .document) {
            runtime_schema.freeSchema(alloc, runtime);
            return error.InvalidSqlCatalog;
        }
        return runtime;
    }

    try expr_type.validateRelationalColumnCatalog(plan.columns);
    try binder.validateRelationalPeriodCatalog(plan.columns, plan.periods);
    if (plan.primary_key) |primary_key| {
        try expr_type.validatePrimaryKeyColumns(plan.columns, primary_key);
        try binder.validatePrimaryKeyTemporalCatalog(plan.periods, primary_key);
    }
    try expr_type.validateUniqueConstraintCatalog(plan.columns, plan.periods, plan.unique_constraints);
    try expr_type.validateForeignKeyCatalog(plan.columns, plan.periods, plan.foreign_keys);
    try expr_type.validateRelationalCheckCatalog(plan.columns, plan.checks);
    for (plan.columns) |column| {
        if (column.default_value) |default_value| try value_mod.validateDefaultValueForColumnAlloc(alloc, column, default_value);
        if (column.on_update_value) |on_update_value| try value_mod.validateDefaultValueForColumnAlloc(alloc, column, on_update_value);
    }

    const default_type = try alloc.dupe(u8, "_default");
    const ttl_field = alloc.dupe(u8, "_timestamp") catch |err| {
        alloc.free(default_type);
        return err;
    };
    var schema: runtime_schema.TableSchema = .{
        .default_type = default_type,
        .ttl_field = ttl_field,
        .enforce_types = true,
        .storage_mode = .relational,
    };
    errdefer runtime_schema.freeSchema(alloc, schema);
    schema.relational_columns = try cloneDdlRelationalColumns(alloc, plan.columns);
    schema.primary_key = try cloneDdlPrimaryKeyMaybe(alloc, plan.primary_key);
    schema.periods = try cloneDdlPeriods(alloc, plan.periods);
    schema.unique_constraints = try cloneDdlUniqueConstraints(alloc, plan.unique_constraints);
    schema.foreign_keys = try cloneDdlForeignKeys(alloc, plan.foreign_keys);
    schema.checks = try cloneDdlRelationalChecks(alloc, plan.checks);
    schema.system_versioned = plan.system_versioned;
    return schema;
}

fn knownSqlDocumentSchemaAntflyExtension(key: []const u8) bool {
    return std.mem.eql(u8, key, "x-antfly-analyzer") or
        std.mem.eql(u8, key, "x-antfly-default") or
        std.mem.eql(u8, key, "x-antfly-dynamic-indexing") or
        std.mem.eql(u8, key, "x-antfly-include-in-all") or
        std.mem.eql(u8, key, "x-antfly-index") or
        std.mem.eql(u8, key, "x-antfly-index-access-method") or
        std.mem.eql(u8, key, "x-antfly-index-generation") or
        std.mem.eql(u8, key, "x-antfly-index-include") or
        std.mem.eql(u8, key, "x-antfly-index-keys") or
        std.mem.eql(u8, key, "x-antfly-index-lifecycle") or
        std.mem.eql(u8, key, "x-antfly-index-name") or
        std.mem.eql(u8, key, "x-antfly-index-schema-fingerprint") or
        std.mem.eql(u8, key, "x-antfly-index-where") or
        std.mem.eql(u8, key, "x-antfly-index-where-expressions") or
        std.mem.eql(u8, key, "x-antfly-on-update") or
        std.mem.eql(u8, key, "x-antfly-types");
}

fn validateSqlDocumentSchemaDdlValue(value: std.json.Value) !void {
    switch (value) {
        .object => |object| {
            var it = object.iterator();
            while (it.next()) |entry| {
                const key = entry.key_ptr.*;
                if (std.mem.startsWith(u8, key, "x-antfly-") and !knownSqlDocumentSchemaAntflyExtension(key)) {
                    return error.UnsupportedSqlShape;
                }
                if (std.mem.eql(u8, key, "dynamic_templates") and
                    entry.value_ptr.* != .null and
                    entry.value_ptr.* != .object)
                {
                    return error.UnsupportedSqlShape;
                }
                try validateSqlDocumentSchemaDdlValue(entry.value_ptr.*);
            }
        },
        .array => |array| for (array.items) |item| try validateSqlDocumentSchemaDdlValue(item),
        else => {},
    }
}

pub fn documentSchemaJsonFromCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    plan: CreateTablePlan,
) ![]u8 {
    if (plan.storage_mode != .document) return error.InvalidSqlCatalog;
    if (plan.columns.len != 0 or
        plan.primary_key != null or
        plan.periods.len != 0 or
        plan.unique_constraints.len != 0 or
        plan.foreign_keys.len != 0 or
        plan.checks.len != 0 or
        plan.system_versioned)
    {
        return error.UnsupportedSqlShape;
    }
    const default_type = plan.default_type orelse return error.UnsupportedSqlShape;
    if (plan.document_schemas.len == 0) return error.UnsupportedSqlShape;
    if (plan.document_schemas.len != 1) return error.UnsupportedSqlShape;

    var found_default = false;
    var arena_impl = std.heap.ArenaAllocator.init(alloc);
    defer arena_impl.deinit();
    const arena = arena_impl.allocator();

    var document_schemas = std.json.ObjectMap.empty;
    for (plan.document_schemas) |document_schema| {
        if (std.mem.eql(u8, document_schema.name, default_type)) found_default = true;
        const parsed_schema = try std.json.parseFromSliceLeaky(std.json.Value, arena, document_schema.schema_json, .{ .allocate = .alloc_always });
        try validateSqlDocumentSchemaDdlValue(parsed_schema);
        var schema_wrapper = std.json.ObjectMap.empty;
        try schema_wrapper.put(arena, try arena.dupe(u8, "schema"), parsed_schema);
        try document_schemas.put(arena, try arena.dupe(u8, document_schema.name), .{ .object = schema_wrapper });
    }
    if (!found_default) return error.UnsupportedSqlShape;

    var root = std.json.ObjectMap.empty;
    try root.put(arena, try arena.dupe(u8, "storage_mode"), .{ .string = try arena.dupe(u8, "document") });
    try root.put(arena, try arena.dupe(u8, "default_type"), .{ .string = try arena.dupe(u8, default_type) });
    try root.put(arena, try arena.dupe(u8, "enforce_types"), .{ .bool = true });
    try root.put(arena, try arena.dupe(u8, "document_schemas"), .{ .object = document_schemas });
    return try std.json.Stringify.valueAlloc(alloc, std.json.Value{ .object = root }, .{ .emit_null_optional_fields = false });
}

fn validateDocumentCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    plan: CreateTablePlan,
) !void {
    const runtime = runtimeSchemaFromCreateTablePlanAlloc(alloc, plan) catch |err| {
        if (err == error.OutOfMemory) return err;
        return error.UnsupportedSqlShape;
    };
    defer runtime_schema.freeSchema(alloc, runtime);
}

fn clearClonedColumnDefault(alloc: std.mem.Allocator, column: *runtime_schema.RelationalColumn) void {
    if (column.default_value) |value| alloc.free(value.value_json);
    column.default_value = null;
}

fn clearClonedColumnGenerated(alloc: std.mem.Allocator, column: *runtime_schema.RelationalColumn) void {
    if (column.generated) |generated| freeDdlGeneratedValue(alloc, generated);
    column.generated = null;
}

fn clearClonedColumnUpdatePolicy(alloc: std.mem.Allocator, column: *runtime_schema.RelationalColumn) void {
    if (column.on_update_value) |value| alloc.free(value.value_json);
    column.on_update_value = null;
}

fn clearClonedColumnIndexMetadata(alloc: std.mem.Allocator, column: *runtime_schema.RelationalColumn) void {
    if (column.index_name) |index_name| alloc.free(index_name);
    column.index_name = null;
    if (column.index_schema_fingerprint) |fingerprint| alloc.free(fingerprint);
    column.index_access_method = null;
    column.index_schema_fingerprint = null;
    freeStringSlice(alloc, column.index_include_columns);
    column.index_include_columns = &.{};
    freeDdlRelationalIndexKeys(alloc, column.index_keys);
    column.index_keys = &.{};
    column.indexed = false;
    column.index_lifecycle = .ready;
    column.index_generation = 0;
    freeDdlUniquePredicates(alloc, column.index_where);
    column.index_where = &.{};
    freeExpressionConditions(alloc, column.index_where_expressions);
    if (column.index_where_expressions.len > 0) alloc.free(column.index_where_expressions);
    column.index_where_expressions = &.{};
}

pub fn createTablePlanFromTableCloneSourceAlloc(
    alloc: std.mem.Allocator,
    source: runtime_schema.TableSchema,
    plan: TableClonePlan,
) !CreateTablePlan {
    if (source.storage_mode != .relational) return error.InvalidSqlCatalog;
    if (!plan.options.columns or !plan.options.constraints or source.primary_key == null) return error.UnsupportedSqlShape;

    const table_name = try alloc.dupe(u8, plan.table_name);
    errdefer alloc.free(table_name);

    var columns = std.ArrayListUnmanaged(runtime_schema.RelationalColumn).empty;
    errdefer {
        clearDdlRelationalColumns(alloc, columns.items);
        columns.deinit(alloc);
    }
    for (source.relational_columns) |source_column| {
        var column = try cloneDdlRelationalColumn(alloc, source_column);
        var column_transferred = false;
        errdefer if (!column_transferred) freeDdlRelationalColumn(alloc, column);
        if (!plan.options.defaults) clearClonedColumnDefault(alloc, &column);
        if (!plan.options.generated) clearClonedColumnGenerated(alloc, &column);
        if (!plan.options.update_policies) clearClonedColumnUpdatePolicy(alloc, &column);
        if (!plan.options.indexes) clearClonedColumnIndexMetadata(alloc, &column);
        try columns.append(alloc, column);
        column_transferred = true;
    }

    const primary_key = try cloneDdlPrimaryKey(alloc, source.primary_key.?);
    errdefer freeDdlPrimaryKey(alloc, primary_key);
    const periods = if (plan.options.periods) try cloneDdlPeriods(alloc, source.periods) else &.{};
    errdefer freeDdlPeriods(alloc, periods);
    const unique_constraints = if (plan.options.constraints) try cloneDdlUniqueConstraints(alloc, source.unique_constraints) else &.{};
    errdefer freeDdlUniqueConstraints(alloc, unique_constraints);
    const foreign_keys = if (plan.options.constraints) try cloneDdlForeignKeys(alloc, source.foreign_keys) else &.{};
    errdefer freeDdlForeignKeys(alloc, foreign_keys);
    const checks = if (plan.options.checks or plan.options.constraints) try cloneDdlRelationalChecks(alloc, source.checks) else &.{};
    errdefer freeDdlRelationalChecks(alloc, checks);

    return .{
        .table_name = table_name,
        .if_not_exists = plan.if_not_exists,
        .columns = try columns.toOwnedSlice(alloc),
        .primary_key = primary_key,
        .periods = periods,
        .unique_constraints = unique_constraints,
        .foreign_keys = foreign_keys,
        .checks = checks,
        .system_versioned = source.system_versioned,
    };
}

