pub fn preparedTransactionPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlPreparedTransactionAst,
) !PreparedTransactionPlan {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end != 3 or tokens.len < end) return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    const second_expected = switch (ast.kind) {
        .prepare => "transaction",
        .commit, .rollback => "prepared",
    };
    const action: PreparedTransactionAction = switch (ast.kind) {
        .prepare => .prepare,
        .commit => .commit,
        .rollback => .rollback,
    };
    switch (ast.kind) {
        .prepare => if (!tokens[0].matchesKeywordTag(.prepare)) return error.UnsupportedSqlShape,
        .commit => if (!tokens[0].matchesKeywordTag(.commit)) return error.UnsupportedSqlShape,
        .rollback => if (!tokens[0].matchesKeywordTag(.rollback)) return error.UnsupportedSqlShape,
    }
    if (!tokens[1].matchesKeyword(second_expected)) return error.UnsupportedSqlShape;
    const gid_tokens = ast.gid_tokens orelse return error.UnsupportedSqlShape;
    if (gid_tokens.start != 2 or gid_tokens.end != 3) return error.UnsupportedSqlShape;
    if (tokens[2].kind != .string or tokens[2].text.len == 0) return error.UnsupportedSqlShape;
    return .{
        .action = action,
        .gid = try alloc.dupe(u8, tokens[2].text),
    };
}

pub fn preparedStatementPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !PreparedStatementPlan {
    const tokens = parsed_sql.items();
    try validateGeneratedPreparedAstRanges(tokens, ast);
    return switch (ast.kind) {
        .prepare => .{ .prepare = try prepareStatementPlanFromGeneratedAstAlloc(alloc, parsed_sql, ast) },
        .execute => .{ .execute = try executePreparedStatementPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
        .deallocate => .{ .deallocate = try deallocatePreparedStatementPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
    };
}

fn validateGeneratedPreparedAstRanges(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    const expected: token_mod.TokenKeyword = switch (ast.kind) {
        .prepare => .prepare,
        .execute => .execute,
        .deallocate => .deallocate,
    };
    if (!tokens[0].matchesKeywordTag(expected)) return error.UnsupportedSqlShape;

    switch (ast.kind) {
        .prepare => {
            try validateGeneratedPreparedRequiredRangeAt(ast.name_tokens, 1, 2, end);
            const inner = ast.inner_statement_tokens orelse return error.UnsupportedSqlShape;
            try validateGeneratedPreparedRange(tokens, inner, 3, end);
            if (inner.start == 0 or !tokens[inner.start - 1].matchesKeywordTag(.as)) return error.UnsupportedSqlShape;
            if (ast.parameter_tokens) |parameter_tokens| {
                if (parameter_tokens.start != 2 or parameter_tokens.end + 1 != inner.start) return error.UnsupportedSqlShape;
                _ = try countGeneratedParenthesizedList(tokens, parameter_tokens);
            } else if (inner.start != 3) {
                return error.UnsupportedSqlShape;
            }
            if (ast.argument_tokens != null) return error.UnsupportedSqlShape;
        },
        .execute => {
            try validateGeneratedPreparedRequiredRangeAt(ast.name_tokens, 1, 2, end);
            if (ast.argument_tokens) |argument_tokens| {
                if (argument_tokens.start != 2 or argument_tokens.end != end) return error.UnsupportedSqlShape;
                _ = try countGeneratedParenthesizedList(tokens, argument_tokens);
            } else if (end != 2) {
                return error.UnsupportedSqlShape;
            }
            if (ast.parameter_tokens != null or ast.inner_statement_tokens != null) return error.UnsupportedSqlShape;
        },
        .deallocate => {
            _ = try generatedDeallocateStatementNameRange(tokens, ast.name_tokens, end);
            if (ast.parameter_tokens != null or ast.argument_tokens != null or ast.inner_statement_tokens != null) return error.UnsupportedSqlShape;
        },
    }
}

fn generatedDeallocateStatementNameRange(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    end: usize,
) !generated_parser.GeneratedSqlTokenRange {
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.end != end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (range.start == 1 and range.start + 1 == range.end) return range;
    if (range.start == 2 and range.start + 1 == range.end and tokens.len > 1 and tokens[1].matchesKeywordTag(.prepare)) {
        return range;
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedPreparedRange(
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
    min_start: usize,
    end: usize,
) !void {
    if (range.start < min_start or range.start >= range.end or range.end > end or range.end > tokens.len) return error.UnsupportedSqlShape;
}

fn validateGeneratedPreparedRequiredRangeAt(
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    start: usize,
    end: usize,
    statement_end: usize,
) !void {
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start != start or range.end != end or range.end > statement_end) return error.UnsupportedSqlShape;
}

pub fn prepareStatementPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !PrepareStatementPlan {
    const tokens = parsed_sql.items();
    const statement_name = try generatedSingleIdentifierText(tokens, ast.name_tokens orelse return error.UnsupportedSqlShape);
    const inner = ast.inner_statement_tokens orelse return error.UnsupportedSqlShape;
    const parameter_count = if (ast.parameter_tokens) |parameter_tokens|
        try countGeneratedParenthesizedList(tokens, parameter_tokens)
    else
        0;
    const owned_statement_name = try alloc.dupe(u8, statement_name);
    errdefer alloc.free(owned_statement_name);
    var payload = try generatedPreparedStatementPayloadFromAstAlloc(
        alloc,
        tokens,
        inner,
        ast.inner_statement_ast orelse return error.UnsupportedSqlShape,
    );
    errdefer deinitOwnedParsedSql(alloc, &payload.subject_parsed_sql);
    return .{
        .statement_name = owned_statement_name,
        .parameter_count = parameter_count,
        .statement_kind = preparedStatementSubjectKindFromStatementKind(payload.statement_family),
        .statement_family = payload.statement_family,
        .subject_parsed_sql = payload.subject_parsed_sql,
    };
}

const GeneratedPreparedStatementPayload = struct {
    statement_family: PreparedStatementStatementKind,
    subject_parsed_sql: tokenized.ParsedSql,
};

fn generatedPreparedStatementPayloadFromAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    inner: generated_parser.GeneratedSqlTokenRange,
    inner_ast: *const generated_parser.GeneratedSqlAst,
) !GeneratedPreparedStatementPayload {
    if (inner.start >= inner.end or inner.end > tokens.len) return error.UnsupportedSqlShape;
    const subject_tokens = tokens[inner.start..inner.end];
    const owned_sql = try tokenized.sqlTextFromTokenSliceAlloc(alloc, subject_tokens);
    errdefer alloc.free(owned_sql);

    return switch (inner_ast.*) {
        .read => |read_ast| .{
            .statement_family = .read,
            .subject_parsed_sql = try tokenized.ParsedSql.initFromOwnedTokenSliceWithGeneratedReadAstAlloc(alloc, owned_sql, subject_tokens, read_ast),
        },
        .dml => |dml_ast| try generatedPreparedDmlPayloadFromOwnedSubjectAlloc(alloc, owned_sql, subject_tokens, dml_ast),
        .ddl => |ddl_ast| try generatedPreparedDdlPayloadFromOwnedSubjectAlloc(alloc, owned_sql, subject_tokens, ddl_ast, .ddl),
        .extension_index => |ddl_ast| try generatedPreparedDdlPayloadFromOwnedSubjectAlloc(alloc, owned_sql, subject_tokens, ddl_ast, .extension_index),
        else => error.UnsupportedSqlShape,
    };
}

fn generatedPreparedDmlPayloadFromOwnedSubjectAlloc(
    alloc: std.mem.Allocator,
    owned_sql: []const u8,
    subject_tokens: []const grammar.Token,
    dml_ast: generated_parser.GeneratedSqlDmlAst,
) !GeneratedPreparedStatementPayload {
    var subject = try tokenized.ParsedSql.initFromOwnedTokenSliceWithGeneratedDmlAstAlloc(alloc, owned_sql, subject_tokens, &dml_ast);
    errdefer subject.deinit(alloc);
    const parsed_kind = subject.writeStatementKindIncludingGeneratedAst() orelse return error.UnsupportedSqlShape;
    const expected_family = generatedPreparedStatementFamilyFromDmlKind(dml_ast.kind);
    if (preparedStatementFamilyFromWriteKind(parsed_kind) != expected_family) return error.UnsupportedSqlShape;
    return .{
        .statement_family = expected_family,
        .subject_parsed_sql = subject,
    };
}

fn generatedPreparedDdlPayloadFromOwnedSubjectAlloc(
    alloc: std.mem.Allocator,
    owned_sql: []const u8,
    subject_tokens: []const grammar.Token,
    ddl_ast: generated_parser.GeneratedSqlDdlAst,
    expected_statement_kind: generated_parser.GeneratedSqlStatementKind,
) !GeneratedPreparedStatementPayload {
    var subject = try tokenized.ParsedSql.initFromOwnedTokenSliceWithGeneratedDdlAstAlloc(alloc, owned_sql, subject_tokens, &ddl_ast, expected_statement_kind);
    errdefer subject.deinit(alloc);
    if (subject.generatedStatementKind() != expected_statement_kind) return error.UnsupportedSqlShape;
    const generated_statement = subject.generated_statement orelse return error.UnsupportedSqlShape;
    const generated_ast = generated_statement.ast orelse return error.UnsupportedSqlShape;
    const subject_ddl = switch (generated_ast) {
        .ddl => |ast| ast,
        .extension_index => |ast| ast,
        else => return error.UnsupportedSqlShape,
    };
    if (subject_ddl.kind != ddl_ast.kind) return error.UnsupportedSqlShape;
    return .{
        .statement_family = .ddl,
        .subject_parsed_sql = subject,
    };
}

fn deinitOwnedParsedSql(alloc: std.mem.Allocator, parsed_sql: *tokenized.ParsedSql) void {
    const owned_sql = parsed_sql.sql();
    parsed_sql.deinit(alloc);
    alloc.free(@constCast(owned_sql));
}

fn generatedPreparedStatementFamilyFromDmlKind(kind: generated_parser.GeneratedSqlDmlKind) PreparedStatementStatementKind {
    return switch (kind) {
        .insert_values => .insert,
        .insert_select => .insert_source,
        .update => .update,
        .delete => .delete,
        .truncate => .truncate,
        .merge => .merge,
    };
}

fn preparedStatementFamilyFromWriteKind(kind: sql_statement_kind.SqlWriteStatementKind) PreparedStatementStatementKind {
    return switch (kind) {
        .insert => .insert,
        .insert_source => .insert_source,
        .update, .update_source, .update_joined_source => .update,
        .delete, .delete_source, .delete_joined_source => .delete,
        .truncate => .truncate,
        .merge => .merge,
    };
}

fn preparedStatementSubjectKindFromStatementKind(kind: PreparedStatementStatementKind) PreparedStatementSubjectKind {
    return switch (kind) {
        .read => .read,
        .insert,
        .insert_source,
        .update,
        .delete,
        .truncate,
        .merge,
        => .write,
        .ddl => .ddl,
    };
}

fn parseExecutePreparedStatementArgumentsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
) ![]const value_mod.SqlValue {
    if (tokens.len == 0) return &.{};
    var pos: usize = 0;
    if (parser.matchToken(tokens, &pos, .lparen) == null) return error.UnsupportedSqlShape;
    if (parser.matchToken(tokens, &pos, .rparen) != null) {
        if (pos != tokens.len) return error.UnsupportedSqlShape;
        return &.{};
    }
    var values = std.ArrayListUnmanaged(value_mod.SqlValue).empty;
    errdefer {
        for (values.items) |value| value_mod.deinitSqlValue(alloc, value);
        values.deinit(alloc);
    }
    while (true) {
        try values.append(alloc, try value_mod.parseSqlUntypedValueAlloc(alloc, tokens, &pos));
        if (parser.matchToken(tokens, &pos, .comma) != null) continue;
        break;
    }
    _ = parser.matchToken(tokens, &pos, .rparen) orelse return error.UnsupportedSqlShape;
    if (pos != tokens.len) return error.UnsupportedSqlShape;
    return try values.toOwnedSlice(alloc);
}

pub fn executePreparedStatementPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !ExecutePreparedStatementPlan {
    const statement_name = try generatedSingleIdentifierText(tokens, ast.name_tokens orelse return error.UnsupportedSqlShape);
    const argument_count = if (ast.argument_tokens) |argument_tokens|
        try countGeneratedParenthesizedList(tokens, argument_tokens)
    else
        0;
    var plan = ExecutePreparedStatementPlan{
        .statement_name = try alloc.dupe(u8, statement_name),
        .argument_count = argument_count,
    };
    errdefer plan.deinit(alloc);
    if (ast.argument_tokens) |argument_tokens| {
        plan.arguments = try parseExecutePreparedStatementArgumentsAlloc(alloc, tokens[argument_tokens.start..argument_tokens.end]);
    }
    return plan;
}

pub fn deallocatePreparedStatementPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlPreparedAst,
) !DeallocatePreparedStatementPlan {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const name_tokens = try generatedDeallocateStatementNameRange(tokens, ast.name_tokens, end);
    if (name_tokens.start + 1 == name_tokens.end and tokens[name_tokens.start].matchesKeywordTag(.all)) {
        return .{ .all = true };
    }
    const statement_name = try generatedSingleIdentifierText(tokens, name_tokens);
    return .{ .statement_name = try alloc.dupe(u8, statement_name) };
}

pub fn cursorPortalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
) !DdlPlan {
    const cursor = try cursorPortalLogicalPlanFromGeneratedAstAlloc(alloc, tokens, ast);
    return .{ .cursor_portal = cursor };
}

pub fn cursorPortalLogicalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
) !CursorPortalPlan {
    try validateGeneratedCursorAstSpans(tokens, ast);
    const tail = ast.tail_tokens orelse return error.UnsupportedSqlShape;
    var plan: CursorPortalPlan = switch (ast.kind) {
        .declare => .{ .declare = try declareCursorPortalPlanFromGeneratedAstAlloc(alloc, tokens, ast, tail) },
        .fetch => .{ .fetch = try fetchCursorPortalPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
        .move => .{ .move = try fetchCursorPortalPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
        .close => .{ .close = try closeCursorPortalPlanFromGeneratedAstAlloc(alloc, tokens, ast) },
    };
    errdefer plan.deinit(alloc);
    return plan;
}

fn declareCursorPortalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
    tail: generated_parser.GeneratedSqlTokenRange,
) !DeclareCursorPortalPlan {
    const portal_name = try generatedSingleIdentifierText(tokens, ast.portal_name_tokens orelse return error.UnsupportedSqlShape);
    const subject_range = ast.subject_tokens orelse return error.UnsupportedSqlShape;
    if (subject_range.start < tail.start or subject_range.end > tail.end or subject_range.start >= subject_range.end) {
        return error.UnsupportedSqlShape;
    }
    var payload = try generatedPreparedStatementPayloadFromAstAlloc(
        alloc,
        tokens,
        subject_range,
        ast.subject_ast orelse return error.UnsupportedSqlShape,
    );
    errdefer deinitOwnedParsedSql(alloc, &payload.subject_parsed_sql);
    var plan = DeclareCursorPortalPlan{
        .portal_name = try alloc.dupe(u8, portal_name),
        .scroll = cursorScrollModeFromGenerated(ast.scroll_mode),
        .binary = ast.binary,
        .hold = ast.hold,
        .statement_kind = preparedStatementSubjectKindFromStatementKind(payload.statement_family),
        .subject_parsed_sql = payload.subject_parsed_sql,
    };
    errdefer plan.deinit(alloc);
    payload.subject_parsed_sql = undefined;
    return plan;
}

fn fetchCursorPortalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
) !FetchCursorPortalPlan {
    const portal_name = try generatedSingleIdentifierText(tokens, ast.portal_name_tokens orelse return error.UnsupportedSqlShape);
    return .{
        .portal_name = try alloc.dupe(u8, portal_name),
        .direction = cursorFetchDirectionFromGenerated(ast.fetch_direction),
        .count = ast.fetch_count,
    };
}

fn closeCursorPortalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
) !CloseCursorPortalPlan {
    if (ast.close_all) return .{ .all = true };
    const portal_name = try generatedSingleIdentifierText(tokens, ast.portal_name_tokens orelse return error.UnsupportedSqlShape);
    return .{ .portal_name = try alloc.dupe(u8, portal_name) };
}

fn cursorScrollModeFromGenerated(mode: generated_parser.GeneratedSqlCursorScrollMode) CursorScrollMode {
    return switch (mode) {
        .default => .default,
        .scroll => .scroll,
        .no_scroll => .no_scroll,
    };
}

fn cursorFetchDirectionFromGenerated(direction: generated_parser.GeneratedSqlCursorFetchDirection) CursorFetchDirection {
    return switch (direction) {
        .next => .next,
        .prior => .prior,
        .first => .first,
        .last => .last,
        .absolute => .absolute,
        .relative => .relative,
        .forward => .forward,
        .backward => .backward,
        .all => .all,
    };
}

fn validateGeneratedCursorAstSpans(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlCursorAst,
) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end == 0 or tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    switch (ast.kind) {
        .declare => if (!tokens[0].matchesKeywordTag(.declare)) return error.UnsupportedSqlShape,
        .fetch => if (!tokens[0].matchesKeywordTag(.fetch)) return error.UnsupportedSqlShape,
        .move => if (!tokens[0].matchesKeywordTag(.move)) return error.UnsupportedSqlShape,
        .close => if (!tokens[0].matchesKeywordTag(.close)) return error.UnsupportedSqlShape,
    }
    const tail = ast.tail_tokens orelse return error.UnsupportedSqlShape;
    if (tail.start != 1 or tail.end != end or tail.start >= tail.end or tail.end > tokens.len) {
        return error.UnsupportedSqlShape;
    }
    if (ast.kind == .declare) {
        const portal_name = ast.portal_name_tokens orelse return error.UnsupportedSqlShape;
        if (portal_name.start != tail.start or portal_name.end != tail.start + 1 or portal_name.end > tail.end) {
            return error.UnsupportedSqlShape;
        }
        if (tokens[portal_name.start].kind != .identifier) return error.UnsupportedSqlShape;
        const subject = ast.subject_tokens orelse return error.UnsupportedSqlShape;
        if (subject.start < tail.start or subject.end > tail.end or subject.start >= subject.end or ast.subject_ast == null) {
            return error.UnsupportedSqlShape;
        }
        if (subject.start <= portal_name.end) return error.UnsupportedSqlShape;
    } else {
        if (ast.subject_tokens != null or ast.subject_ast != null or ast.binary or ast.hold or ast.scroll_mode != .default) {
            return error.UnsupportedSqlShape;
        }
        switch (ast.kind) {
            .fetch, .move => {
                const portal_name = ast.portal_name_tokens orelse return error.UnsupportedSqlShape;
                if (portal_name.start < tail.start or portal_name.end != tail.end or portal_name.start + 1 != portal_name.end) {
                    return error.UnsupportedSqlShape;
                }
                if (tokens[portal_name.start].kind != .identifier) return error.UnsupportedSqlShape;
                if (ast.close_all) return error.UnsupportedSqlShape;
            },
            .close => {
                if (ast.close_all) {
                    if (ast.portal_name_tokens != null or tail.start + 1 != tail.end or !tokens[tail.start].matchesKeyword("all")) {
                        return error.UnsupportedSqlShape;
                    }
                } else {
                    const portal_name = ast.portal_name_tokens orelse return error.UnsupportedSqlShape;
                    if (portal_name.start != tail.start or portal_name.end != tail.end or portal_name.start + 1 != portal_name.end) {
                        return error.UnsupportedSqlShape;
                    }
                    if (tokens[portal_name.start].kind != .identifier) return error.UnsupportedSqlShape;
                }
            },
            .declare => unreachable,
        }
    }
}

fn generatedSingleIdentifierText(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) ![]const u8 {
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].kind != .identifier) return error.UnsupportedSqlShape;
    return tokens[range.start].text;
}

fn countGeneratedParenthesizedList(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) !usize {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].kind != .lparen or tokens[range.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
    if (range.start + 1 == range.end - 1) return 0;

    var count: usize = 1;
    var depth: usize = 0;
    for (tokens[range.start + 1 .. range.end - 1]) |token| {
        switch (token.kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return error.UnsupportedSqlShape;
                depth -= 1;
            },
            .comma => {
                if (depth == 0) count += 1;
            },
            else => {},
        }
    }
    if (depth != 0) return error.UnsupportedSqlShape;
    return count;
}

pub fn sessionCatalogPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) !SessionCatalogPlan {
    const end = try validateGeneratedSessionAstRanges(tokens, ast);
    var plan: SessionCatalogPlan = switch (ast.kind) {
        .set => try setSessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, end, ast),
        .reset => try resetSessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, end, ast),
        .show => try showSessionCatalogPlanFromGeneratedAst(tokens, end, ast),
        .discard_all => try discardSessionCatalogPlanFromGeneratedAst(tokens, end, ast),
    };
    errdefer plan.deinit(alloc);
    try validateGeneratedSessionCatalogPlanMatchesAst(tokens, end, ast, plan);
    return plan;
}

fn sessionLogicalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) !binder.LogicalSqlPlan {
    const plan = try sessionDdlPlanFromGeneratedAstAlloc(alloc, tokens, ast);
    return switch (plan) {
        .session_catalog => |session| .{ .session = session },
        else => error.UnsupportedSqlShape,
    };
}

pub fn transactionControlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !DdlPlan {
    const logical = try transactionLogicalPlanFromGeneratedAstAlloc(alloc, tokens, ast);
    return switch (logical) {
        .boundary => |payload| .{ .transaction_boundary = payload },
        .control => |payload| .{ .transaction_control = payload },
        .savepoint => |payload| .{ .savepoint_transaction = payload },
        .prepared => |payload| .{ .prepared_transaction = payload },
    };
}

pub fn transactionLogicalPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !binder.TransactionLogicalPlan {
    try validateGeneratedTransactionAstSpans(tokens, ast);
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (ast.name_tokens) |name_tokens| {
        if (name_tokens.end != end) return error.UnsupportedSqlShape;
        var plan: binder.TransactionLogicalPlan = switch (ast.kind) {
            .savepoint => .{ .savepoint = .{ .savepoint = try savepointNamePlanFromGeneratedRangeAlloc(alloc, tokens, name_tokens) } },
            .release_savepoint => .{ .savepoint = .{ .release = try savepointNamePlanFromGeneratedRangeAlloc(alloc, tokens, name_tokens) } },
            .rollback_to_savepoint => .{ .savepoint = .{ .rollback_to = try savepointNamePlanFromGeneratedRangeAlloc(alloc, tokens, name_tokens) } },
            else => return error.UnsupportedSqlShape,
        };
        errdefer plan.deinit(alloc);
        return plan;
    }
    if (ast.mode_tokens) |mode_tokens| {
        if (mode_tokens.start != 1 or mode_tokens.end != end) return error.UnsupportedSqlShape;
        if (ast.kind == .constraint_mode) {
            var plan = try constraintModePlanFromGeneratedAstAlloc(alloc, tokens, ast);
            errdefer plan.deinit(alloc);
            return .{ .control = .{ .constraint_mode = plan } };
        }
        const starter: TransactionModeStarter = switch (ast.kind) {
            .set_transaction => .set_transaction,
            .start_transaction => .start_transaction,
            .begin => .begin,
            .commit,
            .rollback,
            .savepoint,
            .release_savepoint,
            .rollback_to_savepoint,
            .constraint_mode,
            => return error.UnsupportedSqlShape,
        };
        const mode = try transactionModePlanFromGeneratedRange(tokens, mode_tokens, starter);
        return .{ .control = .{ .transaction_mode = mode } };
    }
    const action: TransactionBoundaryAction = switch (ast.kind) {
        .start_transaction, .begin => .begin,
        .commit => .commit,
        .rollback => .rollback,
        .set_transaction,
        .constraint_mode,
        .savepoint,
        .release_savepoint,
        .rollback_to_savepoint,
        => return error.UnsupportedSqlShape,
    };
    return .{ .boundary = .{ .action = action } };
}

fn transactionModePlanFromGeneratedRange(
    tokens: []const grammar.Token,
    mode_tokens: generated_parser.GeneratedSqlTokenRange,
    starter: TransactionModeStarter,
) !TransactionModePlan {
    if (mode_tokens.start >= mode_tokens.end or mode_tokens.end > tokens.len) return error.UnsupportedSqlShape;
    var cursor = mode_tokens.start;
    switch (starter) {
        .set_transaction, .start_transaction => {
            if (!tokens[cursor].matchesKeyword("transaction")) return error.UnsupportedSqlShape;
            cursor += 1;
        },
        .begin => {
            if (tokens[cursor].matchesKeyword("transaction")) cursor += 1;
        },
    }

    var plan = TransactionModePlan{ .starter = starter };
    var saw_mode = false;
    while (cursor < mode_tokens.end) {
        if (tokens[cursor].kind == .comma) {
            cursor += 1;
            if (cursor >= mode_tokens.end) return error.UnsupportedSqlShape;
        }
        if (tokens[cursor].matchesKeyword("isolation")) {
            cursor += 1;
            if (cursor >= mode_tokens.end or !tokens[cursor].matchesKeyword("level")) return error.UnsupportedSqlShape;
            cursor += 1;
            if (plan.isolation_level != null) return error.UnsupportedSqlShape;
            plan.isolation_level = try generatedTransactionIsolationLevel(tokens, mode_tokens.end, &cursor);
            saw_mode = true;
        } else if (tokens[cursor].matchesKeyword("read")) {
            cursor += 1;
            if (plan.access_mode != null or cursor >= mode_tokens.end) return error.UnsupportedSqlShape;
            if (tokens[cursor].matchesKeyword("only")) {
                plan.access_mode = .read_only;
            } else if (tokens[cursor].matchesKeyword("write")) {
                plan.access_mode = .read_write;
            } else {
                return error.UnsupportedSqlShape;
            }
            cursor += 1;
            saw_mode = true;
        } else if (tokens[cursor].matchesKeyword("not")) {
            cursor += 1;
            if (plan.deferrable != null or cursor >= mode_tokens.end or !tokens[cursor].matchesKeyword("deferrable")) return error.UnsupportedSqlShape;
            cursor += 1;
            plan.deferrable = false;
            saw_mode = true;
        } else if (tokens[cursor].matchesKeyword("deferrable")) {
            if (plan.deferrable != null) return error.UnsupportedSqlShape;
            cursor += 1;
            plan.deferrable = true;
            saw_mode = true;
        } else {
            return error.UnsupportedSqlShape;
        }
    }
    if (!saw_mode) return error.UnsupportedSqlShape;
    return plan;
}

fn generatedTransactionIsolationLevel(
    tokens: []const grammar.Token,
    end: usize,
    cursor: *usize,
) !TransactionIsolationLevel {
    if (cursor.* >= end) return error.UnsupportedSqlShape;
    if (tokens[cursor.*].matchesKeyword("serializable")) {
        cursor.* += 1;
        return .serializable;
    }
    if (tokens[cursor.*].matchesKeyword("repeatable")) {
        cursor.* += 1;
        if (cursor.* >= end or !tokens[cursor.*].matchesKeyword("read")) return error.UnsupportedSqlShape;
        cursor.* += 1;
        return .repeatable_read;
    }
    if (tokens[cursor.*].matchesKeyword("read")) {
        cursor.* += 1;
        if (cursor.* >= end) return error.UnsupportedSqlShape;
        if (tokens[cursor.*].matchesKeyword("committed")) {
            cursor.* += 1;
            return .read_committed;
        }
        if (tokens[cursor.*].matchesKeyword("uncommitted")) {
            cursor.* += 1;
            return .read_uncommitted;
        }
    }
    return error.UnsupportedSqlShape;
}

fn savepointNamePlanFromGeneratedRangeAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) !SavepointNamePlan {
    const savepoint_name = try generatedSingleIdentifierText(tokens, range);
    return .{ .savepoint_name = try alloc.dupe(u8, savepoint_name) };
}

pub fn transactionBoundaryPlanFromGeneratedAst(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !DdlPlan {
    const plan = try transactionControlPlanFromGeneratedAstAlloc(alloc, tokens, ast);
    switch (plan) {
        .transaction_boundary => return plan,
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedTransactionAstSpans(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end == 0 or tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    switch (ast.kind) {
        .set_transaction => if (!tokens[0].matchesKeywordTag(.set)) return error.UnsupportedSqlShape,
        .constraint_mode => if (!tokens[0].matchesKeywordTag(.set)) return error.UnsupportedSqlShape,
        .start_transaction => if (!tokens[0].matchesKeyword("start")) return error.UnsupportedSqlShape,
        .begin => if (!tokens[0].matchesKeywordTag(.begin)) return error.UnsupportedSqlShape,
        .commit => if (!tokens[0].matchesKeywordTag(.commit) and !tokens[0].matchesKeywordTag(.end)) return error.UnsupportedSqlShape,
        .rollback => if (!tokens[0].matchesKeywordTag(.rollback)) return error.UnsupportedSqlShape,
        .savepoint => if (!tokens[0].matchesKeywordTag(.savepoint)) return error.UnsupportedSqlShape,
        .release_savepoint => if (!tokens[0].matchesKeywordTag(.release)) return error.UnsupportedSqlShape,
        .rollback_to_savepoint => if (!tokens[0].matchesKeywordTag(.rollback)) return error.UnsupportedSqlShape,
    }
    if (ast.boundary_tail_tokens != null and ast.mode_tokens != null) return error.UnsupportedSqlShape;
    if (ast.name_tokens != null and (ast.boundary_tail_tokens != null or ast.mode_tokens != null)) return error.UnsupportedSqlShape;
    if (ast.kind != .constraint_mode and (ast.constraint_all or ast.constraint_name_items.len != 0 or ast.constraint_mode != null)) {
        return error.UnsupportedSqlShape;
    }
    if (ast.name_tokens) |name| {
        try validateGeneratedSavepointNameRange(tokens, end, ast.kind, name);
        return;
    }
    if (ast.boundary_tail_tokens) |tail| {
        if (tail.start != 1 or tail.end != 2 or tail.end > end) return error.UnsupportedSqlShape;
        switch (ast.kind) {
            .set_transaction,
            .constraint_mode,
            .savepoint,
            .release_savepoint,
            .rollback_to_savepoint,
            => return error.UnsupportedSqlShape,
            .start_transaction => if (!tokens[tail.start].matchesKeyword("transaction")) return error.UnsupportedSqlShape,
            .begin, .commit, .rollback => {
                if (!tokens[tail.start].matchesKeyword("work") and !tokens[tail.start].matchesKeyword("transaction")) {
                    return error.UnsupportedSqlShape;
                }
            },
        }
    } else if (ast.kind == .constraint_mode) {
        try validateGeneratedConstraintModeAst(tokens, end, ast);
    } else if (ast.mode_tokens == null and (ast.kind == .set_transaction or ast.kind == .constraint_mode)) {
        return error.UnsupportedSqlShape;
    } else if (ast.mode_tokens == null and end > 1) {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedConstraintModeAst(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !void {
    const mode = ast.mode_tokens orelse return error.UnsupportedSqlShape;
    if (mode.start != 1 or mode.end != end or end <= 3 or !tokens[mode.start].matchesKeyword("constraints")) {
        return error.UnsupportedSqlShape;
    }
    if (ast.constraint_mode == null) return error.UnsupportedSqlShape;
    if (ast.constraint_all) {
        if (ast.constraint_name_items.len != 0) return error.UnsupportedSqlShape;
        if (!tokens[2].matchesKeyword("all")) return error.UnsupportedSqlShape;
        try validateGeneratedDdlRange(tokens, end, .{ .start = 2, .end = 3 });
        if (!generatedConstraintCheckModeToken(tokens, 3, ast.constraint_mode.?)) return error.UnsupportedSqlShape;
        return;
    }
    if (ast.constraint_name_items.len == 0) return error.UnsupportedSqlShape;
    var expected_start: usize = 2;
    for (ast.constraint_name_items, 0..) |item, item_index| {
        if (item.start != expected_start or item.end != item.start + 1) return error.UnsupportedSqlShape;
        try validateGeneratedDdlRange(tokens, end, item);
        if (tokens[item.start].kind != .identifier) return error.UnsupportedSqlShape;
        expected_start = item.end;
        if (item_index + 1 < ast.constraint_name_items.len) {
            if (expected_start >= end or tokens[expected_start].kind != .comma) return error.UnsupportedSqlShape;
            expected_start += 1;
        }
    }
    if (expected_start + 1 != end) return error.UnsupportedSqlShape;
    if (!generatedConstraintCheckModeToken(tokens, expected_start, ast.constraint_mode.?)) return error.UnsupportedSqlShape;
}

fn generatedConstraintCheckModeToken(
    tokens: []const grammar.Token,
    index: usize,
    mode: generated_parser.GeneratedSqlConstraintCheckMode,
) bool {
    if (index >= tokens.len) return false;
    return switch (mode) {
        .immediate => tokens[index].matchesKeyword("immediate"),
        .deferred => tokens[index].matchesKeyword("deferred"),
    };
}

fn constraintModePlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlTransactionAst,
) !ConstraintModePlan {
    if (ast.kind != .constraint_mode) return error.UnsupportedSqlShape;
    const mode = ast.constraint_mode orelse return error.UnsupportedSqlShape;
    var constraint_names: []const []const u8 = &.{};
    if (!ast.constraint_all) {
        if (ast.constraint_name_items.len == 0) return error.UnsupportedSqlShape;
        var names = try alloc.alloc([]const u8, ast.constraint_name_items.len);
        var names_len: usize = 0;
        errdefer {
            for (names[0..names_len]) |name| alloc.free(name);
            alloc.free(names);
        }
        for (ast.constraint_name_items, 0..) |item, index| {
            names[index] = try generatedSqlObjectIdentifierAlloc(alloc, tokens, item);
            names_len += 1;
        }
        constraint_names = names;
    } else if (ast.constraint_name_items.len != 0) {
        return error.UnsupportedSqlShape;
    }
    return .{
        .all = ast.constraint_all,
        .constraint_names = constraint_names,
        .mode = constraintCheckModeFromGenerated(mode),
    };
}

fn constraintCheckModeFromGenerated(mode: generated_parser.GeneratedSqlConstraintCheckMode) ConstraintCheckMode {
    return switch (mode) {
        .immediate => .immediate,
        .deferred => .deferred,
    };
}

fn validateGeneratedSavepointNameRange(
    tokens: []const grammar.Token,
    end: usize,
    kind: generated_parser.GeneratedSqlTransactionKind,
    name: generated_parser.GeneratedSqlTokenRange,
) !void {
    const expected_start: usize = switch (kind) {
        .savepoint => 1,
        .release_savepoint => if (end > 1 and tokens[1].matchesKeywordTag(.savepoint)) @as(usize, 2) else 1,
        .rollback_to_savepoint => blk: {
            if (end <= 1 or !tokens[1].matchesKeywordTag(.to)) return error.UnsupportedSqlShape;
            break :blk if (end > 2 and tokens[2].matchesKeywordTag(.savepoint)) @as(usize, 3) else 2;
        },
        else => return error.UnsupportedSqlShape,
    };
    if (name.start != expected_start or name.end != expected_start + 1 or name.end != end) return error.UnsupportedSqlShape;
    if (tokens[name.start].kind != .identifier) return error.UnsupportedSqlShape;
}

pub fn sessionDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) !DdlPlan {
    _ = try validateGeneratedSessionAstRanges(tokens, ast);
    return switch (ast.kind) {
        .set => {
            if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
            if (sessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, ast)) |plan| {
                return .{ .session_catalog = plan };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => return err,
                else => return err,
            }
        },
        .reset => {
            if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.reset)) return error.UnsupportedSqlShape;
            if (sessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, ast)) |plan| {
                return .{ .session_catalog = plan };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => return err,
                else => return err,
            }
        },
        .show => {
            if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.show)) return error.UnsupportedSqlShape;
            if (sessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, ast)) |plan| {
                return .{ .session_catalog = plan };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => return err,
                else => return err,
            }
        },
        .discard_all => blk: {
            if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.discard)) return error.UnsupportedSqlShape;
            break :blk .{ .session_catalog = try sessionCatalogPlanFromGeneratedAstAlloc(alloc, tokens, ast) };
        },
    };
}

fn generatedSessionCommandIsCatalogOwned(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) bool {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return false;
    if (end <= 1) return ast.kind == .discard_all;
    return switch (ast.kind) {
        .set => generatedSetSessionTailIsCatalogOwned(tokens, end),
        .reset, .show => generatedNamedSessionTailIsCatalogOwned(tokens, 1, end) or
            (ast.kind == .reset and tokens[1].matchesKeyword("all") and end == 2),
        .discard_all => true,
    };
}

fn generatedSetSessionTailIsCatalogOwned(tokens: []const grammar.Token, end: usize) bool {
    var index: usize = 1;
    if (index < end and tokens[index].matchesKeyword("local")) index += 1;
    if (index < end and tokens[index].matchesKeyword("session")) {
        if (index + 1 < end and tokens[index + 1].matchesKeyword("characteristics")) return true;
        index += 1;
    }
    return generatedNamedSessionTailIsCatalogOwned(tokens, index, end);
}

fn generatedNamedSessionTailIsCatalogOwned(tokens: []const grammar.Token, name_index: usize, end: usize) bool {
    if (name_index >= end or tokens[name_index].kind != .identifier) return false;
    const name = tokens[name_index].text;
    return std.ascii.eqlIgnoreCase(name, "search_path") or generatedSessionSettingKindForName(name) != null;
}

fn generatedSessionSettingKindForName(setting: []const u8) ?SessionSettingKind {
    if (std.mem.startsWith(u8, setting, "app.") and setting.len > "app.".len) return .app;
    if (std.ascii.eqlIgnoreCase(setting, "antfly.sync_level")) return .antfly;
    if (std.ascii.eqlIgnoreCase(setting, "statement_timeout") or
        std.ascii.eqlIgnoreCase(setting, "timezone") or
        std.ascii.eqlIgnoreCase(setting, "default_transaction_read_only") or
        std.ascii.eqlIgnoreCase(setting, "transaction_read_only"))
    {
        return .runtime;
    }
    return null;
}

fn validateGeneratedSessionAstRanges(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlSessionAst,
) !usize {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    if (end == 0) return error.UnsupportedSqlShape;
    if (tokens[0].source_start != ast.command_span.start or tokens[0].source_end != ast.command_span.end) {
        return error.UnsupportedSqlShape;
    }
    switch (ast.kind) {
        .set => {
            const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
            try validateGeneratedOptionalSessionRange(name, 1, end);
            if (ast.value_tokens) |value| {
                try validateGeneratedOptionalSessionRange(value, 1, end);
                if (name.end > value.start) return error.UnsupportedSqlShape;
            }
        },
        .reset, .show => {
            const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
            try validateGeneratedRequiredSessionRange(name, 1, end);
            if (ast.value_tokens != null) return error.UnsupportedSqlShape;
        },
        .discard_all => {
            if (ast.name_tokens != null or ast.value_tokens != null) return error.UnsupportedSqlShape;
        },
    }
    return end;
}

fn validateGeneratedOptionalSessionRange(
    range: generated_parser.GeneratedSqlTokenRange,
    min_start: usize,
    end: usize,
) !void {
    if (range.start < min_start or range.start > range.end or range.end > end) return error.UnsupportedSqlShape;
}

fn validateGeneratedRequiredSessionRange(
    range: generated_parser.GeneratedSqlTokenRange,
    min_start: usize,
    end: usize,
) !void {
    try validateGeneratedOptionalSessionRange(range, min_start, end);
    if (range.start == range.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedSessionCatalogPlanMatchesAst(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlSessionAst,
    plan: SessionCatalogPlan,
) !void {
    switch (plan) {
        .set_search_path => try validateGeneratedSetSessionNameAndValue(tokens, end, ast, "search_path", null),
        .set_setting => |set_setting| {
            if (std.ascii.eqlIgnoreCase(set_setting.name, "default_transaction_read_only") and ast.value_tokens == null) {
                return try validateGeneratedSetSessionCharacteristicsAst(tokens, end, ast);
            }
            try validateGeneratedSetSessionNameAndValue(tokens, end, ast, set_setting.name, set_setting.value);
        },
        .reset_setting => |reset_setting| try validateGeneratedSingleNameSessionAst(tokens, end, ast, .reset, reset_setting.name),
        .reset_search_path => try validateGeneratedSingleNameSessionAst(tokens, end, ast, .reset, "search_path"),
        .show_search_path => try validateGeneratedSingleNameSessionAst(tokens, end, ast, .show, "search_path"),
        .discard_all => switch (ast.kind) {
            .reset => try validateGeneratedSingleNameSessionAst(tokens, end, ast, .reset, "all"),
            .discard_all => {
                if (end != 2 or !tokens[0].matchesKeywordTag(.discard) or !tokens[1].matchesKeyword("all")) return error.UnsupportedSqlShape;
                if (ast.name_tokens != null or ast.value_tokens != null) return error.UnsupportedSqlShape;
            },
            else => return error.UnsupportedSqlShape,
        },
    }
}

fn validateGeneratedSetSessionNameAndValue(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlSessionAst,
    expected_name: []const u8,
    expected_single_value: ?[]const u8,
) !void {
    if (ast.kind != .set or end == 0 or !tokens[0].matchesKeywordTag(.set)) return error.UnsupportedSqlShape;
    const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
    const value = ast.value_tokens orelse return error.UnsupportedSqlShape;
    if (value.start < name.end or value.start >= value.end or value.end != end) return error.UnsupportedSqlShape;
    if (name.start < 1 or name.end <= name.start or name.end > value.start) return error.UnsupportedSqlShape;
    if (!std.ascii.eqlIgnoreCase(tokens[name.end - 1].text, expected_name)) return error.UnsupportedSqlShape;
    if (expected_single_value) |expected_value| {
        if (value.end != value.start + 1) return error.UnsupportedSqlShape;
        if (!std.mem.eql(u8, tokens[value.start].text, expected_value)) return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedSetSessionCharacteristicsAst(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlSessionAst,
) !void {
    if (ast.kind != .set or end < 5 or ast.value_tokens != null) return error.UnsupportedSqlShape;
    const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
    if (name.start != 1 or name.end != end - 1) return error.UnsupportedSqlShape;
    if (!tokens[0].matchesKeywordTag(.set) or
        !tokens[1].matchesKeyword("session") or
        !tokens[2].matchesKeyword("characteristics") or
        !tokens[3].matchesKeywordTag(.as))
    {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedSingleNameSessionAst(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlSessionAst,
    expected_kind: generated_parser.GeneratedSqlSessionKind,
    expected_name: []const u8,
) !void {
    if (ast.kind != expected_kind) return error.UnsupportedSqlShape;
    if (end == 0 or ast.value_tokens != null) return error.UnsupportedSqlShape;
    const name = ast.name_tokens orelse return error.UnsupportedSqlShape;
    if (name.start != 1 or name.end != end or name.start >= name.end) return error.UnsupportedSqlShape;
    if (!std.ascii.eqlIgnoreCase(tokens[name.end - 1].text, expected_name)) return error.UnsupportedSqlShape;
}

pub fn simpleDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !DdlPlan {
    try validateGeneratedDdlAstSpans(tokens, ast);
    return switch (ast.kind) {
        .create_database => .{ .database_catalog = .{ .create = try createDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .create_schema => try createSchemaNamespacePlanFromGeneratedDdlAstAsDdlPlanAlloc(alloc, tokens, ast),
        .create_extension => try createExtensionPlanFromGeneratedDdlAstAsDdlPlanAlloc(alloc, tokens, ast),
        .alter_database => .{ .database_catalog = .{ .alter = try alterDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .alter_extension => .{ .extension_catalog = .{ .update = try updateExtensionPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .alter_schema => .{ .schema_namespace_catalog = .{ .rename = try renameSchemaNamespacePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_database => .{ .database_catalog = .{ .drop = try dropDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_schema => .{ .schema_namespace_catalog = .{ .drop = try dropSchemaNamespacePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_extension => .{ .extension_catalog = .{ .drop = try dropExtensionPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        else => error.UnsupportedSqlShape,
    };
}

pub fn runtimeDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    try validateGeneratedDdlAstSpans(tokens, ast);
    var generated_options = options;
    generated_options.column_definition_options.expression_options.generated_scalar_subquery_defaults = ast.scalar_subquery_default_items;
    generated_options.column_definition_options.expression_options.generated_scalar_subquery_full_tokens = tokens;
    generated_options.column_definition_options.expression_options.generated_scalar_subquery_token_offset = 0;
    var pos: usize = 0;
    return switch (ast.kind) {
        .create_table => blk: {
            if (generatedCreateTableUsesRelationLifetime(tokens, ast)) {
                var lifetime_pos: usize = if (ast.replace_existing) 3 else 1;
                break :blk .{ .relation_lifetime = try parseGeneratedRelationLifetimePlanAlloc(alloc, tokens, &lifetime_pos, ast, generated_options.column_definition_options) };
            }
            if (generatedCreateTableMayUseIdentityAllocator(tokens, ast)) {
                break :blk .{ .identity_allocator_catalog = try identityAllocatorPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, generated_options.column_definition_options) };
            }
            const create_table_tail_start = generatedCreateTableStatementTailStart(tokens, ast) orelse return error.UnsupportedSqlShape;
            const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
            const create_table_tail = tokens[create_table_tail_start..end];
            var create_table_tail_options = generated_options.column_definition_options;
            create_table_tail_options.expression_options.generated_scalar_subquery_token_offset = create_table_tail_start;
            if (ast.create_table_like_source_tokens != null) {
                break :blk .{ .table_clone = try tableClonePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) };
            }
            var create_partition_pos: usize = 0;
            if (createTablePartitionPlanValidatedFromGeneratedDdlAstAlloc(alloc, tokens, ast, create_table_tail, &create_partition_pos)) |partition| {
                break :blk .{ .table_partition_catalog = .{ .create_partition = partition } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            var partitioned_pos: usize = 0;
            if (createPartitionedTablePlanValidatedFromGeneratedDdlAstAlloc(alloc, tokens, ast, create_table_tail, &partitioned_pos, create_table_tail_options)) |partitioned| {
                break :blk .{ .table_partition_catalog = .{ .create_partitioned = partitioned } };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            if (generatedCreateTableAstHasDocumentTableMetadata(tokens, ast)) {
                break :blk .{ .create_table = try createTablePlanFromGeneratedDocumentAstAlloc(alloc, tokens, ast) };
            }
            var create_table = try relationalCreateTablePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, create_table_tail, &pos, create_table_tail_options);
            create_table.replace_existing = ast.replace_existing;
            break :blk .{ .create_table = create_table };
        },
        .create_view,
        .alter_view,
        .drop_view,
        => try viewCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_materialized_view,
        .drop_materialized_view,
        .refresh_materialized_view,
        => try materializedViewCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_domain,
        .alter_domain,
        .drop_domain,
        => try domainCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_sequence,
        .alter_sequence,
        .drop_sequence,
        => try sequenceCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_enum_type,
        .alter_enum_type,
        .drop_enum_type,
        => try enumTypeCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_tablespace,
        .alter_tablespace,
        .drop_tablespace,
        => try tablespaceCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_publication,
        .alter_publication,
        .drop_publication,
        .create_subscription,
        .alter_subscription,
        .drop_subscription,
        => try logicalReplicationCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .comment => try commentMetadataPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .security_label => try securityLabelPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .grant,
        .revoke,
        => try privilegeDdlPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .alter_default_privileges => .{ .authorization_catalog = .{ .alter_default_privileges = try defaultPrivilegeChangePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .create_policy,
        .alter_policy,
        .drop_policy,
        => try rowSecurityPolicyCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_function,
        .create_procedure,
        .drop_function,
        .drop_procedure,
        => try routineCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_role,
        .alter_role,
        .drop_role,
        => try authorizationCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_collation,
        .alter_collation,
        .drop_collation,
        .create_operator,
        .drop_operator,
        .create_aggregate,
        .drop_aggregate,
        .create_cast,
        .drop_cast,
        => try typeSystemCatalogPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options),
        .create_index => .{ .create_index = try createIndexPlanFromGeneratedAstAlloc(alloc, tokens, ast, options.create_index_options) },
        .alter_table => blk: {
            if (generatedAlterTableUsesRowSecurityRuntimeBoundary(tokens, ast)) {
                break :blk .{ .row_security_catalog = .{ .alter_table = try rowSecurityAlterTablePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } };
            }
            if (tablePartitionPlanFromGeneratedAlterTableAstAlloc(alloc, tokens, ast)) |partition| {
                break :blk .{ .table_partition_catalog = partition };
            } else |err| switch (err) {
                error.UnsupportedSqlShape => {},
                else => return err,
            }
            break :blk .{ .alter_table = try alterTablePlanFromGeneratedAstAlloc(alloc, tokens, ast, generated_options.column_definition_options) };
        },
        .drop_table => .{ .drop_table = try dropTablePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) },
        .drop_index => .{ .drop_index = try dropIndexPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) },
        else => try simpleDdlPlanFromGeneratedAstAlloc(alloc, tokens, ast),
    };
}

pub fn logicalDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !binder.LogicalSqlPlan {
    var generated_plan = try runtimeDdlPlanFromGeneratedAstAlloc(alloc, tokens, ast, options);
    errdefer generated_plan.deinit(alloc);
    return logicalPlanFromDdlPlan(&generated_plan);
}

fn logicalPlanFromDdlPlan(plan: *DdlPlan) !binder.LogicalSqlPlan {
    const logical: binder.LogicalSqlPlan = switch (plan.*) {
        .adapter_noop => |payload| .{ .other_ddl = .{ .adapter_noop = payload } },
        .session_catalog => |payload| .{ .session = payload },
        .create_table => |payload| .{ .table_ddl = .{ .create_table = payload } },
        .table_clone => |payload| .{ .table_ddl = .{ .table_clone = payload } },
        .view_catalog => |payload| .{ .table_ddl = .{ .view_catalog = payload } },
        .materialized_view_catalog => |payload| .{ .table_ddl = .{ .materialized_view_catalog = payload } },
        .relation_lifetime => |payload| .{ .table_ddl = .{ .relation_lifetime = payload } },
        .enum_type_catalog => |payload| .{ .catalog_ddl = .{ .enum_type_catalog = payload } },
        .domain_catalog => |payload| .{ .catalog_ddl = .{ .domain_catalog = payload } },
        .sequence_catalog => |payload| .{ .catalog_ddl = .{ .sequence_catalog = payload } },
        .identity_allocator_catalog => |payload| .{ .catalog_ddl = .{ .identity_allocator_catalog = payload } },
        .schema_namespace_catalog => |payload| .{ .catalog_ddl = .{ .schema_namespace_catalog = payload } },
        .extension_catalog => |payload| .{ .extension = payload },
        .function_catalog => |payload| .{ .routine = .{ .function_catalog = payload } },
        .trigger_catalog => |payload| .{ .routine = .{ .trigger_catalog = payload } },
        .procedure_call => |payload| .{ .routine = .{ .procedure_call = payload } },
        .authorization_catalog => |payload| .{ .auth = .{ .authorization_catalog = payload } },
        .bulk_io => |payload| .{ .bulk_io = payload },
        .table_partition_catalog => |payload| .{ .table_ddl = .{ .table_partition_catalog = payload } },
        .row_security_catalog => |payload| .{ .auth = .{ .row_security_catalog = payload } },
        .database_catalog => |payload| .{ .catalog_ddl = .{ .database_catalog = payload } },
        .tablespace_catalog => |payload| .{ .catalog_ddl = .{ .tablespace_catalog = payload } },
        .notification_channel => |payload| .{ .notification = payload },
        .logical_replication => |payload| .{ .catalog_ddl = .{ .logical_replication = payload } },
        .type_system_catalog => |payload| .{ .catalog_ddl = .{ .type_system_catalog = payload } },
        .maintenance_job => |payload| .{ .maintenance = payload },
        .prepared_statement => |payload| .{ .prepared_statement = payload },
        .prepared_transaction => |payload| .{ .transaction = .{ .prepared = payload } },
        .cursor_portal => |payload| .{ .cursor = payload },
        .savepoint_transaction => |payload| .{ .transaction = .{ .savepoint = payload } },
        .comment_metadata => |payload| .{ .catalog_ddl = .{ .comment_metadata = payload } },
        .security_label => |payload| .{ .catalog_ddl = .{ .security_label = payload } },
        .transaction_boundary => |payload| .{ .transaction = .{ .boundary = payload } },
        .transaction_control => |payload| .{ .transaction = .{ .control = payload } },
        .create_index => |payload| .{ .table_ddl = .{ .create_index = payload } },
        .drop_index => |payload| .{ .table_ddl = .{ .drop_index = payload } },
        .drop_table => |payload| .{ .table_ddl = .{ .drop_table = payload } },
        .alter_table => |payload| .{ .table_ddl = .{ .alter_table = payload } },
        .create_update_policy => |payload| .{ .table_ddl = .{ .create_update_policy = payload } },
    };
    plan.* = undefined;
    return logical;
}

fn simpleLogicalDdlPlanFromGeneratedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !binder.LogicalSqlPlan {
    try validateGeneratedDdlAstSpans(tokens, ast);
    return switch (ast.kind) {
        .create_database => .{ .catalog_ddl = .{ .database_catalog = .{ .create = try createDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } } },
        .create_schema => try createSchemaNamespaceLogicalPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast),
        .create_extension => try createExtensionLogicalPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast),
        .alter_database => .{ .catalog_ddl = .{ .database_catalog = .{ .alter = try alterDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } } },
        .alter_extension => .{ .extension = .{ .update = try updateExtensionPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .alter_schema => .{ .catalog_ddl = .{ .schema_namespace_catalog = .{ .rename = try renameSchemaNamespacePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } } },
        .drop_database => .{ .catalog_ddl = .{ .database_catalog = .{ .drop = try dropDatabasePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } } },
        .drop_schema => .{ .catalog_ddl = .{ .schema_namespace_catalog = .{ .drop = try dropSchemaNamespacePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } } },
        .drop_extension => .{ .extension = .{ .drop = try dropExtensionPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .alter_default_privileges => .{ .auth = .{ .authorization_catalog = .{ .alter_default_privileges = try defaultPrivilegeChangePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } } },
        else => error.UnsupportedSqlShape,
    };
}

fn generatedDdlUsesRuntimeBoundary(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) bool {
    return switch (ast.kind) {
        .create_database,
        .create_schema,
        .create_view,
        .create_materialized_view,
        .create_domain,
        .create_sequence,
        .create_enum_type,
        .create_tablespace,
        .create_extension,
        .alter_database,
        .alter_extension,
        .alter_schema,
        .alter_tablespace,
        .alter_view,
        .alter_domain,
        .alter_sequence,
        .alter_enum_type,
        .drop_table,
        .drop_view,
        .drop_materialized_view,
        .drop_domain,
        .drop_sequence,
        .drop_enum_type,
        .drop_tablespace,
        .create_publication,
        .alter_publication,
        .drop_publication,
        .create_subscription,
        .alter_subscription,
        .drop_subscription,
        .create_function,
        .create_procedure,
        .drop_function,
        .drop_procedure,
        .create_role,
        .alter_role,
        .drop_role,
        .create_collation,
        .alter_collation,
        .drop_collation,
        .create_operator,
        .drop_operator,
        .create_aggregate,
        .drop_aggregate,
        .create_cast,
        .drop_cast,
        .create_policy,
        .alter_policy,
        .drop_policy,
        .comment,
        .security_label,
        .alter_default_privileges,
        .grant,
        .revoke,
        .drop_index,
        .drop_schema,
        .drop_database,
        .drop_extension,
        .refresh_materialized_view,
        => true,
        .create_table => generatedCreateTableUsesRuntimeBoundary(tokens, ast),
        .create_index => generatedCreateIndexUsesRuntimeBoundary(tokens, ast),
        .alter_table => generatedAlterTableUsesRowSecurityRuntimeBoundary(tokens, ast) or generatedAlterTableUsesRuntimeBoundary(tokens, ast),
        .relation_population,
        .create_graph_index,
        .create_graph_metric,
        => false,
    };
}

fn routineCatalogPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    _ = options;
    try validateGeneratedRoutineDdlAst(tokens, ast);
    var plan: DdlPlan = switch (ast.kind) {
        .create_function, .create_procedure => .{ .function_catalog = .{ .create = try createRoutinePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_function, .drop_procedure => .{ .function_catalog = .{ .drop = try dropRoutinePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        else => return error.UnsupportedSqlShape,
    };
    errdefer plan.deinit(alloc);
    switch (plan) {
        .function_catalog => |function| switch (ast.kind) {
            .create_function, .create_procedure => switch (function) {
                .create => |create| try validateGeneratedCreateRoutinePlan(alloc, tokens, ast, create),
                else => return error.UnsupportedSqlShape,
            },
            .drop_function, .drop_procedure => switch (function) {
                .drop => |drop| try validateGeneratedDropRoutinePlan(alloc, tokens, ast, drop),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn createRoutinePlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !CreateRoutinePlan {
    const metadata = ast.routine_metadata orelse return error.UnsupportedSqlShape;
    const kind = try generatedRoutineKindFromDdlKind(ast.kind);
    var plan = CreateRoutinePlan{
        .kind = kind,
        .routine_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .replace_existing = ast.replace_existing,
        .argument_count = metadata.argument_items.count,
    };
    errdefer plan.deinit(alloc);

    plan.returns_type = try generatedRoutineOptionalObjectIdentifierAlloc(alloc, tokens, metadata.returns_type_tokens);
    plan.language = try generatedRoutineOptionalIdentifierAlloc(alloc, tokens, metadata.language_tokens);
    plan.volatility = try generatedRoutineVolatility(tokens, metadata.volatility_tokens);
    plan.security = try generatedRoutineSecurity(tokens, metadata.security_tokens);
    plan.null_input = try generatedRoutineNullInput(tokens, metadata.null_input_tokens);
    plan.parallel_safety = try generatedRoutineParallelSafety(tokens, metadata.parallel_safety_tokens);
    plan.leakproof = try generatedRoutineFlag(tokens, metadata.leakproof_tokens, "leakproof");
    plan.window = try generatedRoutineFlag(tokens, metadata.window_tokens, "window");
    plan.support_function = try generatedRoutineOptionalObjectIdentifierAlloc(alloc, tokens, metadata.support_function_tokens);
    plan.transform_types = try generatedRoutineTransformTypesAlloc(alloc, tokens, &metadata.transform_type_items);
    plan.settings = try generatedRoutineSettingsAlloc(alloc, tokens, &metadata.setting_items);
    plan.cost = try generatedRoutineOptionalPositiveNumberAlloc(alloc, tokens, metadata.cost_tokens);
    plan.rows = try generatedRoutineOptionalPositiveNumberAlloc(alloc, tokens, metadata.rows_tokens);
    plan.body = try generatedRoutineBodyPlanAlloc(alloc, tokens, metadata, kind, plan.language, plan.returns_type);
    if (kind == .function and plan.returns_type == null) return error.UnsupportedSqlShape;
    return plan;
}

fn dropRoutinePlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !DropRoutinePlan {
    const metadata = ast.routine_metadata orelse return error.UnsupportedSqlShape;
    const kind = try generatedRoutineKindFromDdlKind(ast.kind);
    return .{
        .kind = kind,
        .routine_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .if_exists = ast.if_exists,
        .argument_count = metadata.argument_items.count,
        .cascade = ast.cascade,
    };
}

fn generatedRoutineKindFromDdlKind(kind: generated_parser.GeneratedSqlDdlKind) !RoutineKind {
    return switch (kind) {
        .create_function, .drop_function => .function,
        .create_procedure, .drop_procedure => .procedure,
        else => error.UnsupportedSqlShape,
    };
}

fn generatedRoutineOptionalIdentifierAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
) !?[]const u8 {
    const range = maybe_range orelse return null;
    return try generatedIdentifierAlloc(alloc, tokens, range);
}

fn generatedRoutineOptionalObjectIdentifierAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
) !?[]const u8 {
    const range = maybe_range orelse return null;
    return try generatedSqlObjectIdentifierAlloc(alloc, tokens, range);
}

fn generatedRoutineVolatility(tokens: []const grammar.Token, maybe_range: ?generated_parser.GeneratedSqlTokenRange) !?RoutineVolatility {
    const range = maybe_range orelse return null;
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].matchesKeyword("immutable")) return .immutable;
    if (tokens[range.start].matchesKeyword("stable")) return .stable;
    if (tokens[range.start].matchesKeyword("volatile")) return .@"volatile";
    return error.UnsupportedSqlShape;
}

fn generatedRoutineSecurity(tokens: []const grammar.Token, maybe_range: ?generated_parser.GeneratedSqlTokenRange) !?RoutineSecurity {
    const range = maybe_range orelse return null;
    if (range.end > tokens.len or range.start >= range.end) return error.UnsupportedSqlShape;
    const tail_index = if (range.end == range.start + 2 and tokens[range.start].matchesKeyword("security"))
        range.start + 1
    else if (range.end == range.start + 3 and tokens[range.start].matchesKeyword("external") and tokens[range.start + 1].matchesKeyword("security"))
        range.start + 2
    else
        return error.UnsupportedSqlShape;
    if (tokens[tail_index].matchesKeyword("definer")) return .definer;
    if (tokens[tail_index].matchesKeyword("invoker")) return .invoker;
    return error.UnsupportedSqlShape;
}

fn generatedRoutineNullInput(tokens: []const grammar.Token, maybe_range: ?generated_parser.GeneratedSqlTokenRange) !?RoutineNullInput {
    const range = maybe_range orelse return null;
    if (range.end > tokens.len or range.start >= range.end) return error.UnsupportedSqlShape;
    if (range.end == range.start + 1 and tokens[range.start].matchesKeyword("strict")) return .returns_null;
    if (range.end == range.start + 4 and
        tokens[range.start].matchesKeyword("called") and
        tokens[range.start + 1].matchesKeyword("on") and
        tokens[range.start + 2].matchesKeyword("null") and
        tokens[range.start + 3].matchesKeyword("input"))
    {
        return .called;
    }
    if (range.end == range.start + 5 and
        tokens[range.start].matchesKeyword("returns") and
        tokens[range.start + 1].matchesKeyword("null") and
        tokens[range.start + 2].matchesKeyword("on") and
        tokens[range.start + 3].matchesKeyword("null") and
        tokens[range.start + 4].matchesKeyword("input"))
    {
        return .returns_null;
    }
    return error.UnsupportedSqlShape;
}

fn generatedRoutineParallelSafety(tokens: []const grammar.Token, maybe_range: ?generated_parser.GeneratedSqlTokenRange) !?RoutineParallelSafety {
    const range = maybe_range orelse return null;
    if (range.end != range.start + 2 or range.end > tokens.len or !tokens[range.start].matchesKeyword("parallel")) return error.UnsupportedSqlShape;
    if (tokens[range.start + 1].matchesKeyword("safe")) return .safe;
    if (tokens[range.start + 1].matchesKeyword("restricted")) return .restricted;
    if (tokens[range.start + 1].matchesKeyword("unsafe")) return .unsafe;
    return error.UnsupportedSqlShape;
}

fn generatedRoutineFlag(tokens: []const grammar.Token, maybe_range: ?generated_parser.GeneratedSqlTokenRange, keyword: []const u8) !bool {
    const range = maybe_range orelse return false;
    if (range.end != range.start + 1 or range.end > tokens.len or !tokens[range.start].matchesKeyword(keyword)) return error.UnsupportedSqlShape;
    return true;
}

fn generatedRoutineOptionalPositiveNumberAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
) !?[]const u8 {
    const range = maybe_range orelse return null;
    if (range.end != range.start + 1 or range.end > tokens.len or tokens[range.start].kind != .number) return error.UnsupportedSqlShape;
    const parsed = std.fmt.parseFloat(f64, tokens[range.start].text) catch return error.UnsupportedSqlShape;
    if (!(parsed > 0)) return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, tokens[range.start].text);
}

fn generatedRoutineTransformTypesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    items: *const generated_parser.GeneratedSqlListAst,
) ![]const []const u8 {
    if (items.count == 0) {
        try validateGeneratedEmptyListAst(items);
        return &.{};
    }
    if (items.count != items.items.len or items.expression_items.len != 0 or items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or items.direction_items.len != 0 or items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or items.nulls_order_items.len != 0 or items.nulls_orders.len != 0 or
        items.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
    var values = try alloc.alloc([]const u8, items.items.len);
    var len: usize = 0;
    errdefer {
        for (values[0..len]) |value| alloc.free(value);
        alloc.free(values);
    }
    for (items.items) |item| {
        values[len] = try generatedSqlObjectIdentifierAlloc(alloc, tokens, item);
        len += 1;
    }
    return values;
}

fn generatedRoutineSettingsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    items: *const generated_parser.GeneratedSqlListAst,
) ![]const RoutineSetting {
    if (items.count == 0) {
        try validateGeneratedEmptyListAst(items);
        return &.{};
    }
    if (items.count != items.items.len or items.expression_items.len != 0 or items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or items.direction_items.len != 0 or items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or items.nulls_order_items.len != 0 or items.nulls_orders.len != 0 or
        items.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
    var settings = try alloc.alloc(RoutineSetting, items.items.len);
    var len: usize = 0;
    errdefer {
        for (settings[0..len]) |*setting| setting.deinit(alloc);
        alloc.free(settings);
    }
    for (items.items) |item| {
        settings[len] = try generatedRoutineSettingAlloc(alloc, tokens, item);
        len += 1;
    }
    return settings;
}

fn generatedRoutineSettingAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
) !RoutineSetting {
    if (item.end > tokens.len or item.start + 3 > item.end) return error.UnsupportedSqlShape;
    if (!tokens[item.start].matchesKeyword("set") or tokens[item.start + 1].kind != .identifier) return error.UnsupportedSqlShape;
    var setting = RoutineSetting{
        .name = try alloc.dupe(u8, tokens[item.start + 1].text),
    };
    errdefer setting.deinit(alloc);

    var index = item.start + 2;
    if (tokens[index].matchesKeyword("from")) {
        if (item.end != index + 2 or !tokens[index + 1].matchesKeyword("current")) return error.UnsupportedSqlShape;
        setting.from_current = true;
        return setting;
    }
    if (tokens[index].kind == .eq or tokens[index].matchesKeyword("to")) {
        index += 1;
    } else {
        return error.UnsupportedSqlShape;
    }

    var values = std.ArrayListUnmanaged([]const u8).empty;
    var values_transferred = false;
    errdefer if (!values_transferred) {
        for (values.items) |value| alloc.free(value);
        values.deinit(alloc);
    };
    while (true) {
        if (index >= item.end) return error.UnsupportedSqlShape;
        const value_token = tokens[index];
        if (value_token.kind != .identifier and value_token.kind != .string and value_token.kind != .number) return error.UnsupportedSqlShape;
        const value = try alloc.dupe(u8, value_token.text);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value);
        try values.append(alloc, value);
        value_transferred = true;
        index += 1;
        if (index == item.end) break;
        if (tokens[index].kind != .comma) return error.UnsupportedSqlShape;
        index += 1;
    }
    setting.values = try values.toOwnedSlice(alloc);
    values_transferred = true;
    return setting;
}

fn generatedRoutineBodyPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    metadata: *const generated_parser.GeneratedSqlRoutineAst,
    kind: RoutineKind,
    language: ?[]const u8,
    returns_type: ?[]const u8,
) !?RoutineBodyPlan {
    const body_range = metadata.body_tokens orelse return null;
    if (body_range.end != body_range.start + 1 or body_range.end > tokens.len or tokens[body_range.start].kind != .string) return error.UnsupportedSqlShape;
    const body_kind = metadata.body_kind orelse return error.UnsupportedSqlShape;
    const body_hook = metadata.body_hook orelse return error.UnsupportedSqlShape;
    if (metadata.body_perform_call_count != metadata.body_perform_calls.len) return error.UnsupportedSqlShape;
    switch (body_kind) {
        .plpgsql_trigger, .plpgsql_procedure => return try generatedPlpgsqlRoutineBodyPlanAlloc(
            alloc,
            metadata,
            kind,
            language,
            returns_type,
            body_kind,
            body_hook,
        ),
        .sql_expression => return try generatedSqlRoutineBodyPlanAlloc(
            alloc,
            metadata,
            kind,
            language,
            returns_type,
            body_kind,
            body_hook,
            tokens,
        ),
    }
}

fn generatedSqlRoutineBodyPlanAlloc(
    alloc: std.mem.Allocator,
    metadata: *const generated_parser.GeneratedSqlRoutineAst,
    kind: RoutineKind,
    language: ?[]const u8,
    returns_type: ?[]const u8,
    body_kind: generated_parser.GeneratedSqlRoutineBodyKind,
    body_hook: generated_parser.GeneratedSqlRoutineExecutionHook,
    tokens: []const grammar.Token,
) !RoutineBodyPlan {
    if (kind != .function) return error.UnsupportedSqlShape;
    if (body_kind != .sql_expression or body_hook != .expression) return error.UnsupportedSqlShape;
    const lang = language orelse return error.UnsupportedSqlShape;
    if (!std.ascii.eqlIgnoreCase(lang, "sql")) return error.UnsupportedSqlShape;
    if (returns_type == null) return error.UnsupportedSqlShape;
    const expression_range = metadata.body_expression_tokens orelse return error.UnsupportedSqlShape;
    const expression_tokens = metadata.body_expression.tokens orelse return error.UnsupportedSqlShape;
    if (!generatedDdlTokenRangeEqual(expression_range, expression_tokens)) return error.UnsupportedSqlShape;
    if (expression_range.start != 0 or expression_range.end != metadata.body_sql_tokens.len or expression_range.start >= expression_range.end) return error.UnsupportedSqlShape;

    var expression = (try generatedCreateIndexRowExpressionAlloc(alloc, metadata.body_sql_tokens, metadata.body_expression)) orelse return error.UnsupportedSqlShape;
    errdefer runtime_schema.freeRelationalRowsExpression(alloc, expression);
    const argument_names = try generatedRoutineArgumentNamesAlloc(alloc, tokens, &metadata.argument_items);
    defer freeGeneratedRoutineArgumentNames(alloc, argument_names);
    try generatedRewriteRoutineBodyExpressionArguments(alloc, &expression, metadata.argument_items.count, argument_names);
    return .{
        .kind = .sql_expression,
        .hook = .expression,
        .expression = expression,
    };
}

fn generatedPlpgsqlRoutineBodyPlanAlloc(
    alloc: std.mem.Allocator,
    metadata: *const generated_parser.GeneratedSqlRoutineAst,
    kind: RoutineKind,
    language: ?[]const u8,
    returns_type: ?[]const u8,
    body_kind: generated_parser.GeneratedSqlRoutineBodyKind,
    body_hook: generated_parser.GeneratedSqlRoutineExecutionHook,
) !RoutineBodyPlan {
    const lang = language orelse return error.UnsupportedSqlShape;
    if (!std.ascii.eqlIgnoreCase(lang, "plpgsql")) return error.UnsupportedSqlShape;
    const plan_kind: RoutineBodyKind = switch (body_kind) {
        .plpgsql_trigger => blk: {
            if (kind != .function or metadata.argument_items.count != 0) return error.UnsupportedSqlShape;
            const returns = returns_type orelse return error.UnsupportedSqlShape;
            if (!std.ascii.eqlIgnoreCase(returns, "trigger")) return error.UnsupportedSqlShape;
            break :blk .plpgsql_trigger;
        },
        .plpgsql_procedure => blk: {
            if (kind != .procedure or returns_type != null or metadata.argument_items.count != 0) return error.UnsupportedSqlShape;
            break :blk .plpgsql_procedure;
        },
        .sql_expression => return error.UnsupportedSqlShape,
    };
    const plan_hook = try generatedRoutineExecutionHook(body_hook);
    switch (plan_kind) {
        .plpgsql_trigger => switch (plan_hook) {
            .trigger_return_new, .trigger_return_old, .trigger_return_null => {},
            else => return error.UnsupportedSqlShape,
        },
        .plpgsql_procedure => if (plan_hook != .procedure_noop) return error.UnsupportedSqlShape,
        .sql_expression => return error.UnsupportedSqlShape,
    }
    try validateGeneratedPlpgsqlRoutineBodyTokenPayload(metadata.body_sql_tokens, body_kind, body_hook, metadata.body_perform_call_count);
    return .{
        .kind = plan_kind,
        .hook = plan_hook,
        .perform_calls = try generatedRoutinePerformCallsAlloc(alloc, metadata.body_perform_calls),
    };
}

fn validateGeneratedPlpgsqlRoutineBodyTokenPayload(
    tokens: []const grammar.Token,
    body_kind: generated_parser.GeneratedSqlRoutineBodyKind,
    body_hook: generated_parser.GeneratedSqlRoutineExecutionHook,
    perform_call_count: usize,
) !void {
    if (tokens.len == 0) return error.UnsupportedSqlShape;
    var perform_count: usize = 0;
    var return_hook: ?generated_parser.GeneratedSqlRoutineExecutionHook = null;
    for (tokens, 0..) |token, index| {
        if (token.matchesKeyword("perform")) perform_count += 1;
        if (!token.matchesKeyword("return")) continue;
        if (return_hook != null or index + 1 >= tokens.len) return error.UnsupportedSqlShape;
        return_hook = if (tokens[index + 1].matchesKeyword("new"))
            .trigger_return_new
        else if (tokens[index + 1].matchesKeyword("old"))
            .trigger_return_old
        else if (tokens[index + 1].matchesKeyword("null"))
            .trigger_return_null
        else
            return error.UnsupportedSqlShape;
    }
    if (perform_count != perform_call_count) return error.UnsupportedSqlShape;
    switch (body_kind) {
        .plpgsql_trigger => {
            const hook = return_hook orelse return error.UnsupportedSqlShape;
            if (hook != body_hook) return error.UnsupportedSqlShape;
        },
        .plpgsql_procedure => {
            if (return_hook != null or body_hook != .procedure_noop) return error.UnsupportedSqlShape;
        },
        .sql_expression => return error.UnsupportedSqlShape,
    }
}

fn generatedRoutineExecutionHook(generated: generated_parser.GeneratedSqlRoutineExecutionHook) !RoutineExecutionHook {
    return switch (generated) {
        .expression => .expression,
        .trigger_return_new => .trigger_return_new,
        .trigger_return_old => .trigger_return_old,
        .trigger_return_null => .trigger_return_null,
        .procedure_noop => .procedure_noop,
    };
}

fn generatedRoutinePerformCallsAlloc(
    alloc: std.mem.Allocator,
    calls: []const generated_parser.GeneratedSqlRoutinePerformCallAst,
) ![]const RoutinePerformCall {
    if (calls.len == 0) return &.{};
    const out = try alloc.alloc(RoutinePerformCall, calls.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |*call| call.deinit(alloc);
        alloc.free(out);
    }
    for (calls, out) |call, *target| {
        target.* = .{
            .routine_name = try alloc.dupe(u8, call.routine_name),
            .argument_json = try cloneStringSlice(alloc, call.argument_json),
        };
        initialized += 1;
    }
    return out;
}

fn generatedRoutineNamedArgumentIndex(argument_names: []const []const u8, text: []const u8) ?usize {
    for (argument_names, 0..) |name, i| {
        if (name.len != 0 and std.ascii.eqlIgnoreCase(name, text)) return i + 1;
    }
    return null;
}

fn generatedRoutinePlaceholderCastType(text: []const u8) ?[]const u8 {
    const trimmed = std.mem.trim(u8, text, " \t\r\n");
    if (!std.mem.startsWith(u8, trimmed, "$")) return null;
    var end: usize = 1;
    while (end < trimmed.len and trimmed[end] >= '0' and trimmed[end] <= '9') : (end += 1) {}
    if (end == 1 or end == trimmed.len) return null;
    if (!std.mem.startsWith(u8, trimmed[end..], "::")) return null;
    const cast_type = trimmed[end + "::".len ..];
    if (cast_type.len == 0) return null;
    return cast_type;
}

fn generatedDdlRoutineCastType(text: []const u8) ?runtime_schema.RelationalRowsExpressionCastType {
    if (std.ascii.eqlIgnoreCase(text, "text") or std.ascii.eqlIgnoreCase(text, "varchar") or std.ascii.eqlIgnoreCase(text, "uuid")) return .text;
    if (std.ascii.eqlIgnoreCase(text, "numeric") or std.ascii.eqlIgnoreCase(text, "integer") or std.ascii.eqlIgnoreCase(text, "int") or std.ascii.eqlIgnoreCase(text, "bigint")) return .numeric;
    if (std.ascii.eqlIgnoreCase(text, "boolean") or std.ascii.eqlIgnoreCase(text, "bool")) return .bool;
    if (std.ascii.eqlIgnoreCase(text, "timestamp") or std.ascii.eqlIgnoreCase(text, "timestamptz") or std.ascii.eqlIgnoreCase(text, "datetime")) return .datetime;
    return null;
}

fn generatedRewriteRoutineBodyExpressionArguments(
    alloc: std.mem.Allocator,
    expression: *runtime_schema.RelationalRowsExpression,
    argument_count: usize,
    argument_names: []const []const u8,
) error{ OutOfMemory, UnsupportedSqlShape }!void {
    if (expression.kind == .field) {
        const argument_index = generatedRoutineBodyExpressionArgumentIndex(argument_names, expression.field) orelse return error.UnsupportedSqlShape;
        if (argument_index > argument_count) return error.UnsupportedSqlShape;
        const field = try std.fmt.allocPrint(alloc, "arg{d}", .{argument_index});
        alloc.free(@constCast(expression.field));
        expression.field = field;
        expression.field_source = .source;
    }
    for (@constCast(expression.operands)) |*operand| try generatedRewriteRoutineBodyExpressionArguments(alloc, operand, argument_count, argument_names);
    for (@constCast(expression.case_branches)) |*branch| {
        try generatedRewriteRoutineBodyExpressionConditionArguments(alloc, &branch.when, argument_count, argument_names);
        try generatedRewriteRoutineBodyExpressionArguments(alloc, &branch.then, argument_count, argument_names);
    }
    for (@constCast(expression.case_else)) |*fallback| try generatedRewriteRoutineBodyExpressionArguments(alloc, fallback, argument_count, argument_names);
}

fn generatedRewriteRoutineBodyExpressionConditionArguments(
    alloc: std.mem.Allocator,
    condition: *runtime_schema.RelationalRowsExpressionCondition,
    argument_count: usize,
    argument_names: []const []const u8,
) error{ OutOfMemory, UnsupportedSqlShape }!void {
    try generatedRewriteRoutineBodyExpressionArguments(alloc, &condition.lhs, argument_count, argument_names);
    for (@constCast(condition.rhs)) |*rhs| try generatedRewriteRoutineBodyExpressionArguments(alloc, rhs, argument_count, argument_names);
}

fn generatedRoutineBodyExpressionArgumentIndex(argument_names: []const []const u8, text: []const u8) ?usize {
    if (generatedRoutineArgumentIndex(text)) |index| return index;
    return generatedRoutineNamedArgumentIndex(argument_names, text);
}

fn generatedRoutineArgumentIndex(text: []const u8) ?usize {
    const trimmed = std.mem.trim(u8, text, " \t\r\n");
    const digits = if (std.mem.startsWith(u8, trimmed, "$")) blk: {
        var end: usize = 1;
        while (end < trimmed.len and trimmed[end] >= '0' and trimmed[end] <= '9') : (end += 1) {}
        if (end == 1) return null;
        if (end != trimmed.len and !std.mem.startsWith(u8, trimmed[end..], "::")) return null;
        break :blk trimmed[1..end];
    } else if (std.ascii.startsWithIgnoreCase(trimmed, "arg"))
        trimmed["arg".len..]
    else
        return null;
    if (digits.len == 0) return null;
    for (digits) |byte| {
        if (byte < '0' or byte > '9') return null;
    }
    const index = std.fmt.parseInt(usize, digits, 10) catch return null;
    if (index == 0) return null;
    return index;
}

fn generatedRoutineArgumentNamesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    items: *const generated_parser.GeneratedSqlListAst,
) ![]const []const u8 {
    if (items.count == 0) {
        try validateGeneratedEmptyListAst(items);
        return &.{};
    }
    if (items.count != items.items.len) return error.UnsupportedSqlShape;
    var names = try alloc.alloc([]const u8, items.items.len);
    var len: usize = 0;
    errdefer {
        for (names[0..len]) |name| {
            if (name.len > 0) alloc.free(name);
        }
        alloc.free(names);
    }
    for (items.items) |item| {
        if (item.end > tokens.len or item.start >= item.end) return error.UnsupportedSqlShape;
        names[len] = try generatedRoutineSignatureArgumentNameAlloc(alloc, tokens[item.start..item.end]);
        len += 1;
    }
    return names;
}

fn freeGeneratedRoutineArgumentNames(alloc: std.mem.Allocator, names: []const []const u8) void {
    for (names) |name| {
        if (name.len > 0) alloc.free(name);
    }
    if (names.len > 0) alloc.free(names);
}

fn generatedRoutineSignatureArgumentNameAlloc(alloc: std.mem.Allocator, tokens: []const grammar.Token) ![]const u8 {
    if (tokens.len < 2) return "";
    const first = tokens[0];
    if (first.kind != .identifier) return "";
    if (generatedRoutineSignatureLeadingMode(first.text)) return "";
    if (generatedRoutineSignatureTypeStartsWith(first.text)) return "";
    if (!generatedRoutineSignatureHasTypeAfterName(tokens[1..])) return "";
    return try alloc.dupe(u8, first.text);
}

fn generatedRoutineSignatureLeadingMode(text: []const u8) bool {
    return std.ascii.eqlIgnoreCase(text, "in") or
        std.ascii.eqlIgnoreCase(text, "out") or
        std.ascii.eqlIgnoreCase(text, "inout") or
        std.ascii.eqlIgnoreCase(text, "variadic");
}

fn generatedRoutineSignatureTypeStartsWith(text: []const u8) bool {
    const known_type_heads = [_][]const u8{
        "bigint",
        "bool",
        "boolean",
        "character",
        "date",
        "double",
        "integer",
        "int",
        "json",
        "jsonb",
        "numeric",
        "real",
        "smallint",
        "text",
        "time",
        "timestamp",
        "timestamptz",
        "uuid",
        "varchar",
    };
    for (known_type_heads) |known| {
        if (std.ascii.eqlIgnoreCase(text, known)) return true;
    }
    return false;
}

fn generatedRoutineSignatureHasTypeAfterName(tokens: []const grammar.Token) bool {
    for (tokens) |token| {
        switch (token.kind) {
            .identifier => return true,
            .string, .number, .placeholder => return false,
            else => {},
        }
    }
    return false;
}

fn generatedDdlTailFrom(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst, start: usize) ?[]const grammar.Token {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return null;
    return if (start < end) tokens[start..end] else null;
}

fn validateGeneratedRoutineDdlAst(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) !void {
    try validateGeneratedDdlAstSpans(tokens, ast);
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const object_name_tokens = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    if (object_name_tokens.start >= object_name_tokens.end or object_name_tokens.end > end) return error.UnsupportedSqlShape;
    switch (ast.kind) {
        .create_function, .create_procedure => {
            if (end < 4 or !tokens[0].matchesKeyword("create")) return error.UnsupportedSqlShape;
            var routine_index: usize = 1;
            if (tokens[routine_index].matchesKeyword("or")) {
                if (routine_index + 2 >= end or !tokens[routine_index + 1].matchesKeyword("replace")) return error.UnsupportedSqlShape;
                if (!ast.replace_existing) return error.UnsupportedSqlShape;
                routine_index += 2;
            } else if (ast.replace_existing) {
                return error.UnsupportedSqlShape;
            }
            const expected: token_mod.TokenKeyword = switch (ast.kind) {
                .create_function => .function,
                .create_procedure => .procedure,
                else => unreachable,
            };
            if (routine_index >= end or !tokens[routine_index].matchesKeywordTag(expected)) return error.UnsupportedSqlShape;
            if (object_name_tokens.start != routine_index + 1) return error.UnsupportedSqlShape;
            const signature_tail = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (signature_tail.start != object_name_tokens.end or signature_tail.end != end or signature_tail.start >= end) return error.UnsupportedSqlShape;
            if (tokens[signature_tail.start].kind != .lparen) return error.UnsupportedSqlShape;
        },
        .drop_function, .drop_procedure => {
            if (end < 4 or !tokens[0].matchesKeyword("drop")) return error.UnsupportedSqlShape;
            const expected: token_mod.TokenKeyword = switch (ast.kind) {
                .drop_function => .function,
                .drop_procedure => .procedure,
                else => unreachable,
            };
            if (!tokens[1].matchesKeywordTag(expected)) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_exists = consumeGeneratedPlanIfExists(tokens, &name_index, end);
            if (if_exists != ast.if_exists) return error.UnsupportedSqlShape;
            if (object_name_tokens.start != name_index) return error.UnsupportedSqlShape;
            const signature_tail = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (signature_tail.start != object_name_tokens.end or signature_tail.end != end or signature_tail.start >= end) return error.UnsupportedSqlShape;
            if (tokens[signature_tail.start].kind != .lparen) return error.UnsupportedSqlShape;
            const has_cascade = generatedRangeHasKeyword(tokens, .{ .start = signature_tail.start, .end = end }, "cascade");
            if (has_cascade != ast.cascade) return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedCreateRoutinePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    create: CreateRoutinePlan,
) !void {
    const expected_kind: RoutineKind = switch (ast.kind) {
        .create_function => .function,
        .create_procedure => .procedure,
        else => return error.UnsupportedSqlShape,
    };
    if (create.kind != expected_kind or create.replace_existing != ast.replace_existing) return error.UnsupportedSqlShape;
    try validateGeneratedRoutineNameMatches(alloc, tokens, ast, create.routine_name);
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (operation.start >= operation.end or tokens[operation.start].kind != .lparen) return error.UnsupportedSqlShape;
    const signature_close = findGeneratedMatchingParen(tokens, operation.start, operation.end) orelse return error.UnsupportedSqlShape;
    const routine_metadata = ast.routine_metadata orelse return error.UnsupportedSqlShape;
    try validateGeneratedRoutineUniqueScalarOptionTokens(tokens, .{ .start = signature_close + 1, .end = operation.end }, routine_metadata);
    try validateGeneratedPlainListCount(tokens, .{ .start = operation.start + 1, .end = signature_close }, &routine_metadata.argument_items, create.argument_count);
    try validateGeneratedRoutineOptionalIdentifier(alloc, tokens, routine_metadata.returns_type_tokens, create.returns_type, "returns");
    try validateGeneratedRoutineOptionalIdentifier(alloc, tokens, routine_metadata.language_tokens, create.language, "language");
    try validateGeneratedRoutineScalarOptions(alloc, tokens, routine_metadata, create);
    try validateGeneratedRoutineListOptions(alloc, tokens, routine_metadata, create);
}

fn validateGeneratedRoutineUniqueScalarOptionTokens(
    tokens: []const grammar.Token,
    tail: generated_parser.GeneratedSqlTokenRange,
    routine_metadata: *const generated_parser.GeneratedSqlRoutineAst,
) !void {
    try validateGeneratedRoutineUniqueOptionToken(tokens, tail, "support", routine_metadata.support_function_tokens != null);
}

fn validateGeneratedRoutineUniqueOptionToken(
    tokens: []const grammar.Token,
    tail: generated_parser.GeneratedSqlTokenRange,
    keyword: []const u8,
    expected_present: bool,
) !void {
    if (tail.end > tokens.len or tail.start > tail.end) return error.UnsupportedSqlShape;
    var count: usize = 0;
    for (tokens[tail.start..tail.end]) |token| {
        if (token.matchesKeyword(keyword)) count += 1;
    }
    const expected_count: usize = if (expected_present) 1 else 0;
    if (count != expected_count) return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineScalarOptions(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    routine_metadata: *const generated_parser.GeneratedSqlRoutineAst,
    create: CreateRoutinePlan,
) !void {
    try validateGeneratedRoutineVolatility(tokens, routine_metadata.volatility_tokens, create.volatility);
    try validateGeneratedRoutineSecurity(tokens, routine_metadata.security_tokens, create.security);
    try validateGeneratedRoutineNullInput(tokens, routine_metadata.null_input_tokens, create.null_input);
    try validateGeneratedRoutineParallelSafety(tokens, routine_metadata.parallel_safety_tokens, create.parallel_safety);
    try validateGeneratedRoutineFlag(tokens, routine_metadata.leakproof_tokens, create.leakproof, "leakproof");
    try validateGeneratedRoutineFlag(tokens, routine_metadata.window_tokens, create.window, "window");
    try validateGeneratedRoutineOptionalIdentifier(alloc, tokens, routine_metadata.support_function_tokens, create.support_function, "support");
    try validateGeneratedRoutineOptionalNumber(tokens, routine_metadata.cost_tokens, create.cost, "cost");
    try validateGeneratedRoutineOptionalNumber(tokens, routine_metadata.rows_tokens, create.rows, "rows");
    try validateGeneratedRoutineBodyPayload(tokens, routine_metadata, create);
}

fn validateGeneratedRoutineListOptions(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    routine_metadata: *const generated_parser.GeneratedSqlRoutineAst,
    create: CreateRoutinePlan,
) !void {
    try validateGeneratedRoutineTransformTypes(alloc, tokens, &routine_metadata.transform_type_items, create.transform_types);
    try validateGeneratedRoutineSettings(tokens, &routine_metadata.setting_items, create.settings);
}

fn validateGeneratedRoutineTransformTypes(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    items: *const generated_parser.GeneratedSqlListAst,
    expected_types: []const []const u8,
) !void {
    if (expected_types.len == 0) {
        try validateGeneratedEmptyListAst(items);
        return;
    }
    const first = items.first_tokens orelse return error.UnsupportedSqlShape;
    const last = items.last_tokens orelse return error.UnsupportedSqlShape;
    if (first.start < 3 or last.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[first.start - 3].matchesKeyword("transform") or
        !tokens[first.start - 2].matchesKeyword("for") or
        !tokens[first.start - 1].matchesKeyword("type"))
    {
        return error.UnsupportedSqlShape;
    }
    try validateGeneratedPlainListCount(tokens, .{ .start = first.start, .end = last.end }, items, expected_types.len);
    for (expected_types, 0..) |expected_type, item_index| {
        const generated_type = try generatedSqlObjectIdentifierAlloc(alloc, tokens, items.items[item_index]);
        defer alloc.free(generated_type);
        if (!std.ascii.eqlIgnoreCase(generated_type, expected_type)) return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedRoutineSettings(
    tokens: []const grammar.Token,
    items: *const generated_parser.GeneratedSqlListAst,
    expected_settings: []const RoutineSetting,
) !void {
    if (expected_settings.len == 0) {
        try validateGeneratedEmptyListAst(items);
        return;
    }
    if (items.count != expected_settings.len or
        items.items.len != expected_settings.len or
        items.first_tokens == null or
        items.last_tokens == null or
        items.expression_items.len != 0 or
        items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or
        items.direction_items.len != 0 or
        items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or
        items.nulls_order_items.len != 0 or
        items.nulls_orders.len != 0 or
        items.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
    for (expected_settings, 0..) |expected_setting, item_index| {
        try validateGeneratedRoutineSetting(tokens, items.items[item_index], expected_setting);
    }
}

fn validateGeneratedRoutineSetting(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
    expected: RoutineSetting,
) !void {
    if (item.end > tokens.len or item.start + 3 > item.end) return error.UnsupportedSqlShape;
    if (!tokens[item.start].matchesKeyword("set")) return error.UnsupportedSqlShape;
    if (tokens[item.start + 1].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens[item.start + 1].text, expected.name)) return error.UnsupportedSqlShape;
    var index = item.start + 2;
    if (expected.from_current) {
        if (item.end != index + 2 or !tokens[index].matchesKeyword("from") or !tokens[index + 1].matchesKeyword("current")) return error.UnsupportedSqlShape;
        return;
    }
    if (expected.values.len == 0) return error.UnsupportedSqlShape;
    if (tokens[index].kind == .eq) {
        index += 1;
    } else if (tokens[index].matchesKeyword("to")) {
        index += 1;
    } else {
        return error.UnsupportedSqlShape;
    }
    for (expected.values, 0..) |expected_value, value_index| {
        if (index >= item.end) return error.UnsupportedSqlShape;
        const token = tokens[index];
        if (token.kind != .identifier and token.kind != .string and token.kind != .number) return error.UnsupportedSqlShape;
        if (!std.ascii.eqlIgnoreCase(token.text, expected_value)) return error.UnsupportedSqlShape;
        index += 1;
        if (value_index + 1 < expected.values.len) {
            if (index >= item.end or tokens[index].kind != .comma) return error.UnsupportedSqlShape;
            index += 1;
        }
    }
    if (index != item.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineVolatility(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?RoutineVolatility,
) !void {
    const volatility = expected orelse {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        return;
    };
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    const keyword = switch (volatility) {
        .immutable => "immutable",
        .stable => "stable",
        .@"volatile" => "volatile",
    };
    if (!tokens[range.start].matchesKeyword(keyword)) return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineSecurity(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?RoutineSecurity,
) !void {
    const security = expected orelse {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        return;
    };
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.end > tokens.len or range.start >= range.end) return error.UnsupportedSqlShape;
    const expected_tail = switch (security) {
        .definer => "definer",
        .invoker => "invoker",
    };
    if (range.end == range.start + 2) {
        if (!tokens[range.start].matchesKeyword("security") or !tokens[range.start + 1].matchesKeyword(expected_tail)) return error.UnsupportedSqlShape;
        return;
    }
    if (range.end == range.start + 3) {
        if (!tokens[range.start].matchesKeyword("external") or
            !tokens[range.start + 1].matchesKeyword("security") or
            !tokens[range.start + 2].matchesKeyword(expected_tail))
        {
            return error.UnsupportedSqlShape;
        }
        return;
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineNullInput(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?RoutineNullInput,
) !void {
    const null_input = expected orelse {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        return;
    };
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.end > tokens.len or range.start >= range.end) return error.UnsupportedSqlShape;
    switch (null_input) {
        .called => {
            if (range.end != range.start + 4 or
                !tokens[range.start].matchesKeyword("called") or
                !tokens[range.start + 1].matchesKeyword("on") or
                !tokens[range.start + 2].matchesKeyword("null") or
                !tokens[range.start + 3].matchesKeyword("input"))
            {
                return error.UnsupportedSqlShape;
            }
        },
        .returns_null => {
            if (range.end == range.start + 1 and tokens[range.start].matchesKeyword("strict")) return;
            if (range.end == range.start + 5 and
                tokens[range.start].matchesKeyword("returns") and
                tokens[range.start + 1].matchesKeyword("null") and
                tokens[range.start + 2].matchesKeyword("on") and
                tokens[range.start + 3].matchesKeyword("null") and
                tokens[range.start + 4].matchesKeyword("input"))
            {
                return;
            }
            return error.UnsupportedSqlShape;
        },
    }
}

fn validateGeneratedRoutineParallelSafety(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?RoutineParallelSafety,
) !void {
    const parallel_safety = expected orelse {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        return;
    };
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.end != range.start + 2 or range.end > tokens.len or !tokens[range.start].matchesKeyword("parallel")) return error.UnsupportedSqlShape;
    const keyword = switch (parallel_safety) {
        .safe => "safe",
        .restricted => "restricted",
        .unsafe => "unsafe",
    };
    if (!tokens[range.start + 1].matchesKeyword(keyword)) return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineFlag(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: bool,
    keyword: []const u8,
) !void {
    if (!expected) {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        return;
    }
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.end != range.start + 1 or range.end > tokens.len or !tokens[range.start].matchesKeyword(keyword)) return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineOptionalNumber(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?[]const u8,
    keyword: []const u8,
) !void {
    const number = expected orelse {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        return;
    };
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start == 0 or range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[range.start - 1].matchesKeyword(keyword) or tokens[range.start].kind != .number) return error.UnsupportedSqlShape;
    if (!std.mem.eql(u8, tokens[range.start].text, number)) return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineBodyTokens(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: bool,
) !void {
    if (!expected) {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        return;
    }
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start == 0 or range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[range.start - 1].matchesKeyword("as") or tokens[range.start].kind != .string) return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineBodyPayload(
    tokens: []const grammar.Token,
    routine_metadata: *const generated_parser.GeneratedSqlRoutineAst,
    create: CreateRoutinePlan,
) !void {
    const body = create.body orelse {
        if (routine_metadata.body_tokens != null or
            routine_metadata.body_kind != null or
            routine_metadata.body_hook != null or
            routine_metadata.body_perform_call_count != 0)
        {
            return error.UnsupportedSqlShape;
        }
        return;
    };
    try validateGeneratedRoutineBodyTokens(tokens, routine_metadata.body_tokens, true);
    const body_kind = routine_metadata.body_kind orelse return error.UnsupportedSqlShape;
    const body_hook = routine_metadata.body_hook orelse return error.UnsupportedSqlShape;
    if (!generatedRoutineBodyKindMatches(body_kind, body.kind)) return error.UnsupportedSqlShape;
    if (!generatedRoutineExecutionHookMatches(body_hook, body.hook)) return error.UnsupportedSqlShape;
    if (routine_metadata.body_perform_call_count != body.perform_calls.len) return error.UnsupportedSqlShape;
}

fn generatedRoutineBodyKindMatches(generated: generated_parser.GeneratedSqlRoutineBodyKind, expected: RoutineBodyKind) bool {
    return switch (generated) {
        .sql_expression => expected == .sql_expression,
        .plpgsql_trigger => expected == .plpgsql_trigger,
        .plpgsql_procedure => expected == .plpgsql_procedure,
    };
}

fn generatedRoutineExecutionHookMatches(generated: generated_parser.GeneratedSqlRoutineExecutionHook, expected: RoutineExecutionHook) bool {
    return switch (generated) {
        .expression => expected == .expression,
        .trigger_return_new => expected == .trigger_return_new,
        .trigger_return_old => expected == .trigger_return_old,
        .trigger_return_null => expected == .trigger_return_null,
        .procedure_noop => expected == .procedure_noop,
    };
}

fn validateGeneratedDropRoutinePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    drop: DropRoutinePlan,
) !void {
    const expected_kind: RoutineKind = switch (ast.kind) {
        .drop_function => .function,
        .drop_procedure => .procedure,
        else => return error.UnsupportedSqlShape,
    };
    if (drop.kind != expected_kind or drop.if_exists != ast.if_exists or drop.cascade != ast.cascade) return error.UnsupportedSqlShape;
    try validateGeneratedRoutineNameMatches(alloc, tokens, ast, drop.routine_name);
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (operation.start >= operation.end or tokens[operation.start].kind != .lparen) return error.UnsupportedSqlShape;
    const signature_close = findGeneratedMatchingParen(tokens, operation.start, operation.end) orelse return error.UnsupportedSqlShape;
    const routine_metadata = ast.routine_metadata orelse return error.UnsupportedSqlShape;
    try validateGeneratedPlainListCount(tokens, .{ .start = operation.start + 1, .end = signature_close }, &routine_metadata.argument_items, drop.argument_count);
}

fn validateGeneratedRoutineNameMatches(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    expected_name: []const u8,
) !void {
    const generated_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    defer alloc.free(generated_name);
    if (!std.ascii.eqlIgnoreCase(generated_name, expected_name)) return error.UnsupportedSqlShape;
}

fn validateGeneratedRoutineOptionalIdentifier(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected_name: ?[]const u8,
    keyword: []const u8,
) !void {
    const expected = expected_name orelse {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        return;
    };
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start == 0 or !tokens[range.start - 1].matchesKeyword(keyword)) return error.UnsupportedSqlShape;
    const generated_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, range);
    defer alloc.free(generated_name);
    if (!std.ascii.eqlIgnoreCase(generated_name, expected)) return error.UnsupportedSqlShape;
}

fn authorizationCatalogPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    _ = options;
    try validateGeneratedRoleDdlAst(tokens, ast);
    var plan: DdlPlan = .{ .authorization_catalog = switch (ast.kind) {
        .create_role => .{ .create_role = try createRolePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) },
        .alter_role => .{ .alter_role = try alterRolePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) },
        .drop_role => .{ .drop_role = try dropRolePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) },
        else => return error.UnsupportedSqlShape,
    } };
    errdefer plan.deinit(alloc);
    switch (plan) {
        .authorization_catalog => |authorization| switch (authorization) {
            .create_role => |create| try validateGeneratedCreateRolePlan(alloc, tokens, ast, create),
            .alter_role => |alter| try validateGeneratedAlterRolePlan(alloc, tokens, ast, alter),
            .drop_role => |drop| try validateGeneratedDropRolePlan(alloc, tokens, ast, drop),
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn createRolePlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !CreateRolePlan {
    return .{
        .role_name = try generatedIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
    };
}

fn dropRolePlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !DropRolePlan {
    return .{
        .role_name = try generatedIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .if_exists = ast.if_exists,
    };
}

fn alterRolePlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !AlterRolePlan {
    const operation_range = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    var setting_operation = operation_range.start;
    const database_name: ?[]const u8 = if (ast.role_database_name_tokens) |database_range| blk: {
        if (database_range.start != operation_range.start + 2 or
            database_range.end > operation_range.end or
            !tokens[operation_range.start].matchesKeyword("in") or
            !tokens[operation_range.start + 1].matchesKeyword("database"))
        {
            return error.UnsupportedSqlShape;
        }
        setting_operation = database_range.end;
        break :blk try generatedIdentifierAlloc(alloc, tokens, database_range);
    } else null;
    errdefer if (database_name) |name| alloc.free(name);

    if (setting_operation >= operation_range.end) return error.UnsupportedSqlShape;
    const operation: AlterRolePlan.Operation = if (tokens[setting_operation].matchesKeyword("set"))
        .set
    else if (tokens[setting_operation].matchesKeyword("reset"))
        .reset
    else
        return error.UnsupportedSqlShape;

    const setting_name_range = try requireGeneratedTokenRangeAt(ast.setting_name_tokens, setting_operation + 1, operation_range.end);
    const setting_name = try generatedIdentifierAlloc(alloc, tokens, setting_name_range);
    errdefer alloc.free(setting_name);
    const setting_kind: AlterRolePlan.SettingKind = if (std.mem.startsWith(u8, setting_name, "app.")) .app else .runtime;

    const setting_value: ?AlterRolePlan.SettingValue = switch (operation) {
        .reset => blk: {
            if (setting_name_range.end != operation_range.end or ast.setting_value_tokens != null) return error.UnsupportedSqlShape;
            break :blk null;
        },
        .set => blk: {
            if (setting_name_range.end >= operation_range.end or tokens[setting_name_range.end].kind != .eq) return error.UnsupportedSqlShape;
            const value_range = ast.setting_value_tokens orelse return error.UnsupportedSqlShape;
            if (value_range.start != setting_name_range.end + 1 or value_range.end != operation_range.end) return error.UnsupportedSqlShape;
            break :blk try generatedAlterRoleSettingValueAlloc(alloc, tokens, value_range);
        },
    };
    errdefer if (setting_value) |value| {
        var mutable = value;
        mutable.deinit(alloc);
    };

    return .{
        .role_name = try generatedIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .database_name = database_name,
        .operation = operation,
        .setting_kind = setting_kind,
        .setting_name = setting_name,
        .setting_value = setting_value,
    };
}

fn validateGeneratedRoleDdlAst(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) !void {
    try validateGeneratedDdlAstSpans(tokens, ast);
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const object_name_tokens = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    if (object_name_tokens.start >= object_name_tokens.end or object_name_tokens.end > end) return error.UnsupportedSqlShape;
    switch (ast.kind) {
        .create_role => {
            if (end < 3 or !tokens[0].matchesKeyword("create") or !grammar.isRoleAliasKeywordToken(tokens[1])) return error.UnsupportedSqlShape;
            if (object_name_tokens.start != 2 or object_name_tokens.end != 3) return error.UnsupportedSqlShape;
            if (object_name_tokens.end < end) {
                const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
                if (operation.start != object_name_tokens.end or operation.end != end) return error.UnsupportedSqlShape;
            } else if (ast.alter_table_operation_tokens != null) {
                return error.UnsupportedSqlShape;
            }
        },
        .alter_role => {
            if (end < 5 or !tokens[0].matchesKeyword("alter") or !grammar.isRoleAliasKeywordToken(tokens[1])) return error.UnsupportedSqlShape;
            if (object_name_tokens.start != 2 or object_name_tokens.end != 3) return error.UnsupportedSqlShape;
            const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (operation.start != object_name_tokens.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
        },
        .drop_role => {
            if (end < 3 or !tokens[0].matchesKeyword("drop") or !grammar.isRoleAliasKeywordToken(tokens[1])) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_exists = consumeGeneratedPlanIfExists(tokens, &name_index, end);
            if (if_exists != ast.if_exists) return error.UnsupportedSqlShape;
            if (object_name_tokens.start != name_index or object_name_tokens.end != name_index + 1) return error.UnsupportedSqlShape;
            if (object_name_tokens.end < end) {
                const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
                if (operation.start != object_name_tokens.end or operation.end != end) return error.UnsupportedSqlShape;
            } else if (ast.alter_table_operation_tokens != null) {
                return error.UnsupportedSqlShape;
            }
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedCreateRolePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    create: CreateRolePlan,
) !void {
    try validateGeneratedRoleNameMatches(alloc, tokens, ast, create.role_name);
}

fn validateGeneratedDropRolePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    drop: DropRolePlan,
) !void {
    try validateGeneratedRoleNameMatches(alloc, tokens, ast, drop.role_name);
}

fn validateGeneratedAlterRolePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    alter: AlterRolePlan,
) !void {
    try validateGeneratedRoleNameMatches(alloc, tokens, ast, alter.role_name);
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    var setting_operation = operation.start;
    if (alter.database_name) |database_name| {
        const database_range = try requireGeneratedTokenRangeAt(ast.role_database_name_tokens, operation.start + 2, operation.end);
        if (!tokens[operation.start].matchesKeyword("in") or !tokens[operation.start + 1].matchesKeyword("database")) return error.UnsupportedSqlShape;
        const generated_database_name = try generatedIdentifierAlloc(alloc, tokens, database_range);
        defer alloc.free(@constCast(generated_database_name));
        if (!std.ascii.eqlIgnoreCase(generated_database_name, database_name)) return error.UnsupportedSqlShape;
        setting_operation = database_range.end;
    } else if (ast.role_database_name_tokens != null) {
        return error.UnsupportedSqlShape;
    }

    if (setting_operation >= operation.end) return error.UnsupportedSqlShape;
    switch (alter.operation) {
        .set => if (!tokens[setting_operation].matchesKeyword("set")) return error.UnsupportedSqlShape,
        .reset => if (!tokens[setting_operation].matchesKeyword("reset")) return error.UnsupportedSqlShape,
    }
    const setting_name_range = try requireGeneratedTokenRangeAt(ast.setting_name_tokens, setting_operation + 1, operation.end);
    const generated_setting_name = try generatedIdentifierAlloc(alloc, tokens, setting_name_range);
    defer alloc.free(@constCast(generated_setting_name));
    if (!std.ascii.eqlIgnoreCase(generated_setting_name, alter.setting_name)) return error.UnsupportedSqlShape;

    switch (alter.operation) {
        .reset => {
            if (setting_name_range.end != operation.end or ast.setting_value_tokens != null or alter.setting_value != null) return error.UnsupportedSqlShape;
        },
        .set => {
            if (setting_name_range.end >= operation.end or tokens[setting_name_range.end].kind != .eq) return error.UnsupportedSqlShape;
            const value_range = ast.setting_value_tokens orelse return error.UnsupportedSqlShape;
            if (value_range.start != setting_name_range.end + 1 or value_range.end != operation.end) return error.UnsupportedSqlShape;
            try validateGeneratedAlterRoleSettingValue(alloc, tokens, value_range, alter.setting_value orelse return error.UnsupportedSqlShape);
        },
    }
}

fn generatedAlterRoleSettingValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    value_range: generated_parser.GeneratedSqlTokenRange,
) !AlterRolePlan.SettingValue {
    if (value_range.start >= value_range.end or value_range.end > tokens.len) return error.UnsupportedSqlShape;
    if (value_range.start + 1 == value_range.end and tokens[value_range.start].kind == .string) {
        return .{ .literal = try alloc.dupe(u8, tokens[value_range.start].text) };
    }
    if (value_range.start + 4 == value_range.end and
        tokens[value_range.start].matchesKeyword("current_setting") and
        tokens[value_range.start + 1].kind == .lparen and
        tokens[value_range.start + 2].kind == .string and
        tokens[value_range.start + 3].kind == .rparen)
    {
        if (tokens[value_range.start + 2].text.len == 0) return error.UnsupportedSqlShape;
        return .{ .current_setting = try alloc.dupe(u8, tokens[value_range.start + 2].text) };
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedRoleNameMatches(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    expected_name: []const u8,
) !void {
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    const generated_name = try generatedIdentifierAlloc(alloc, tokens, name_range);
    defer alloc.free(@constCast(generated_name));
    if (!std.ascii.eqlIgnoreCase(generated_name, expected_name)) return error.UnsupportedSqlShape;
}

fn validateGeneratedAlterRoleSettingValue(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    value_range: generated_parser.GeneratedSqlTokenRange,
    expected_value: AlterRolePlan.SettingValue,
) !void {
    switch (expected_value) {
        .literal => |literal| {
            if (value_range.start + 1 != value_range.end or tokens[value_range.start].kind != .string) return error.UnsupportedSqlShape;
            if (!std.mem.eql(u8, tokens[value_range.start].text, literal)) return error.UnsupportedSqlShape;
        },
        .current_setting => |setting_name| {
            if (value_range.start + 4 != value_range.end or
                !tokens[value_range.start].matchesKeyword("current_setting") or
                tokens[value_range.start + 1].kind != .lparen or
                tokens[value_range.start + 2].kind != .string or
                tokens[value_range.start + 3].kind != .rparen)
            {
                return error.UnsupportedSqlShape;
            }
            const generated_setting_name = try alloc.dupe(u8, tokens[value_range.start + 2].text);
            defer alloc.free(generated_setting_name);
            if (!std.mem.eql(u8, generated_setting_name, setting_name)) return error.UnsupportedSqlShape;
        },
    }
}

fn isRoleAliasKeywordAt(tokens: []const grammar.Token, index: usize) bool {
    return index < tokens.len and grammar.isRoleAliasKeywordToken(tokens[index]);
}

fn typeSystemCatalogPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    _ = options;
    try validateGeneratedTypeSystemDdlAst(tokens, ast);
    var plan: DdlPlan = .{ .type_system_catalog = switch (ast.kind) {
        .create_collation => .{ .collation = .{ .create = try createCollationPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .alter_collation => .{ .collation = .{ .rename = try renameCollationPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_collation => .{ .collation = .{ .drop = try dropCollationPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .create_operator => .{ .operator = .{ .create = try createOperatorPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_operator => .{ .operator = .{ .drop = try dropOperatorPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .create_aggregate => .{ .aggregate = .{ .create = try createAggregatePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_aggregate => .{ .aggregate = .{ .drop = try dropAggregatePlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .create_cast => .{ .cast = .{ .create = try createCastPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_cast => .{ .cast = .{ .drop = try dropCastPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        else => return error.UnsupportedSqlShape,
    } };
    errdefer plan.deinit(alloc);
    switch (plan) {
        .type_system_catalog => |type_system| switch (ast.kind) {
            .create_collation, .alter_collation, .drop_collation => switch (type_system) {
                .collation => |collation| switch (ast.kind) {
                    .create_collation => switch (collation) {
                        .create => |create| try validateGeneratedCreateCollationPlan(alloc, tokens, ast, create),
                        else => return error.UnsupportedSqlShape,
                    },
                    .alter_collation => switch (collation) {
                        .rename => |rename| try validateGeneratedRenameCollationPlan(alloc, tokens, ast, rename),
                        else => return error.UnsupportedSqlShape,
                    },
                    .drop_collation => switch (collation) {
                        .drop => |drop| try validateGeneratedDropCollationPlan(alloc, tokens, ast, drop),
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .create_operator, .drop_operator => switch (type_system) {
                .operator => |operator| switch (ast.kind) {
                    .create_operator => switch (operator) {
                        .create => |create| try validateGeneratedCreateOperatorPlan(alloc, tokens, ast, create),
                        else => return error.UnsupportedSqlShape,
                    },
                    .drop_operator => switch (operator) {
                        .drop => |drop| try validateGeneratedDropOperatorPlan(alloc, tokens, ast, drop),
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .create_aggregate, .drop_aggregate => switch (type_system) {
                .aggregate => |aggregate| switch (ast.kind) {
                    .create_aggregate => switch (aggregate) {
                        .create => |create| try validateGeneratedCreateAggregatePlan(alloc, tokens, ast, create),
                        else => return error.UnsupportedSqlShape,
                    },
                    .drop_aggregate => switch (aggregate) {
                        .drop => |drop| try validateGeneratedDropAggregatePlan(alloc, tokens, ast, drop),
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            .create_cast, .drop_cast => switch (type_system) {
                .cast => |cast| switch (ast.kind) {
                    .create_cast => switch (cast) {
                        .create => |create| try validateGeneratedCreateCastPlan(alloc, tokens, ast, create),
                        else => return error.UnsupportedSqlShape,
                    },
                    .drop_cast => switch (cast) {
                        .drop => |drop| try validateGeneratedDropCastPlan(alloc, tokens, ast, drop),
                        else => return error.UnsupportedSqlShape,
                    },
                    else => return error.UnsupportedSqlShape,
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn createCollationPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !CreateCollationPlan {
    return .{
        .collation_name = try generatedIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .option_count = ast.collation_option_items.count,
    };
}

fn renameCollationPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !RenameCollationPlan {
    const collation_name = try generatedIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(collation_name);
    return .{
        .collation_name = collation_name,
        .new_collation_name = try generatedIdentifierAlloc(alloc, tokens, ast.rename_target_tokens orelse return error.UnsupportedSqlShape),
    };
}

