}

fn validateGeneratedRefreshMaterializedViewPlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    refresh: RefreshMaterializedViewPlan,
) !void {
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.object_name_tokens, name_range.start, refresh.view_name);
    if ((ast.materialized_view_concurrently orelse return error.UnsupportedSqlShape) != refresh.concurrently) return error.UnsupportedSqlShape;
    const operation = ast.alter_table_operation_tokens;
    if (operation == null) {
        if (!refresh.populate or (ast.materialized_view_populate orelse return error.UnsupportedSqlShape) != refresh.populate) return error.UnsupportedSqlShape;
        return;
    }
    const op = operation.?;
    if (op.start != name_range.end or op.end > tokens.len or op.start >= op.end) return error.UnsupportedSqlShape;
    if (!tokens[op.start].matchesKeyword("with")) return error.UnsupportedSqlShape;
    const populate = generatedMaterializedViewPopulateClause(tokens, op) orelse return error.UnsupportedSqlShape;
    if (populate != refresh.populate or (ast.materialized_view_populate orelse return error.UnsupportedSqlShape) != refresh.populate) return error.UnsupportedSqlShape;
}

fn validateGeneratedMaterializedViewDataClauseAst(
    tokens: []const grammar.Token,
    source_start: usize,
    end: usize,
    ast: generated_parser.GeneratedSqlDdlAst,
    expected_populate: bool,
) !void {
    const ast_populate = ast.materialized_view_populate orelse return error.UnsupportedSqlShape;
    if (ast_populate != expected_populate) return error.UnsupportedSqlShape;
    if (generatedMaterializedViewDataClauseRange(tokens, source_start, end)) |clause| {
        const ast_clause = ast.materialized_view_data_clause_tokens orelse return error.UnsupportedSqlShape;
        if (ast_clause.start != clause.range.start or ast_clause.end != clause.range.end) return error.UnsupportedSqlShape;
        if (clause.populate != ast_populate) return error.UnsupportedSqlShape;
    } else if (ast.materialized_view_data_clause_tokens != null) {
        return error.UnsupportedSqlShape;
    }
}

fn generatedMaterializedViewPopulateOnCreate(
    tokens: []const grammar.Token,
    operation: generated_parser.GeneratedSqlTokenRange,
) bool {
    if (operation.end >= operation.start + 3 and
        tokens[operation.end - 3].matchesKeyword("with") and
        tokens[operation.end - 2].matchesKeyword("no") and
        tokens[operation.end - 1].matchesKeyword("data"))
    {
        return false;
    }
    return true;
}

fn generatedMaterializedViewPopulateClause(
    tokens: []const grammar.Token,
    operation: generated_parser.GeneratedSqlTokenRange,
) ?bool {
    if (operation.start + 2 == operation.end and
        tokens[operation.start].matchesKeyword("with") and
        tokens[operation.start + 1].matchesKeyword("data"))
    {
        return true;
    }
    if (operation.start + 3 == operation.end and
        tokens[operation.start].matchesKeyword("with") and
        tokens[operation.start + 1].matchesKeyword("no") and
        tokens[operation.start + 2].matchesKeyword("data"))
    {
        return false;
    }
    return null;
}

const GeneratedMaterializedViewDataClause = struct {
    range: generated_parser.GeneratedSqlTokenRange,
    populate: bool,
};

fn generatedMaterializedViewDataClauseRange(
    tokens: []const grammar.Token,
    source_start: usize,
    end: usize,
) ?GeneratedMaterializedViewDataClause {
    if (end > tokens.len) return null;
    if (end >= source_start + 2 and
        tokens[end - 2].matchesKeyword("with") and
        tokens[end - 1].matchesKeyword("data"))
    {
        return .{ .range = .{ .start = end - 2, .end = end }, .populate = true };
    }
    if (end >= source_start + 3 and
        tokens[end - 3].matchesKeyword("with") and
        tokens[end - 2].matchesKeyword("no") and
        tokens[end - 1].matchesKeyword("data"))
    {
        return .{ .range = .{ .start = end - 3, .end = end }, .populate = false };
    }
    return null;
}

fn consumeGeneratedPlanIfNotExists(tokens: []const grammar.Token, index: *usize, end: usize) bool {
    if (index.* + 2 < end and
        tokens[index.*].matchesKeyword("if") and
        tokens[index.* + 1].matchesKeyword("not") and
        tokens[index.* + 2].matchesKeyword("exists"))
    {
        index.* += 3;
        return true;
    }
    return false;
}

fn consumeGeneratedPlanIfExists(tokens: []const grammar.Token, index: *usize, end: usize) bool {
    if (index.* + 1 < end and
        tokens[index.*].matchesKeyword("if") and
        tokens[index.* + 1].matchesKeyword("exists"))
    {
        index.* += 2;
        return true;
    }
    return false;
}

fn domainCatalogPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    try validateGeneratedDomainDdlAst(tokens, ast);
    var plan: DdlPlan = switch (ast.kind) {
        .create_domain => .{ .domain_catalog = .{ .create = try createDomainPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options.domain_options) } },
        .alter_domain => .{ .domain_catalog = .{ .alter = try alterDomainPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        .drop_domain => .{ .domain_catalog = .{ .drop = try dropDomainPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) } },
        else => return error.UnsupportedSqlShape,
    };
    errdefer plan.deinit(alloc);
    switch (ast.kind) {
        .create_domain => switch (plan) {
            .domain_catalog => |catalog| switch (catalog) {
                .create => |create| try validateGeneratedCreateDomainPlan(alloc, tokens, ast, create),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .alter_domain => switch (plan) {
            .domain_catalog => |catalog| switch (catalog) {
                .alter => |alter| try validateGeneratedDomainAlterPlan(tokens, ast, alter),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .drop_domain => switch (plan) {
            .domain_catalog => |catalog| switch (catalog) {
                .drop => |drop| try validateGeneratedDropDomainPlan(alloc, tokens, ast, drop),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn createDomainPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlDomainOptions,
) !CreateDomainPlan {
    const type_range = ast.domain_type_tokens orelse return error.UnsupportedSqlShape;
    var type_pos = type_range.start;
    const ddl_type = try parseDdlType(tokens, &type_pos);
    if (type_pos != type_range.end) return error.UnsupportedSqlShape;

    var plan = CreateDomainPlan{
        .domain_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .field_type = ddl_type.field_type,
        .array_item_type = ddl_type.array_item_type,
    };
    errdefer plan.deinit(alloc);

    var checks = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        clearDdlRelationalChecks(alloc, checks.items);
        checks.deinit(alloc);
    }
    for (ast.domain_operation_items.items, 0..) |item, index| {
        try applyGeneratedCreateDomainOptionAlloc(alloc, tokens, ast, item, index, options, &plan, &checks);
    }
    plan.checks = try checks.toOwnedSlice(alloc);
    return plan;
}

fn applyGeneratedCreateDomainOptionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    item: generated_parser.GeneratedSqlTokenRange,
    index: usize,
    options: DdlDomainOptions,
    plan: *CreateDomainPlan,
    checks: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
) !void {
    if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (ast.domain_operation_kind_items.len != ast.domain_operation_items.count or
        ast.domain_operation_constraint_name_items.len != ast.domain_operation_items.count or
        ast.domain_operation_default_value_items.len != ast.domain_operation_items.count or
        ast.domain_operation_check_payload_items.len != ast.domain_operation_items.count or
        ast.domain_operation_check_payload_expressions.len != ast.domain_operation_items.count)
    {
        return error.UnsupportedSqlShape;
    }
    const kind = ast.domain_operation_kind_items[index];
    if (kind.start < item.start or kind.end > item.end or kind.start >= kind.end or kind.end > tokens.len) return error.UnsupportedSqlShape;
    const constraint_name = ast.domain_operation_constraint_name_items[index];
    const default_payload = ast.domain_operation_default_value_items[index];
    const check_payload = ast.domain_operation_check_payload_items[index];
    if (tokens[kind.start].matchesKeyword("default")) {
        const default_range = default_payload orelse return error.UnsupportedSqlShape;
        if (plan.default_value != null or kind.start != item.start or kind.end != item.start + 1) return error.UnsupportedSqlShape;
        if (default_range.start != kind.end or default_range.end != item.end or constraint_name != null or check_payload != null) return error.UnsupportedSqlShape;
        var pos = default_range.start;
        const default_value = try parseDdlDefaultValueWithParamsAlloc(alloc, tokens, &pos, plan.field_type, options.params, options.realtime_ns, &.{}, null, 0);
        errdefer alloc.free(default_value.value_json);
        if (pos != default_range.end) return error.UnsupportedSqlShape;
        plan.default_value = default_value;
        return;
    }
    if (tokens[kind.start].matchesKeyword("not")) {
        if (!std.meta.eql(kind, item) or constraint_name != null or default_payload != null or check_payload != null) return error.UnsupportedSqlShape;
        if (item.start + 2 != item.end or !tokens[item.start + 1].matchesKeyword("null")) return error.UnsupportedSqlShape;
        plan.not_null = true;
        return;
    }
    if (tokens[kind.start].matchesKeyword("null")) {
        if (!std.meta.eql(kind, item) or constraint_name != null or default_payload != null or check_payload != null) return error.UnsupportedSqlShape;
        if (item.start + 1 != item.end) return error.UnsupportedSqlShape;
        plan.not_null = false;
        return;
    }
    if (tokens[kind.start].matchesKeyword("check")) {
        const payload = check_payload orelse return error.UnsupportedSqlShape;
        if (default_payload != null) return error.UnsupportedSqlShape;
        if (constraint_name) |name| {
            if (item.start + 4 > item.end or !tokens[item.start].matchesKeyword("constraint")) return error.UnsupportedSqlShape;
            if (name.start != item.start + 1 or name.end != item.start + 2 or tokens[name.start].kind != .identifier) return error.UnsupportedSqlShape;
            if (kind.start != item.start + 2 or kind.end != item.start + 3) return error.UnsupportedSqlShape;
        } else if (kind.start != item.start or kind.end != item.start + 1) {
            return error.UnsupportedSqlShape;
        }
        if (payload.start != kind.end or payload.end != item.end) return error.UnsupportedSqlShape;
        const check_expression = &ast.domain_operation_check_payload_expressions[index];
        try validateGeneratedDdlCheckPayloadExpressionAst(tokens, payload, check_expression);
        const check = try generatedDdlCheckConstraintFromAstAlloc(
            alloc,
            tokens,
            payload,
            check_expression.*,
            if (constraint_name) |name| tokens[name.start].text else null,
            options.expression_options,
        );
        var transferred = false;
        errdefer if (!transferred) freeDdlRelationalCheck(alloc, check);
        try checks.append(alloc, check);
        transferred = true;
        return;
    }
    return error.UnsupportedSqlShape;
}

fn alterDomainPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !AlterDomainPlan {
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedDomainOperationItems(tokens, operation, &ast.domain_operation_items);
    const domain_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(domain_name);
    const operations = try alloc.alloc(DomainAlterOperation, ast.domain_operation_items.count);
    errdefer alloc.free(operations);
    var initialized: usize = 0;
    errdefer clearDomainAlterOperations(alloc, operations[0..initialized]);
    for (ast.domain_operation_items.items, 0..) |item, index| {
        operations[index] = try generatedDomainAlterOperationAlloc(alloc, tokens, item);
        initialized += 1;
    }
    return .{
        .domain_name = domain_name,
        .operations = operations,
    };
}

fn dropDomainPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !DropDomainPlan {
    return .{
        .domain_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .if_exists = ast.if_exists,
        .cascade = ast.cascade,
    };
}

fn validateGeneratedDomainDdlAst(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const object_name = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    if (object_name.start >= object_name.end or object_name.end > end) return error.UnsupportedSqlShape;
    switch (ast.kind) {
        .create_domain => {
            if (end < 5 or !tokens[0].matchesKeyword("create") or !tokens[1].matchesKeyword("domain")) return error.UnsupportedSqlShape;
            if (object_name.start != 2) return error.UnsupportedSqlShape;
            const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (operation.start != object_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
            if (!tokens[operation.start].matchesKeyword("as")) return error.UnsupportedSqlShape;
            const type_range = try requireGeneratedTokenRangeAt(ast.domain_type_tokens, operation.start + 1, operation.end);
            if (type_range.end < operation.end) {
                try validateGeneratedCreateDomainOptionItems(tokens, .{ .start = type_range.end, .end = operation.end }, &ast.domain_operation_items);
                try validateGeneratedCreateDomainOptionPayloadItems(tokens, &ast);
            } else {
                try validateGeneratedEmptyListAst(&ast.domain_operation_items);
                try validateGeneratedEmptyDomainCreateOptionPayloadItems(&ast);
            }
        },
        .alter_domain => {
            if (end < 5 or !tokens[0].matchesKeyword("alter") or !tokens[1].matchesKeyword("domain")) return error.UnsupportedSqlShape;
            if (object_name.start != 2) return error.UnsupportedSqlShape;
            const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (operation.start != object_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
            if (!tokens[operation.start].matchesKeyword("set") and !tokens[operation.start].matchesKeyword("drop")) return error.UnsupportedSqlShape;
            try validateGeneratedDomainOperationItems(tokens, operation, &ast.domain_operation_items);
        },
        .drop_domain => {
            if (end < 3 or !tokens[0].matchesKeyword("drop") or !tokens[1].matchesKeyword("domain")) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_exists = consumeGeneratedPlanIfExists(tokens, &name_index, end);
            if (if_exists != ast.if_exists) return error.UnsupportedSqlShape;
            if (object_name.start != name_index) return error.UnsupportedSqlShape;
            const has_cascade = generatedRangeHasKeyword(tokens, .{ .start = object_name.end, .end = end }, "cascade");
            if (has_cascade != ast.cascade) return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedCreateDomainPlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    create: CreateDomainPlan,
) !void {
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.object_name_tokens, name_range.start, create.domain_name);
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (operation.start + 2 > operation.end or !tokens[operation.start].matchesKeyword("as")) return error.UnsupportedSqlShape;
    const type_range = try requireGeneratedTokenRangeAt(ast.domain_type_tokens, operation.start + 1, operation.end);
    var type_pos = type_range.start;
    const generated_type = try parseDdlType(tokens, &type_pos);
    if (type_pos != type_range.end or
        generated_type.field_type != create.field_type or
        generated_type.array_item_type != create.array_item_type)
    {
        return error.UnsupportedSqlShape;
    }
    if (type_range.end < operation.end) {
        try validateGeneratedCreateDomainOptionItems(tokens, .{ .start = type_range.end, .end = operation.end }, &ast.domain_operation_items);
        try validateGeneratedCreateDomainOptionPayloadItems(tokens, &ast);
    } else {
        try validateGeneratedEmptyListAst(&ast.domain_operation_items);
        try validateGeneratedEmptyDomainCreateOptionPayloadItems(&ast);
    }
}

fn validateGeneratedDropDomainPlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    drop: DropDomainPlan,
) !void {
    if (drop.if_exists != ast.if_exists or drop.cascade != ast.cascade) return error.UnsupportedSqlShape;
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.object_name_tokens, name_range.start, drop.domain_name);
}

fn validateGeneratedDomainAlterPlan(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    alter: AlterDomainPlan,
) !void {
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedDomainOperationItems(tokens, operation, &ast.domain_operation_items);
    if (alter.operations.len != ast.domain_operation_items.count) return error.UnsupportedSqlShape;
    for (alter.operations, ast.domain_operation_items.items) |operation_plan, item| {
        try validateGeneratedDomainOperationItemMatchesPlan(tokens, item, operation_plan);
    }
}

fn validateGeneratedDomainOperationItems(
    tokens: []const grammar.Token,
    operation_range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (items.count == 0 or
        items.items.len != items.count or
        items.expression_items.len != 0 or
        items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or
        items.direction_items.len != 0 or
        items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or
        items.nulls_order_items.len != 0 or
        items.nulls_orders.len != 0 or
        items.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
    if (!std.meta.eql(items.first_tokens orelse return error.UnsupportedSqlShape, items.items[0])) return error.UnsupportedSqlShape;
    if (!std.meta.eql(items.last_tokens orelse return error.UnsupportedSqlShape, items.items[items.items.len - 1])) return error.UnsupportedSqlShape;

    var expected_start = operation_range.start;
    for (items.items, 0..) |item, item_index| {
        if (item.start != expected_start or item.start >= item.end or item.end > operation_range.end) return error.UnsupportedSqlShape;
        try validateGeneratedDomainOperationItem(tokens, item);
        if (item_index + 1 < items.items.len) {
            if (item.end >= operation_range.end or tokens[item.end].kind != .comma) return error.UnsupportedSqlShape;
            expected_start = item.end + 1;
        } else {
            expected_start = item.end;
        }
    }
    if (expected_start != operation_range.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedCreateDomainOptionItems(
    tokens: []const grammar.Token,
    option_range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (items.count == 0 or
        items.items.len != items.count or
        items.expression_items.len != 0 or
        items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or
        items.direction_items.len != 0 or
        items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or
        items.nulls_order_items.len != 0 or
        items.nulls_orders.len != 0 or
        items.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
    if (!std.meta.eql(items.first_tokens orelse return error.UnsupportedSqlShape, items.items[0])) return error.UnsupportedSqlShape;
    if (!std.meta.eql(items.last_tokens orelse return error.UnsupportedSqlShape, items.items[items.items.len - 1])) return error.UnsupportedSqlShape;

    var expected_start = option_range.start;
    for (items.items) |item| {
        if (item.start != expected_start or item.start >= item.end or item.end > option_range.end) return error.UnsupportedSqlShape;
        try validateGeneratedCreateDomainOptionItem(tokens, item);
        expected_start = item.end;
    }
    if (expected_start != option_range.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedEmptyDomainCreateOptionPayloadItems(ast: *const generated_parser.GeneratedSqlDdlAst) !void {
    if (ast.domain_operation_kind_items.len != 0 or
        ast.domain_operation_constraint_name_items.len != 0 or
        ast.domain_operation_default_value_items.len != 0 or
        ast.domain_operation_check_payload_items.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedCreateDomainOptionPayloadItems(
    tokens: []const grammar.Token,
    ast: *const generated_parser.GeneratedSqlDdlAst,
) !void {
    const count = ast.domain_operation_items.count;
    if (count == 0) return try validateGeneratedEmptyDomainCreateOptionPayloadItems(ast);
    if (ast.domain_operation_items.items.len != count or
        ast.domain_operation_kind_items.len != count or
        ast.domain_operation_constraint_name_items.len != count or
        ast.domain_operation_default_value_items.len != count or
        ast.domain_operation_check_payload_items.len != count or
        ast.domain_operation_check_payload_expressions.len != count)
    {
        return error.UnsupportedSqlShape;
    }
    for (ast.domain_operation_items.items, 0..) |item, index| {
        const expected = generatedCreateDomainOptionPayloadRanges(tokens, item) orelse return error.UnsupportedSqlShape;
        const kind = ast.domain_operation_kind_items[index];
        if (kind.end > tokens.len or !std.meta.eql(kind, expected.kind)) return error.UnsupportedSqlShape;
        if (!generatedOptionalRangeEqual(ast.domain_operation_constraint_name_items[index], expected.constraint_name)) return error.UnsupportedSqlShape;
        if (!generatedOptionalRangeEqual(ast.domain_operation_default_value_items[index], expected.default_value)) return error.UnsupportedSqlShape;
        if (!generatedOptionalRangeEqual(ast.domain_operation_check_payload_items[index], expected.check_payload)) return error.UnsupportedSqlShape;
        if (ast.domain_operation_check_payload_items[index]) |payload| {
            if (!generatedParenthesizedRangeIsValid(tokens, payload)) return error.UnsupportedSqlShape;
            try validateGeneratedDdlCheckPayloadExpressionAst(tokens, payload, &ast.domain_operation_check_payload_expressions[index]);
        } else if (ast.domain_operation_check_payload_expressions[index].tokens != null) {
            return error.UnsupportedSqlShape;
        }
    }
}

const GeneratedCreateDomainOptionPayloadRanges = struct {
    kind: generated_parser.GeneratedSqlTokenRange,
    constraint_name: ?generated_parser.GeneratedSqlTokenRange = null,
    default_value: ?generated_parser.GeneratedSqlTokenRange = null,
    check_payload: ?generated_parser.GeneratedSqlTokenRange = null,
};

fn generatedCreateDomainOptionPayloadRanges(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
) ?GeneratedCreateDomainOptionPayloadRanges {
    if (item.start >= item.end or item.end > tokens.len) return null;
    if (tokens[item.start].matchesKeyword("default")) {
        if (item.start + 1 >= item.end) return null;
        return .{
            .kind = .{ .start = item.start, .end = item.start + 1 },
            .default_value = .{ .start = item.start + 1, .end = item.end },
        };
    }
    if (tokens[item.start].matchesKeyword("not")) {
        if (item.start + 2 != item.end or !tokens[item.start + 1].matchesKeyword("null")) return null;
        return .{ .kind = item };
    }
    if (tokens[item.start].matchesKeyword("null")) {
        if (item.start + 1 != item.end) return null;
        return .{ .kind = item };
    }
    if (tokens[item.start].matchesKeyword("constraint")) {
        if (item.start + 4 > item.end or tokens[item.start + 1].kind != .identifier or !tokens[item.start + 2].matchesKeyword("check")) return null;
        return .{
            .kind = .{ .start = item.start + 2, .end = item.start + 3 },
            .constraint_name = .{ .start = item.start + 1, .end = item.start + 2 },
            .check_payload = .{ .start = item.start + 3, .end = item.end },
        };
    }
    if (tokens[item.start].matchesKeyword("check")) {
        if (item.start + 2 > item.end) return null;
        return .{
            .kind = .{ .start = item.start, .end = item.start + 1 },
            .check_payload = .{ .start = item.start + 1, .end = item.end },
        };
    }
    return null;
}

fn generatedOptionalRangeEqual(
    actual: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?generated_parser.GeneratedSqlTokenRange,
) bool {
    if (actual == null or expected == null) return actual == null and expected == null;
    return std.meta.eql(actual.?, expected.?);
}

fn generatedParenthesizedRangeIsValid(
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) bool {
    if (range.end > tokens.len or range.start >= range.end or tokens[range.start].kind != .lparen) return false;
    const close_index = findGeneratedMatchingParen(tokens, range.start, range.end) orelse return false;
    return close_index + 1 == range.end;
}

fn validateGeneratedCreateDomainOptionItem(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[item.start].matchesKeyword("default")) {
        if (item.start + 1 < item.end) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("not")) {
        if (item.start + 2 == item.end and tokens[item.start + 1].matchesKeyword("null")) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("null")) {
        if (item.start + 1 == item.end) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("constraint")) {
        if (item.start + 4 <= item.end and tokens[item.start + 1].kind == .identifier and tokens[item.start + 2].matchesKeyword("check")) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("check")) {
        if (item.start + 2 <= item.end) return;
        return error.UnsupportedSqlShape;
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedDomainOperationItem(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[item.start].matchesKeyword("set")) {
        if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("not") and tokens[item.start + 2].matchesKeyword("null")) return;
        if (item.start + 3 <= item.end and tokens[item.start + 1].matchesKeyword("default")) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("drop")) {
        if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("not") and tokens[item.start + 2].matchesKeyword("null")) return;
        if (item.start + 2 == item.end and tokens[item.start + 1].matchesKeyword("default")) return;
        return error.UnsupportedSqlShape;
    }
    return error.UnsupportedSqlShape;
}

fn generatedDomainAlterOperationAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
) !DomainAlterOperation {
    if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[item.start].matchesKeyword("set")) {
        if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("not") and tokens[item.start + 2].matchesKeyword("null")) return .set_not_null;
        if (item.start + 3 <= item.end and tokens[item.start + 1].matchesKeyword("default")) {
            var pos = item.start + 2;
            const default_value = try parseDdlDefaultValueUntypedLiteralAlloc(alloc, tokens, &pos);
            errdefer alloc.free(default_value.value_json);
            if (pos != item.end) return error.UnsupportedSqlShape;
            return .{ .set_default = default_value };
        }
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("drop")) {
        if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("not") and tokens[item.start + 2].matchesKeyword("null")) return .drop_not_null;
        if (item.start + 2 == item.end and tokens[item.start + 1].matchesKeyword("default")) return .drop_default;
        return error.UnsupportedSqlShape;
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedDomainOperationItemMatchesPlan(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
    operation: DomainAlterOperation,
) !void {
    switch (operation) {
        .set_not_null => {
            if (item.start + 3 != item.end or !tokens[item.start].matchesKeyword("set") or !tokens[item.start + 1].matchesKeyword("not") or !tokens[item.start + 2].matchesKeyword("null")) return error.UnsupportedSqlShape;
        },
        .drop_not_null => {
            if (item.start + 3 != item.end or !tokens[item.start].matchesKeyword("drop") or !tokens[item.start + 1].matchesKeyword("not") or !tokens[item.start + 2].matchesKeyword("null")) return error.UnsupportedSqlShape;
        },
        .set_default => {
            if (item.start + 3 > item.end or !tokens[item.start].matchesKeyword("set") or !tokens[item.start + 1].matchesKeyword("default")) return error.UnsupportedSqlShape;
        },
        .drop_default => {
            if (item.start + 2 != item.end or !tokens[item.start].matchesKeyword("drop") or !tokens[item.start + 1].matchesKeyword("default")) return error.UnsupportedSqlShape;
        },
    }
}

fn sequenceCatalogPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    _ = options;
    try validateGeneratedSequenceDdlAst(tokens, ast);
    var plan: DdlPlan = .{ .sequence_catalog = switch (ast.kind) {
        .create_sequence => .{ .create = try generatedCreateSequencePlanAlloc(alloc, tokens, ast) },
        .alter_sequence => .{ .alter = try generatedAlterSequencePlanAlloc(alloc, tokens, ast) },
        .drop_sequence => .{ .drop = try generatedDropSequencePlanAlloc(alloc, tokens, ast) },
        else => return error.UnsupportedSqlShape,
    } };
    errdefer plan.deinit(alloc);
    switch (ast.kind) {
        .create_sequence => switch (plan) {
            .sequence_catalog => |catalog| switch (catalog) {
                .create => |create| try validateGeneratedCreateSequencePlan(alloc, tokens, ast, create),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .alter_sequence => switch (plan) {
            .sequence_catalog => |catalog| switch (catalog) {
                .alter => |alter| try validateGeneratedSequenceAlterPlan(tokens, ast, alter),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .drop_sequence => switch (plan) {
            .sequence_catalog => |catalog| switch (catalog) {
                .drop => |drop| try validateGeneratedDropSequencePlan(alloc, tokens, ast, drop),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn generatedCreateSequencePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !CreateSequencePlan {
    var plan = CreateSequencePlan{
        .sequence_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .if_not_exists = ast.if_not_exists,
    };
    errdefer plan.deinit(alloc);

    const operation = ast.alter_table_operation_tokens orelse {
        try validateGeneratedEmptyListAst(&ast.sequence_operation_items);
        return plan;
    };
    try validateGeneratedSequenceOperationItems(tokens, operation, &ast.sequence_operation_items);
    for (ast.sequence_operation_items.items) |item| {
        try generatedApplyCreateSequenceOptionItemAlloc(alloc, tokens, item, &plan.options);
    }
    return plan;
}

fn generatedAlterSequencePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !AlterSequencePlan {
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedSequenceOperationItems(tokens, operation, &ast.sequence_operation_items);
    const operations = try alloc.alloc(SequenceAlterOperation, ast.sequence_operation_items.count);
    errdefer alloc.free(operations);
    var initialized: usize = 0;
    errdefer freeSequenceAlterOperations(alloc, operations[0..initialized]);
    for (ast.sequence_operation_items.items, 0..) |item, index| {
        operations[index] = try generatedSequenceAlterOperationAlloc(alloc, tokens, item);
        initialized += 1;
    }

    return .{
        .sequence_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .if_exists = ast.if_exists,
        .operations = operations,
    };
}

fn generatedDropSequencePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !DropSequencePlan {
    return .{
        .sequence_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .if_exists = ast.if_exists,
        .cascade = ast.cascade,
    };
}

fn validateGeneratedSequenceDdlAst(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const object_name = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    if (object_name.start >= object_name.end or object_name.end > end) return error.UnsupportedSqlShape;
    switch (ast.kind) {
        .create_sequence => {
            if (end < 3 or !tokens[0].matchesKeyword("create") or !tokens[1].matchesKeyword("sequence")) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_not_exists = consumeGeneratedPlanIfNotExists(tokens, &name_index, end);
            if (if_not_exists != ast.if_not_exists) return error.UnsupportedSqlShape;
            if (object_name.start != name_index) return error.UnsupportedSqlShape;
            if (object_name.end < end) {
                const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
                if (operation.start != object_name.end or operation.end != end) return error.UnsupportedSqlShape;
            } else if (ast.alter_table_operation_tokens != null) {
                return error.UnsupportedSqlShape;
            }
        },
        .alter_sequence => {
            if (end < 4 or !tokens[0].matchesKeyword("alter") or !tokens[1].matchesKeyword("sequence")) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_exists = consumeGeneratedPlanIfExists(tokens, &name_index, end);
            if (if_exists != ast.if_exists) return error.UnsupportedSqlShape;
            if (object_name.start != name_index) return error.UnsupportedSqlShape;
            const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (operation.start != object_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
            try validateGeneratedSequenceOperationItems(tokens, operation, &ast.sequence_operation_items);
        },
        .drop_sequence => {
            if (end < 3 or !tokens[0].matchesKeyword("drop") or !tokens[1].matchesKeyword("sequence")) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_exists = consumeGeneratedPlanIfExists(tokens, &name_index, end);
            if (if_exists != ast.if_exists) return error.UnsupportedSqlShape;
            if (object_name.start != name_index) return error.UnsupportedSqlShape;
            const has_cascade = generatedRangeHasKeyword(tokens, .{ .start = object_name.end, .end = end }, "cascade");
            if (has_cascade != ast.cascade) return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedCreateSequencePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    create: CreateSequencePlan,
) !void {
    if (create.if_not_exists != ast.if_not_exists) return error.UnsupportedSqlShape;
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedIdentifierRangeMatchesQualifiedTail(alloc, tokens, ast.object_name_tokens, name_range.start, create.sequence_name);
    const expected_count = generatedSequenceOptionsCount(create.options);
    const operation = ast.alter_table_operation_tokens orelse {
        if (expected_count != 0) return error.UnsupportedSqlShape;
        try validateGeneratedEmptyListAst(&ast.sequence_operation_items);
        return;
    };
    try validateGeneratedSequenceOperationItems(tokens, operation, &ast.sequence_operation_items);
    if (ast.sequence_operation_items.count != expected_count) return error.UnsupportedSqlShape;
    for (ast.sequence_operation_items.items) |item| {
        try validateGeneratedCreateSequenceOptionItemMatchesPlan(tokens, item, create.options);
    }
}

fn validateGeneratedDropSequencePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    drop: DropSequencePlan,
) !void {
    if (drop.if_exists != ast.if_exists or drop.cascade != ast.cascade) return error.UnsupportedSqlShape;
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedIdentifierRangeMatchesQualifiedTail(alloc, tokens, ast.object_name_tokens, name_range.start, drop.sequence_name);
}

fn generatedSequenceOptionsCount(options: SequenceOptions) usize {
    var count: usize = 0;
    if (options.as_type != null) count += 1;
    if (options.start_with != null) count += 1;
    if (options.increment_by != null) count += 1;
    if (options.min_value_specified) count += 1;
    if (options.max_value_specified) count += 1;
    if (options.cache != null) count += 1;
    if (options.cycle != null) count += 1;
    if (options.owned_by != null) count += 1;
    return count;
}

fn validateGeneratedCreateSequenceOptionItemMatchesPlan(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
    options: SequenceOptions,
) !void {
    if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[item.start].matchesKeyword("as")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        const as_type = options.as_type orelse return error.UnsupportedSqlShape;
        if (!std.ascii.eqlIgnoreCase(tokens[item.start + 1].text, as_type)) return error.UnsupportedSqlShape;
        return;
    }
    if (tokens[item.start].matchesKeyword("owned")) {
        if (item.start + 3 != item.end or !tokens[item.start + 1].matchesKeyword("by")) return error.UnsupportedSqlShape;
        if (!generatedSequenceOwnedByMatches(tokens[item.start + 2], options.owned_by orelse return error.UnsupportedSqlShape)) return error.UnsupportedSqlShape;
        return;
    }
    if (tokens[item.start].matchesKeyword("start")) {
        const value_index = if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("with")) item.start + 2 else item.start + 1;
        if (value_index + 1 != item.end) return error.UnsupportedSqlShape;
        if ((try generatedSequenceIntegerValue(tokens, value_index)) != (options.start_with orelse return error.UnsupportedSqlShape)) return error.UnsupportedSqlShape;
        return;
    }
    if (tokens[item.start].matchesKeyword("increment")) {
        const value_index = if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("by")) item.start + 2 else item.start + 1;
        if (value_index + 1 != item.end) return error.UnsupportedSqlShape;
        if ((try generatedSequenceIntegerValue(tokens, value_index)) != (options.increment_by orelse return error.UnsupportedSqlShape)) return error.UnsupportedSqlShape;
        return;
    }
    if (tokens[item.start].matchesKeyword("minvalue")) {
        if (item.start + 2 != item.end or !options.min_value_specified) return error.UnsupportedSqlShape;
        if ((try generatedSequenceIntegerValue(tokens, item.start + 1)) != (options.min_value orelse return error.UnsupportedSqlShape)) return error.UnsupportedSqlShape;
        return;
    }
    if (tokens[item.start].matchesKeyword("maxvalue")) {
        if (item.start + 2 != item.end or !options.max_value_specified) return error.UnsupportedSqlShape;
        if ((try generatedSequenceIntegerValue(tokens, item.start + 1)) != (options.max_value orelse return error.UnsupportedSqlShape)) return error.UnsupportedSqlShape;
        return;
    }
    if (tokens[item.start].matchesKeyword("cache")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        if ((try generatedSequenceIntegerValue(tokens, item.start + 1)) != (options.cache orelse return error.UnsupportedSqlShape)) return error.UnsupportedSqlShape;
        return;
    }
    if (tokens[item.start].matchesKeyword("cycle")) {
        if (item.start + 1 != item.end or (options.cycle orelse return error.UnsupportedSqlShape) != true) return error.UnsupportedSqlShape;
        return;
    }
    if (tokens[item.start].matchesKeyword("no")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        if (tokens[item.start + 1].matchesKeyword("minvalue")) {
            if (!options.min_value_specified or options.min_value != null) return error.UnsupportedSqlShape;
            return;
        }
        if (tokens[item.start + 1].matchesKeyword("maxvalue")) {
            if (!options.max_value_specified or options.max_value != null) return error.UnsupportedSqlShape;
            return;
        }
        if (tokens[item.start + 1].matchesKeyword("cycle")) {
            if ((options.cycle orelse return error.UnsupportedSqlShape) != false) return error.UnsupportedSqlShape;
            return;
        }
    }
    return error.UnsupportedSqlShape;
}

fn generatedApplyCreateSequenceOptionItemAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
    options: *SequenceOptions,
) !void {
    if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[item.start].matchesKeyword("as")) {
        if (options.as_type != null or item.start + 2 != item.end) return error.UnsupportedSqlShape;
        options.as_type = try generatedSequenceTypeNameAlloc(alloc, tokens[item.start + 1]);
        return;
    }
    if (tokens[item.start].matchesKeyword("owned")) {
        if (options.owned_by != null or item.start + 3 != item.end or !tokens[item.start + 1].matchesKeyword("by")) return error.UnsupportedSqlShape;
        options.owned_by = try generatedSequenceOwnedByAlloc(alloc, tokens[item.start + 2]);
        return;
    }
    if (tokens[item.start].matchesKeyword("start")) {
        if (options.start_with != null) return error.UnsupportedSqlShape;
        const value_index = if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("with")) item.start + 2 else item.start + 1;
        if (value_index + 1 != item.end) return error.UnsupportedSqlShape;
        options.start_with = try generatedSequenceIntegerValue(tokens, value_index);
        return;
    }
    if (tokens[item.start].matchesKeyword("increment")) {
        if (options.increment_by != null) return error.UnsupportedSqlShape;
        const value_index = if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("by")) item.start + 2 else item.start + 1;
        if (value_index + 1 != item.end) return error.UnsupportedSqlShape;
        options.increment_by = try generatedSequenceIntegerValue(tokens, value_index);
        return;
    }
    if (tokens[item.start].matchesKeyword("minvalue")) {
        if (options.min_value_specified or item.start + 2 != item.end) return error.UnsupportedSqlShape;
        options.min_value_specified = true;
        options.min_value = try generatedSequenceIntegerValue(tokens, item.start + 1);
        return;
    }
    if (tokens[item.start].matchesKeyword("maxvalue")) {
        if (options.max_value_specified or item.start + 2 != item.end) return error.UnsupportedSqlShape;
        options.max_value_specified = true;
        options.max_value = try generatedSequenceIntegerValue(tokens, item.start + 1);
        return;
    }
    if (tokens[item.start].matchesKeyword("cache")) {
        if (options.cache != null or item.start + 2 != item.end) return error.UnsupportedSqlShape;
        options.cache = try generatedSequenceIntegerValue(tokens, item.start + 1);
        return;
    }
    if (tokens[item.start].matchesKeyword("cycle")) {
        if (options.cycle != null or item.start + 1 != item.end) return error.UnsupportedSqlShape;
        options.cycle = true;
        return;
    }
    if (tokens[item.start].matchesKeyword("no")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        if (tokens[item.start + 1].matchesKeyword("minvalue")) {
            if (options.min_value_specified) return error.UnsupportedSqlShape;
            options.min_value_specified = true;
            options.min_value = null;
            return;
        }
        if (tokens[item.start + 1].matchesKeyword("maxvalue")) {
            if (options.max_value_specified) return error.UnsupportedSqlShape;
            options.max_value_specified = true;
            options.max_value = null;
            return;
        }
        if (tokens[item.start + 1].matchesKeyword("cycle")) {
            if (options.cycle != null) return error.UnsupportedSqlShape;
            options.cycle = false;
            return;
        }
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedSequenceAlterPlan(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    alter: AlterSequencePlan,
) !void {
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedSequenceOperationItems(tokens, operation, &ast.sequence_operation_items);
    if (alter.operations.len != ast.sequence_operation_items.count) return error.UnsupportedSqlShape;
    for (alter.operations, ast.sequence_operation_items.items) |operation_plan, item| {
        try validateGeneratedSequenceOperationItemMatchesPlan(tokens, item, operation_plan);
    }
}

fn validateGeneratedSequenceOperationItems(
    tokens: []const grammar.Token,
    operation_range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (items.count == 0 or
        items.items.len != items.count or
        items.expression_items.len != 0 or
        items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or
        items.direction_items.len != 0 or
        items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or
        items.nulls_order_items.len != 0 or
        items.nulls_orders.len != 0 or
        items.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
    if (!std.meta.eql(items.first_tokens orelse return error.UnsupportedSqlShape, items.items[0])) return error.UnsupportedSqlShape;
    if (!std.meta.eql(items.last_tokens orelse return error.UnsupportedSqlShape, items.items[items.items.len - 1])) return error.UnsupportedSqlShape;

    var expected_start = operation_range.start;
    for (items.items) |item| {
        if (item.start != expected_start or item.start >= item.end or item.end > operation_range.end) return error.UnsupportedSqlShape;
        try validateGeneratedSequenceOperationItem(tokens, item);
        expected_start = item.end;
    }
    if (expected_start != operation_range.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedSequenceOperationItem(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[item.start].matchesKeyword("as")) {
        if (item.start + 2 == item.end) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("owned")) {
        if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("by")) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("restart")) {
        if (item.start + 1 == item.end) return;
        if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("with")) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("start")) {
        if (item.start + 2 == item.end) return;
        if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("with")) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("increment")) {
        if (item.start + 2 == item.end) return;
        if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("by")) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("minvalue") or tokens[item.start].matchesKeyword("maxvalue") or tokens[item.start].matchesKeyword("cache")) {
        if (item.start + 2 == item.end) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("cycle")) {
        if (item.start + 1 == item.end) return;
        return error.UnsupportedSqlShape;
    }
    if (tokens[item.start].matchesKeyword("no")) {
        if (item.start + 2 == item.end and
            (tokens[item.start + 1].matchesKeyword("minvalue") or
                tokens[item.start + 1].matchesKeyword("maxvalue") or
                tokens[item.start + 1].matchesKeyword("cycle")))
        {
            return;
        }
        return error.UnsupportedSqlShape;
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedSequenceOperationItemMatchesPlan(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
    operation: SequenceAlterOperation,
) !void {
    switch (operation) {
        .set_type => |type_name| {
            if (item.start + 2 != item.end or !tokens[item.start].matchesKeyword("as")) return error.UnsupportedSqlShape;
            if (!std.ascii.eqlIgnoreCase(tokens[item.start + 1].text, type_name)) return error.UnsupportedSqlShape;
        },
        .restart => |value| {
            if (!tokens[item.start].matchesKeyword("restart")) return error.UnsupportedSqlShape;
            if (value) |expected| {
                if (item.start + 3 != item.end or !tokens[item.start + 1].matchesKeyword("with")) return error.UnsupportedSqlShape;
                if ((try generatedSequenceIntegerValue(tokens, item.start + 2)) != expected) return error.UnsupportedSqlShape;
            } else if (item.start + 1 != item.end) return error.UnsupportedSqlShape;
        },
        .set_start => |expected| {
            if (!tokens[item.start].matchesKeyword("start")) return error.UnsupportedSqlShape;
            const value_index = if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("with")) item.start + 2 else item.start + 1;
            if (value_index + 1 != item.end) return error.UnsupportedSqlShape;
            if ((try generatedSequenceIntegerValue(tokens, value_index)) != expected) return error.UnsupportedSqlShape;
        },
        .set_increment => |expected| {
            if (!tokens[item.start].matchesKeyword("increment")) return error.UnsupportedSqlShape;
            const value_index = if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("by")) item.start + 2 else item.start + 1;
            if (value_index + 1 != item.end) return error.UnsupportedSqlShape;
            if ((try generatedSequenceIntegerValue(tokens, value_index)) != expected) return error.UnsupportedSqlShape;
        },
        .set_min => |value| {
            if (value) |expected| {
                if (item.start + 2 != item.end or !tokens[item.start].matchesKeyword("minvalue")) return error.UnsupportedSqlShape;
                if ((try generatedSequenceIntegerValue(tokens, item.start + 1)) != expected) return error.UnsupportedSqlShape;
            } else if (item.start + 2 != item.end or !tokens[item.start].matchesKeyword("no") or !tokens[item.start + 1].matchesKeyword("minvalue")) return error.UnsupportedSqlShape;
        },
        .set_max => |value| {
            if (value) |expected| {
                if (item.start + 2 != item.end or !tokens[item.start].matchesKeyword("maxvalue")) return error.UnsupportedSqlShape;
                if ((try generatedSequenceIntegerValue(tokens, item.start + 1)) != expected) return error.UnsupportedSqlShape;
            } else if (item.start + 2 != item.end or !tokens[item.start].matchesKeyword("no") or !tokens[item.start + 1].matchesKeyword("maxvalue")) return error.UnsupportedSqlShape;
        },
        .set_cache => |expected| {
            if (item.start + 2 != item.end or !tokens[item.start].matchesKeyword("cache")) return error.UnsupportedSqlShape;
            if ((try generatedSequenceIntegerValue(tokens, item.start + 1)) != expected) return error.UnsupportedSqlShape;
        },
        .set_cycle => |enabled| {
            if (enabled) {
                if (item.start + 1 != item.end or !tokens[item.start].matchesKeyword("cycle")) return error.UnsupportedSqlShape;
            } else if (item.start + 2 != item.end or !tokens[item.start].matchesKeyword("no") or !tokens[item.start + 1].matchesKeyword("cycle")) return error.UnsupportedSqlShape;
        },
        .set_owned_by => |owned_by| {
            if (item.start + 3 != item.end or !tokens[item.start].matchesKeyword("owned") or !tokens[item.start + 1].matchesKeyword("by")) return error.UnsupportedSqlShape;
            if (!generatedSequenceOwnedByMatches(tokens[item.start + 2], owned_by)) return error.UnsupportedSqlShape;
        },
    }
}

fn generatedSequenceAlterOperationAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
) !SequenceAlterOperation {
    if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[item.start].matchesKeyword("as")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        return .{ .set_type = try generatedSequenceTypeNameAlloc(alloc, tokens[item.start + 1]) };
    }
    if (tokens[item.start].matchesKeyword("owned")) {
        if (item.start + 3 != item.end or !tokens[item.start + 1].matchesKeyword("by")) return error.UnsupportedSqlShape;
        return .{ .set_owned_by = try generatedSequenceOwnedByAlloc(alloc, tokens[item.start + 2]) };
    }
    if (tokens[item.start].matchesKeyword("restart")) {
        if (item.start + 1 == item.end) return .{ .restart = null };
        if (item.start + 3 != item.end or !tokens[item.start + 1].matchesKeyword("with")) return error.UnsupportedSqlShape;
        return .{ .restart = try generatedSequenceIntegerValue(tokens, item.start + 2) };
    }
    if (tokens[item.start].matchesKeyword("start")) {
        const value_index = if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("with")) item.start + 2 else item.start + 1;
        if (value_index + 1 != item.end) return error.UnsupportedSqlShape;
        return .{ .set_start = try generatedSequenceIntegerValue(tokens, value_index) };
    }
    if (tokens[item.start].matchesKeyword("increment")) {
        const value_index = if (item.start + 3 == item.end and tokens[item.start + 1].matchesKeyword("by")) item.start + 2 else item.start + 1;
        if (value_index + 1 != item.end) return error.UnsupportedSqlShape;
        return .{ .set_increment = try generatedSequenceIntegerValue(tokens, value_index) };
    }
    if (tokens[item.start].matchesKeyword("minvalue")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        return .{ .set_min = try generatedSequenceIntegerValue(tokens, item.start + 1) };
    }
    if (tokens[item.start].matchesKeyword("maxvalue")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        return .{ .set_max = try generatedSequenceIntegerValue(tokens, item.start + 1) };
    }
    if (tokens[item.start].matchesKeyword("cache")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        return .{ .set_cache = try generatedSequenceIntegerValue(tokens, item.start + 1) };
    }
    if (tokens[item.start].matchesKeyword("cycle")) {
        if (item.start + 1 != item.end) return error.UnsupportedSqlShape;
        return .{ .set_cycle = true };
    }
    if (tokens[item.start].matchesKeyword("no")) {
        if (item.start + 2 != item.end) return error.UnsupportedSqlShape;
        if (tokens[item.start + 1].matchesKeyword("minvalue")) return .{ .set_min = null };
        if (tokens[item.start + 1].matchesKeyword("maxvalue")) return .{ .set_max = null };
        if (tokens[item.start + 1].matchesKeyword("cycle")) return .{ .set_cycle = false };
    }
    return error.UnsupportedSqlShape;
}

fn generatedSequenceTypeNameAlloc(alloc: std.mem.Allocator, token: grammar.Token) ![]const u8 {
    if (token.kind != .identifier) return error.UnsupportedSqlShape;
    if (std.ascii.eqlIgnoreCase(token.text, "smallint")) return try alloc.dupe(u8, "smallint");
    if (std.ascii.eqlIgnoreCase(token.text, "integer") or std.ascii.eqlIgnoreCase(token.text, "int")) return try alloc.dupe(u8, "integer");
    if (std.ascii.eqlIgnoreCase(token.text, "bigint")) return try alloc.dupe(u8, "bigint");
    return error.UnsupportedSqlShape;
}

fn generatedSequenceIntegerValue(tokens: []const grammar.Token, index: usize) !i64 {
    if (index >= tokens.len) return error.UnsupportedSqlShape;
    return std.fmt.parseInt(i64, tokens[index].text, 10) catch return error.UnsupportedSqlShape;
}

fn generatedSequenceOwnedByAlloc(alloc: std.mem.Allocator, token: grammar.Token) !SequenceOwnedBy {
    if (token.matchesKeyword("none")) return .{};
    if (token.kind != .identifier) return error.UnsupportedSqlShape;
    const raw = token.text;
    const first_dot = std.mem.indexOfScalar(u8, raw, '.') orelse return error.UnsupportedSqlShape;
    const table_start = if (std.ascii.eqlIgnoreCase(raw[0..first_dot], "public")) first_dot + 1 else 0;
    const table_and_column = raw[table_start..];
    const dot = std.mem.indexOfScalar(u8, table_and_column, '.') orelse return error.UnsupportedSqlShape;
    if (std.mem.indexOfScalar(u8, table_and_column[dot + 1 ..], '.') != null) return error.UnsupportedSqlShape;
    const table_name = table_and_column[0..dot];
    const column_name = table_and_column[dot + 1 ..];
    if (table_name.len == 0 or column_name.len == 0) return error.UnsupportedSqlShape;
    const owned_table_name = try alloc.dupe(u8, table_name);
    errdefer alloc.free(owned_table_name);
    return .{
        .table_name = owned_table_name,
        .column_name = try alloc.dupe(u8, column_name),
    };
}

fn generatedSequenceOwnedByMatches(token: grammar.Token, owned_by: SequenceOwnedBy) bool {
    if (owned_by.table_name.len == 0 and owned_by.column_name.len == 0) return token.matchesKeyword("none");
    if (token.matchesKeyword("none")) return false;
    const raw = token.text;
    const first_dot = std.mem.indexOfScalar(u8, raw, '.') orelse return false;
    const table_start = if (std.ascii.eqlIgnoreCase(raw[0..first_dot], "public")) first_dot + 1 else 0;
    const table_and_column = raw[table_start..];
    const dot = std.mem.indexOfScalar(u8, table_and_column, '.') orelse return false;
    return std.ascii.eqlIgnoreCase(table_and_column[0..dot], owned_by.table_name) and
        std.ascii.eqlIgnoreCase(table_and_column[dot + 1 ..], owned_by.column_name);
}

fn enumTypeCatalogPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    _ = options;
    try validateGeneratedEnumTypeDdlAst(tokens, ast);
    var plan: DdlPlan = .{ .enum_type_catalog = switch (ast.kind) {
        .create_enum_type => .{ .create = try generatedCreateEnumTypePlanAlloc(alloc, tokens, ast) },
        .alter_enum_type => .{ .add_value = try generatedAddEnumValuePlanAlloc(alloc, tokens, ast) },
        .drop_enum_type => .{ .drop = try generatedDropEnumTypePlanAlloc(alloc, tokens, ast) },
        else => return error.UnsupportedSqlShape,
    } };
    errdefer plan.deinit(alloc);
    switch (ast.kind) {
        .create_enum_type => switch (plan) {
            .enum_type_catalog => |catalog| switch (catalog) {
                .create => |create| try validateGeneratedCreateEnumTypePlan(alloc, tokens, ast, create),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .alter_enum_type => switch (plan) {
            .enum_type_catalog => |catalog| switch (catalog) {
                .add_value => |add| {
                    const value_range = ast.enum_value_tokens orelse return error.UnsupportedSqlShape;
                    const generated_value = try generatedStringLiteralValueAlloc(alloc, tokens, value_range);
                    defer alloc.free(@constCast(generated_value));
                    if (!std.mem.eql(u8, generated_value, add.value)) return error.UnsupportedSqlShape;
                    const generated_position = generatedEnumValuePositionFromGenerated(ast.enum_value_position);
                    if (generated_position != add.position) return error.UnsupportedSqlShape;
                    if (ast.enum_value_if_not_exists != add.if_not_exists) return error.UnsupportedSqlShape;
                    if (add.position == .none) {
                        if (ast.enum_neighbor_value_tokens != null or add.neighbor_value != null) return error.UnsupportedSqlShape;
                    } else {
                        const neighbor_range = ast.enum_neighbor_value_tokens orelse return error.UnsupportedSqlShape;
                        const generated_neighbor = try generatedStringLiteralValueAlloc(alloc, tokens, neighbor_range);
                        defer alloc.free(@constCast(generated_neighbor));
                        if (add.neighbor_value == null or !std.mem.eql(u8, generated_neighbor, add.neighbor_value.?)) return error.UnsupportedSqlShape;
                    }
                },
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .drop_enum_type => switch (plan) {
            .enum_type_catalog => |catalog| switch (catalog) {
                .drop => |drop| try validateGeneratedDropEnumTypePlan(alloc, tokens, ast, drop),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn generatedCreateEnumTypePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !CreateEnumTypePlan {
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (operation.start + 4 > operation.end or !tokens[operation.start].matchesKeyword("as") or !tokens[operation.start + 1].matchesKeyword("enum") or tokens[operation.start + 2].kind != .lparen) {
        return error.UnsupportedSqlShape;
    }
    const values_close = findGeneratedMatchingParen(tokens, operation.start + 2, operation.end) orelse return error.UnsupportedSqlShape;
    if (values_close + 1 != operation.end) return error.UnsupportedSqlShape;
    try validateGeneratedPlainListCount(tokens, .{ .start = operation.start + 3, .end = values_close }, &ast.enum_value_items, ast.enum_value_items.count);

    const type_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(type_name);
    const values = try generatedUniqueStringLiteralListAlloc(alloc, tokens, &ast.enum_value_items);
    errdefer freeStringSlice(alloc, values);
    return .{
        .type_name = type_name,
        .values = values,
    };
}

fn generatedAddEnumValuePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !AddEnumValuePlan {
    const type_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(type_name);
    const value = try generatedStringLiteralValueAlloc(alloc, tokens, ast.enum_value_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(value);

    var neighbor_value: ?[]const u8 = null;
    errdefer if (neighbor_value) |neighbor| alloc.free(neighbor);
    const position = generatedEnumValuePositionFromGenerated(ast.enum_value_position);
    if (position == .none) {
        if (ast.enum_neighbor_value_tokens != null) return error.UnsupportedSqlShape;
    } else {
        neighbor_value = try generatedStringLiteralValueAlloc(alloc, tokens, ast.enum_neighbor_value_tokens orelse return error.UnsupportedSqlShape);
    }

    const out = AddEnumValuePlan{
        .type_name = type_name,
        .value = value,
        .if_not_exists = ast.enum_value_if_not_exists,
        .position = position,
        .neighbor_value = neighbor_value,
    };
    neighbor_value = null;
    return out;
}

fn generatedDropEnumTypePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !DropEnumTypePlan {
    return .{
        .type_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .if_exists = ast.if_exists,
        .cascade = ast.cascade,
    };
}

fn generatedEnumValuePositionFromGenerated(position: generated_parser.GeneratedSqlEnumValuePosition) EnumValuePosition {
    return switch (position) {
        .none => .none,
        .before => .before,
        .after => .after,
    };
}

fn validateGeneratedCreateEnumTypePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    create: CreateEnumTypePlan,
) !void {
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.object_name_tokens, name_range.start, create.type_name);
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (operation.start + 4 > operation.end or !tokens[operation.start].matchesKeyword("as") or !tokens[operation.start + 1].matchesKeyword("enum") or tokens[operation.start + 2].kind != .lparen) return error.UnsupportedSqlShape;
    const values_close = findGeneratedMatchingParen(tokens, operation.start + 2, operation.end) orelse return error.UnsupportedSqlShape;
    if (values_close + 1 != operation.end) return error.UnsupportedSqlShape;
    try validateGeneratedStringLiteralListMatches(alloc, tokens, .{ .start = operation.start + 3, .end = values_close }, &ast.enum_value_items, create.values);
}

fn validateGeneratedDropEnumTypePlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    drop: DropEnumTypePlan,
) !void {
    if (drop.if_exists != ast.if_exists or drop.cascade != ast.cascade) return error.UnsupportedSqlShape;
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.object_name_tokens, name_range.start, drop.type_name);
}

fn generatedUniqueStringLiteralListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    items: *const generated_parser.GeneratedSqlListAst,
) ![]const []const u8 {
    if (items.count == 0 or items.items.len != items.count) return error.UnsupportedSqlShape;
    const values = try alloc.alloc([]const u8, items.count);
    var filled: usize = 0;
    errdefer {
        for (values[0..filled]) |value| alloc.free(value);
        alloc.free(values);
    }
    for (items.items, 0..) |item, index| {
        values[index] = try generatedStringLiteralValueAlloc(alloc, tokens, item);
        filled += 1;
        for (values[0..index]) |existing| {
            if (std.mem.eql(u8, existing, values[index])) return error.UnsupportedSqlShape;
        }
    }
    return values;
}

fn validateGeneratedStringLiteralListMatches(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    expected_range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
    expected_values: []const []const u8,
) !void {
    try validateGeneratedPlainListCount(tokens, expected_range, items, expected_values.len);
    for (items.items, expected_values) |item, expected_value| {
        const generated_value = try generatedStringLiteralValueAlloc(alloc, tokens, item);
        defer alloc.free(@constCast(generated_value));
        if (!std.mem.eql(u8, generated_value, expected_value)) return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedEnumTypeDdlAst(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const object_name = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    if (object_name.start >= object_name.end or object_name.end > end) return error.UnsupportedSqlShape;
    switch (ast.kind) {
        .create_enum_type => {
            if (end < 5 or !tokens[0].matchesKeyword("create") or !tokens[1].matchesKeyword("type")) return error.UnsupportedSqlShape;
            if (object_name.start != 2) return error.UnsupportedSqlShape;
            const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (operation.start != object_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
            if (!tokens[operation.start].matchesKeyword("as")) return error.UnsupportedSqlShape;
        },
        .alter_enum_type => {
            if (end < 5 or !tokens[0].matchesKeyword("alter") or !tokens[1].matchesKeyword("type")) return error.UnsupportedSqlShape;
            if (object_name.start != 2) return error.UnsupportedSqlShape;
            const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (operation.start != object_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
            if (operation.start + 3 > end or !tokens[operation.start].matchesKeyword("add") or !tokens[operation.start + 1].matchesKeyword("value")) return error.UnsupportedSqlShape;
            var value_index = operation.start + 2;
            const if_not_exists = consumeGeneratedPlanIfNotExists(tokens, &value_index, end);
            if (if_not_exists != ast.enum_value_if_not_exists) return error.UnsupportedSqlShape;
            const value_range = try requireGeneratedTokenRangeAt(ast.enum_value_tokens, value_index, end);
            if (tokens[value_range.start].kind != .string) return error.UnsupportedSqlShape;
            value_index = value_range.end;
            switch (ast.enum_value_position) {
                .none => {
                    if (value_index != end or ast.enum_neighbor_value_tokens != null) return error.UnsupportedSqlShape;
                },
                .before, .after => |position| {
                    if (value_index + 2 != end) return error.UnsupportedSqlShape;
                    const expected = switch (position) {
                        .before => "before",
                        .after => "after",
                        .none => unreachable,
                    };
                    if (!tokens[value_index].matchesKeyword(expected)) return error.UnsupportedSqlShape;
                    const neighbor_range = try requireGeneratedTokenRangeAt(ast.enum_neighbor_value_tokens, value_index + 1, end);
                    if (tokens[neighbor_range.start].kind != .string) return error.UnsupportedSqlShape;
                },
            }
        },
        .drop_enum_type => {
            if (end < 3 or !tokens[0].matchesKeyword("drop") or !tokens[1].matchesKeyword("type")) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_exists = consumeGeneratedPlanIfExists(tokens, &name_index, end);
            if (if_exists != ast.if_exists) return error.UnsupportedSqlShape;
            if (object_name.start != name_index) return error.UnsupportedSqlShape;
            const has_cascade = generatedRangeHasKeyword(tokens, .{ .start = object_name.end, .end = end }, "cascade");
            if (has_cascade != ast.cascade) return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn tablespaceCatalogPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    _ = options;
    try validateGeneratedTablespaceDdlAst(tokens, ast);
    var plan: DdlPlan = .{ .tablespace_catalog = switch (ast.kind) {
        .create_tablespace => .{ .create = try generatedCreateTablespacePlanAlloc(alloc, tokens, ast) },
        .alter_tablespace => .{ .rename = try generatedRenameTablespacePlanAlloc(alloc, tokens, ast) },
        .drop_tablespace => .{ .drop = try generatedDropTablespacePlanAlloc(alloc, tokens, ast) },
        else => return error.UnsupportedSqlShape,
    } };
    errdefer plan.deinit(alloc);
    switch (ast.kind) {
        .create_tablespace => switch (plan) {
            .tablespace_catalog => |catalog| switch (catalog) {
                .create => |create| try validateGeneratedCreateTablespacePlan(alloc, tokens, ast, create),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .alter_tablespace => switch (plan) {
            .tablespace_catalog => |catalog| switch (catalog) {
                .rename => |rename| try validateGeneratedRenameTablespacePlan(alloc, tokens, ast, rename),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .drop_tablespace => switch (plan) {
            .tablespace_catalog => |catalog| switch (catalog) {
                .drop => |drop| try validateGeneratedDropTablespacePlan(alloc, tokens, ast, drop),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn generatedCreateTablespacePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !CreateTablespacePlan {
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    const name_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    if (operation.start != name_range.end or operation.start + 2 != operation.end or !tokens[operation.start].matchesKeyword("location")) {
        return error.UnsupportedSqlShape;
    }
    const tablespace_name = try generatedIdentifierAlloc(alloc, tokens, name_range);
    errdefer alloc.free(tablespace_name);
    const location_json = try generatedSqlUntypedValueJsonAlloc(alloc, tokens, ast.tablespace_location_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(location_json);
    return .{
        .tablespace_name = tablespace_name,
        .location_json = location_json,
        .placement_policy_json = try alloc.dupe(u8, "{}"),
    };
}

fn generatedRenameTablespacePlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
