) !void {
    if (option_items.count != 1 or option_items.items.len != 1) return error.UnsupportedSqlShape;
    const item = option_items.items[0];
    if (item.start + 3 != item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[item.start].matchesKeyword("lsn") or tokens[item.start + 1].kind != .eq) return error.UnsupportedSqlShape;
    var value_pos = item.start + 2;
    const generated_lsn_json = try value_mod.parseSqlUntypedValueJsonAlloc(alloc, tokens, &value_pos);
    defer alloc.free(generated_lsn_json);
    if (value_pos != item.end or !std.mem.eql(u8, generated_lsn_json, expected_lsn_json)) return error.UnsupportedSqlShape;
}

fn validateGeneratedAlterSubscriptionPlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    alter: AlterSubscriptionPlan,
) !void {
    try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.object_name_tokens, 2, alter.subscription_name);
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (alter.enabled) |expected_enabled| {
        if (operation.start + 1 != operation.end) return error.UnsupportedSqlShape;
        const generated_enabled = ast.subscription_enabled orelse return error.UnsupportedSqlShape;
        if (generated_enabled != expected_enabled) return error.UnsupportedSqlShape;
        if (expected_enabled) {
            if (!tokens[operation.start].matchesKeyword("enable")) return error.UnsupportedSqlShape;
        } else if (!tokens[operation.start].matchesKeyword("disable")) return error.UnsupportedSqlShape;
        if (ast.subscription_option_items.count != 0) return error.UnsupportedSqlShape;
        if (ast.privilege_principal_tokens != null) return error.UnsupportedSqlShape;
        return;
    }
    if (ast.subscription_enabled != null) return error.UnsupportedSqlShape;
    if (alter.connection_json) |expected_connection_json| {
        if (operation.start + 2 != operation.end or !tokens[operation.start].matchesKeyword("connection")) return error.UnsupportedSqlShape;
        const connection_value = ast.subscription_connection_value_tokens orelse return error.UnsupportedSqlShape;
        if (connection_value.start != operation.start + 1 or connection_value.end != operation.end) return error.UnsupportedSqlShape;
        var value_pos = connection_value.start;
        const generated_connection_json = try value_mod.parseSqlUntypedValueJsonAlloc(alloc, tokens, &value_pos);
        defer alloc.free(generated_connection_json);
        if (value_pos != connection_value.end or !std.mem.eql(u8, generated_connection_json, expected_connection_json)) return error.UnsupportedSqlShape;
        if (ast.subscription_publication_items.count != 0 or ast.subscription_option_items.count != 0) return error.UnsupportedSqlShape;
        if (ast.privilege_principal_tokens != null) return error.UnsupportedSqlShape;
        return;
    }
    if (ast.subscription_connection_value_tokens != null) return error.UnsupportedSqlShape;
    if (alter.rename_to) |expected_rename_to| {
        if (operation.start + 3 != operation.end or !tokens[operation.start].matchesKeywordTag(.rename) or !tokens[operation.start + 1].matchesKeywordTag(.to)) return error.UnsupportedSqlShape;
        try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.rename_target_tokens, operation.start + 2, expected_rename_to);
        if (ast.subscription_publication_items.count != 0 or ast.subscription_option_items.count != 0) return error.UnsupportedSqlShape;
        if (ast.privilege_principal_tokens != null) return error.UnsupportedSqlShape;
        return;
    }
    if (ast.rename_target_tokens != null) return error.UnsupportedSqlShape;
    if (alter.owner_to) |expected_owner_to| {
        if (operation.start + 3 != operation.end or !tokens[operation.start].matchesKeywordTag(.owner) or !tokens[operation.start + 1].matchesKeywordTag(.to)) return error.UnsupportedSqlShape;
        try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.privilege_principal_tokens, operation.start + 2, expected_owner_to);
        if (ast.subscription_publication_items.count != 0 or ast.subscription_option_items.count != 0) return error.UnsupportedSqlShape;
        return;
    }
    if (ast.privilege_principal_tokens != null) return error.UnsupportedSqlShape;
    if (alter.skip_lsn_json) |expected_lsn_json| {
        if (operation.start + 6 != operation.end or !tokens[operation.start].matchesKeywordTag(.skip)) return error.UnsupportedSqlShape;
        try validateGeneratedSubscriptionSkipLsn(alloc, tokens, &ast.subscription_option_items, expected_lsn_json);
        if (ast.subscription_publication_items.count != 0) return error.UnsupportedSqlShape;
        return;
    }
    if (alter.refresh_publication) {
        if (operation.start + 2 > operation.end or !tokens[operation.start].matchesKeywordTag(.refresh) or !tokens[operation.start + 1].matchesKeywordTag(.publication)) return error.UnsupportedSqlShape;
        try validateGeneratedSubscriptionOptions(alloc, tokens, &ast.subscription_option_items, alter.copy_data, null, null, null, null, null, null, null, null, null, null, null, null, null);
        if (ast.subscription_publication_items.count != 0) return error.UnsupportedSqlShape;
        return;
    }
    if (alter.publication_names.len > 0) {
        const action = alter.publication_action orelse return error.UnsupportedSqlShape;
        const action_matches = switch (action) {
            .set => tokens[operation.start].matchesKeyword("set"),
            .add => tokens[operation.start].matchesKeyword("add"),
            .drop => tokens[operation.start].matchesKeyword("drop"),
        };
        if (!action_matches or operation.start + 3 > operation.end or !tokens[operation.start + 1].matchesKeyword("publication")) return error.UnsupportedSqlShape;
        const body_end = generatedSubscriptionPlanBodyEnd(tokens, operation);
        try validateGeneratedIdentifierListMatchesNames(alloc, tokens, .{ .start = operation.start + 2, .end = body_end }, &ast.subscription_publication_items, alter.publication_names, false);
        try validateGeneratedSubscriptionOptions(alloc, tokens, &ast.subscription_option_items, alter.copy_data, alter.connect, alter.binary, alter.create_slot, alter.enabled_option, alter.two_phase, alter.disable_on_error, alter.synchronous_commit_json, alter.streaming_json, alter.password_required, alter.run_as_owner, alter.failover, alter.origin_json, alter.slot_name_json);
        if (ast.privilege_principal_tokens != null) return error.UnsupportedSqlShape;
        return;
    }
    if (operation.start + 1 >= operation.end or !tokens[operation.start].matchesKeyword("set")) return error.UnsupportedSqlShape;
    if (ast.subscription_publication_items.count != 0) return error.UnsupportedSqlShape;
    if (operation.start + 3 > operation.end) return error.UnsupportedSqlShape;
    try validateGeneratedSubscriptionOptions(alloc, tokens, &ast.subscription_option_items, alter.copy_data, alter.connect, alter.binary, alter.create_slot, alter.enabled_option, alter.two_phase, alter.disable_on_error, alter.synchronous_commit_json, alter.streaming_json, alter.password_required, alter.run_as_owner, alter.failover, alter.origin_json, alter.slot_name_json);
    if (ast.privilege_principal_tokens != null) return error.UnsupportedSqlShape;
}

fn validateGeneratedDropSubscriptionPlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    drop: DropSubscriptionPlan,
) !void {
    if (drop.if_exists != ast.if_exists) return error.UnsupportedSqlShape;
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    var name_index: usize = 2;
    _ = consumeGeneratedPlanIfExists(tokens, &name_index, end);
    try validateGeneratedIdentifierRangeMatches(alloc, tokens, ast.object_name_tokens, name_index, drop.subscription_name);
}

fn validateGeneratedIdentifierListMatchesNames(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    expected_range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
    names: []const []const u8,
    normalize_sql_object_names: bool,
) !void {
    try validateGeneratedPlainCommaList(tokens, expected_range, items);
    if (items.count != names.len) return error.UnsupportedSqlShape;
    for (items.items, names) |item, expected_name| {
        const generated_name = if (normalize_sql_object_names)
            try generatedSqlObjectIdentifierAlloc(alloc, tokens, item)
        else
            try generatedIdentifierAlloc(alloc, tokens, item);
        defer alloc.free(@constCast(generated_name));
        if (!std.ascii.eqlIgnoreCase(generated_name, expected_name)) return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedPlainCommaList(
    tokens: []const grammar.Token,
    expected_range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (expected_range.start >= expected_range.end or expected_range.end > tokens.len) return error.UnsupportedSqlShape;
    if (items.count == 0 or
        items.items.len != items.count or
        items.expression_items.len != 0 or
        items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or
        items.direction_items.len != 0 or
        items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or
        items.nulls_order_items.len != 0 or
        items.nulls_orders.len != 0 or
        items.expressions.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
    if (!std.meta.eql(items.first_tokens orelse return error.UnsupportedSqlShape, items.items[0])) return error.UnsupportedSqlShape;
    if (!std.meta.eql(items.last_tokens orelse return error.UnsupportedSqlShape, items.items[items.items.len - 1])) return error.UnsupportedSqlShape;

    var expected_start = expected_range.start;
    for (items.items, 0..) |item, item_index| {
        if (item.start != expected_start or item.start >= item.end or item.end > expected_range.end) return error.UnsupportedSqlShape;
        if (item_index + 1 < items.items.len) {
            if (item.end >= expected_range.end or tokens[item.end].kind != .comma) return error.UnsupportedSqlShape;
            expected_start = item.end + 1;
        } else {
            expected_start = item.end;
        }
    }
    if (expected_start != expected_range.end) return error.UnsupportedSqlShape;
}

fn rowSecurityPolicyCatalogPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    try validateGeneratedRowSecurityPolicyDdlAst(tokens, ast);
    var plan: DdlPlan = .{ .row_security_catalog = switch (ast.kind) {
        .create_policy => .{ .create_policy = try createRowSecurityPolicyPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options.row_security_policy_options) },
        .alter_policy => .{ .alter_policy = try alterRowSecurityPolicyPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast, options.row_security_policy_options) },
        .drop_policy => .{ .drop_policy = try dropRowSecurityPolicyPlanFromGeneratedDdlAstAlloc(alloc, tokens, ast) },
        else => return error.UnsupportedSqlShape,
    } };
    errdefer plan.deinit(alloc);
    switch (ast.kind) {
        .create_policy => switch (plan) {
            .row_security_catalog => |catalog| switch (catalog) {
                .create_policy => |create| try validateGeneratedCreateRowSecurityPolicyPlan(alloc, tokens, ast, create),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .alter_policy => switch (plan) {
            .row_security_catalog => |catalog| switch (catalog) {
                .alter_policy => |alter| try validateGeneratedAlterRowSecurityPolicyPlan(alloc, tokens, ast, alter),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        .drop_policy => switch (plan) {
            .row_security_catalog => |catalog| switch (catalog) {
                .drop_policy => |drop| try validateGeneratedDropRowSecurityPolicyPlan(alloc, tokens, ast, drop),
                else => return error.UnsupportedSqlShape,
            },
            else => return error.UnsupportedSqlShape,
        },
        else => return error.UnsupportedSqlShape,
    }
    return plan;
}

fn createRowSecurityPolicyPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: RowSecurityPolicyOptions,
) !CreateRowSecurityPolicyPlan {
    const policy_name = try generatedIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(policy_name);
    const table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.index_table_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(table_name);
    const role_targets = try generatedRowSecurityPolicyRoleTargetsAlloc(alloc, tokens, ast);
    errdefer freeStringSlice(alloc, role_targets);
    var predicate = try generatedRowSecurityPolicyPredicateAlloc(alloc, tokens, ast.policy_using_predicate_tokens orelse return error.UnsupportedSqlShape, options);
    errdefer predicate.deinit(alloc);
    var check_predicate: ?RowSecurityPolicyPredicate = if (ast.policy_check_predicate_tokens) |range|
        try generatedRowSecurityPolicyPredicateAlloc(alloc, tokens, range, options)
    else
        null;
    errdefer if (check_predicate) |*value| value.deinit(alloc);
    return .{
        .policy_name = policy_name,
        .table_name = table_name,
        .mode = try generatedRowSecurityPolicyMode(tokens, ast.policy_mode_tokens),
        .command = try generatedRowSecurityPolicyCommand(tokens, ast.policy_command_tokens),
        .role_targets = role_targets,
        .predicate = predicate,
        .check_predicate = check_predicate,
    };
}

fn alterRowSecurityPolicyPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    options: RowSecurityPolicyOptions,
) !AlterRowSecurityPolicyPlan {
    if (ast.policy_mode_tokens != null or ast.policy_command_tokens != null) return error.UnsupportedSqlShape;
    const policy_name = try generatedIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(policy_name);
    const table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.index_table_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(table_name);
    const role_targets = try generatedRowSecurityPolicyRoleTargetsAlloc(alloc, tokens, ast);
    errdefer freeStringSlice(alloc, role_targets);
    var predicate: ?RowSecurityPolicyPredicate = if (ast.policy_using_predicate_tokens) |range|
        try generatedRowSecurityPolicyPredicateAlloc(alloc, tokens, range, options)
    else
        null;
    errdefer if (predicate) |*value| value.deinit(alloc);
    var check_predicate: ?RowSecurityPolicyPredicate = if (ast.policy_check_predicate_tokens) |range|
        try generatedRowSecurityPolicyPredicateAlloc(alloc, tokens, range, options)
    else
        null;
    errdefer if (check_predicate) |*value| value.deinit(alloc);
    if (!ast.policy_role_targets_present and predicate == null and check_predicate == null) return error.UnsupportedSqlShape;
    return .{
        .policy_name = policy_name,
        .table_name = table_name,
        .role_targets_present = ast.policy_role_targets_present,
        .role_targets = role_targets,
        .predicate = predicate,
        .check_predicate = check_predicate,
    };
}

fn generatedRowSecurityPolicyMode(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
) !?RowSecurityPolicyMode {
    const range = maybe_range orelse return null;
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].matchesKeyword("permissive")) return .permissive;
    if (tokens[range.start].matchesKeyword("restrictive")) return .restrictive;
    return error.UnsupportedSqlShape;
}

fn generatedRowSecurityPolicyCommand(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
) !?RowSecurityPolicyCommand {
    const range = maybe_range orelse return null;
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start].matchesKeyword("all")) return .all;
    if (tokens[range.start].matchesKeyword("select")) return .select;
    if (tokens[range.start].matchesKeyword("insert")) return .insert;
    if (tokens[range.start].matchesKeyword("update")) return .update;
    if (tokens[range.start].matchesKeyword("delete")) return .delete;
    return error.UnsupportedSqlShape;
}

fn generatedRowSecurityPolicyRoleTargetsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) ![]const []const u8 {
    if (!ast.policy_role_targets_present) {
        try validateGeneratedEmptyListAst(&ast.policy_role_target_items);
        if (ast.policy_role_targets_public) return error.UnsupportedSqlShape;
        return &.{};
    }
    if (ast.policy_role_targets_public) {
        try validateGeneratedEmptyListAst(&ast.policy_role_target_items);
        return &.{};
    }
    return try generatedIdentifierStringListAlloc(alloc, tokens, &ast.policy_role_target_items);
}

fn generatedRowSecurityPolicyPredicateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
    options: RowSecurityPolicyOptions,
) !RowSecurityPolicyPredicate {
    if (range.start == 0 or range.start >= range.end or range.end >= tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start - 1].kind != .lparen or tokens[range.end].kind != .rparen) return error.UnsupportedSqlShape;
    var pos = range.start - 1;
    var predicate = grammar.parseRowSecurityPolicyPredicateAlloc(alloc, parser.Cursor.init(tokens, &pos), tokens, &pos) catch |err| switch (err) {
        error.UnsupportedSqlShape, error.InvalidSqlCatalog => blk: {
            pos = range.start;
            var expression_predicate = try parseRowSecurityPolicyExpressionBindingPredicateAlloc(alloc, tokens, &pos, options);
            errdefer expression_predicate.deinit(alloc);
            if (pos != range.end) return error.UnsupportedSqlShape;
            break :blk expression_predicate;
        },
        else => return err,
    };
    if (pos != range.end + 1) {
        predicate.deinit(alloc);
        pos = range.start;
        var expression_predicate = try parseRowSecurityPolicyExpressionBindingPredicateAlloc(alloc, tokens, &pos, options);
        errdefer expression_predicate.deinit(alloc);
        if (pos != range.end) return error.UnsupportedSqlShape;
        return expression_predicate;
    }
    return predicate;
}

fn dropRowSecurityPolicyPlanFromGeneratedDdlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
) !DropRowSecurityPolicyPlan {
    return .{
        .policy_name = try generatedIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape),
        .table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.index_table_tokens orelse return error.UnsupportedSqlShape),
        .if_exists = ast.if_exists,
    };
}

fn validateGeneratedRowSecurityPolicyDdlAst(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) !void {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return error.UnsupportedSqlShape;
    const policy_name = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    const table_name = ast.index_table_tokens orelse return error.UnsupportedSqlShape;
    if (policy_name.start >= policy_name.end or policy_name.end > end) return error.UnsupportedSqlShape;
    if (table_name.start >= table_name.end or table_name.end > end) return error.UnsupportedSqlShape;
    switch (ast.kind) {
        .create_policy => {
            if (end < 5 or !tokens[0].matchesKeyword("create") or !tokens[1].matchesKeyword("policy")) return error.UnsupportedSqlShape;
            try validateGeneratedRowSecurityPolicyDdlNameAndTable(tokens, end, policy_name, table_name, 2);
            try validateGeneratedRowSecurityPolicyDdlTail(tokens, ast, end, table_name, true);
        },
        .alter_policy => {
            if (end < 6 or !tokens[0].matchesKeyword("alter") or !tokens[1].matchesKeyword("policy")) return error.UnsupportedSqlShape;
            try validateGeneratedRowSecurityPolicyDdlNameAndTable(tokens, end, policy_name, table_name, 2);
            const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
            if (operation.start != table_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
            if (!tokens[operation.start].matchesKeyword("rename") and
                !tokens[operation.start].matchesKeyword("to") and
                !tokens[operation.start].matchesKeyword("using") and
                !tokens[operation.start].matchesKeyword("with"))
            {
                return error.UnsupportedSqlShape;
            }
        },
        .drop_policy => {
            if (end < 5 or !tokens[0].matchesKeyword("drop") or !tokens[1].matchesKeyword("policy")) return error.UnsupportedSqlShape;
            var name_index: usize = 2;
            const if_exists = consumeGeneratedPlanIfExists(tokens, &name_index, end);
            if (if_exists != ast.if_exists) return error.UnsupportedSqlShape;
            try validateGeneratedRowSecurityPolicyDdlNameAndTable(tokens, end, policy_name, table_name, name_index);
            if (ast.alter_table_operation_tokens != null) return error.UnsupportedSqlShape;
            const has_cascade = generatedRangeHasKeyword(tokens, .{ .start = table_name.end, .end = end }, "cascade");
            if (has_cascade != ast.cascade) return error.UnsupportedSqlShape;
            if (table_name.end < end and
                !tokens[table_name.end].matchesKeyword("cascade") and
                !tokens[table_name.end].matchesKeyword("restrict"))
            {
                return error.UnsupportedSqlShape;
            }
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn validateGeneratedRowSecurityPolicyDdlNameAndTable(
    tokens: []const grammar.Token,
    end: usize,
    policy_name: generated_parser.GeneratedSqlTokenRange,
    table_name: generated_parser.GeneratedSqlTokenRange,
    name_index: usize,
) !void {
    if (policy_name.start != name_index) return error.UnsupportedSqlShape;
    if (policy_name.end >= end or !tokens[policy_name.end].matchesKeyword("on")) return error.UnsupportedSqlShape;
    if (table_name.start != policy_name.end + 1) return error.UnsupportedSqlShape;
}

fn validateGeneratedRowSecurityPolicyDdlTail(
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    end: usize,
    table_name: generated_parser.GeneratedSqlTokenRange,
    allow_empty_tail: bool,
) !void {
    if (table_name.end < end) {
        const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
        if (operation.start != table_name.end or operation.end != end or operation.start >= end) return error.UnsupportedSqlShape;
        if (!tokens[operation.start].matchesKeyword("as") and
            !tokens[operation.start].matchesKeyword("for") and
            !tokens[operation.start].matchesKeyword("to") and
            !tokens[operation.start].matchesKeyword("using") and
            !tokens[operation.start].matchesKeyword("with"))
        {
            return error.UnsupportedSqlShape;
        }
    } else if (!allow_empty_tail or ast.alter_table_operation_tokens != null) {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedCreateRowSecurityPolicyPlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    create: CreateRowSecurityPolicyPlan,
) !void {
    try validateGeneratedRowSecurityPolicyPlanNames(alloc, tokens, ast, create.policy_name, create.table_name);
    try validateGeneratedRowSecurityPolicyMode(tokens, ast.policy_mode_tokens, create.mode);
    try validateGeneratedRowSecurityPolicyCommand(tokens, ast.policy_command_tokens, create.command);
    try validateGeneratedRowSecurityPolicyRoleTargets(alloc, tokens, ast, create.role_targets, true);
    try validateGeneratedRowSecurityPolicyPredicateRange(tokens, ast.policy_using_predicate_tokens, true, "using");
    try validateGeneratedRowSecurityPolicyPredicateRange(tokens, ast.policy_check_predicate_tokens, create.check_predicate != null, "with check");
}

fn validateGeneratedAlterRowSecurityPolicyPlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    alter: AlterRowSecurityPolicyPlan,
) !void {
    try validateGeneratedRowSecurityPolicyPlanNames(alloc, tokens, ast, alter.policy_name, alter.table_name);
    if (ast.policy_mode_tokens != null) return error.UnsupportedSqlShape;
    if (ast.policy_role_targets_present != alter.role_targets_present) return error.UnsupportedSqlShape;
    if (alter.role_targets_present) {
        try validateGeneratedRowSecurityPolicyRoleTargets(alloc, tokens, ast, alter.role_targets, true);
    } else if (ast.policy_role_targets_public or ast.policy_role_target_items.count != 0) {
        return error.UnsupportedSqlShape;
    }
    if (ast.policy_command_tokens != null) return error.UnsupportedSqlShape;
    try validateGeneratedRowSecurityPolicyPredicateRange(tokens, ast.policy_using_predicate_tokens, alter.predicate != null, "using");
    try validateGeneratedRowSecurityPolicyPredicateRange(tokens, ast.policy_check_predicate_tokens, alter.check_predicate != null, "with check");
}

fn validateGeneratedDropRowSecurityPolicyPlan(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    drop: DropRowSecurityPolicyPlan,
) !void {
    try validateGeneratedRowSecurityPolicyPlanNames(alloc, tokens, ast, drop.policy_name, drop.table_name);
    if (ast.policy_mode_tokens != null or
        ast.policy_command_tokens != null or
        ast.policy_using_predicate_tokens != null or
        ast.policy_check_predicate_tokens != null or
        ast.policy_role_targets_present or
        ast.policy_role_targets_public or
        ast.policy_role_target_items.count != 0)
    {
        return error.UnsupportedSqlShape;
    }
}

fn validateGeneratedRowSecurityPolicyMode(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?RowSecurityPolicyMode,
) !void {
    const mode = expected orelse {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        if (findTopLevelKeywordText(tokens, 0, tokens.len, "as") != null) return error.UnsupportedSqlShape;
        return;
    };
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start == 0 or range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[range.start - 1].matchesKeyword("as")) return error.UnsupportedSqlShape;
    const keyword = switch (mode) {
        .permissive => "permissive",
        .restrictive => "restrictive",
    };
    if (!tokens[range.start].matchesKeyword(keyword)) return error.UnsupportedSqlShape;
}

fn validateGeneratedRowSecurityPolicyCommand(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: ?RowSecurityPolicyCommand,
) !void {
    const command = expected orelse {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        if (findTopLevelKeyword(tokens, 0, tokens.len, .@"for") != null) return error.UnsupportedSqlShape;
        return;
    };
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start == 0 or range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[range.start - 1].matchesKeyword("for")) return error.UnsupportedSqlShape;
    const keyword = switch (command) {
        .all => "all",
        .select => "select",
        .insert => "insert",
        .update => "update",
        .delete => "delete",
    };
    if (!tokens[range.start].matchesKeyword(keyword)) return error.UnsupportedSqlShape;
}

fn validateGeneratedRowSecurityPolicyPredicateRange(
    tokens: []const grammar.Token,
    maybe_range: ?generated_parser.GeneratedSqlTokenRange,
    expected: bool,
    clause: []const u8,
) !void {
    if (!expected) {
        if (maybe_range != null) return error.UnsupportedSqlShape;
        if (std.mem.eql(u8, clause, "using")) {
            if (findTopLevelKeywordText(tokens, 0, tokens.len, "using") != null) return error.UnsupportedSqlShape;
        } else if (std.mem.eql(u8, clause, "with check")) {
            var search_start: usize = 0;
            while (findTopLevelKeywordText(tokens, search_start, tokens.len, "with")) |with_index| {
                if (with_index + 1 < tokens.len and tokens[with_index + 1].matchesKeyword("check")) return error.UnsupportedSqlShape;
                search_start = with_index + 1;
            }
        }
        return;
    }
    const range = maybe_range orelse return error.UnsupportedSqlShape;
    if (range.start == 0 or range.start >= range.end or range.end >= tokens.len) return error.UnsupportedSqlShape;
    if (tokens[range.start - 1].kind != .lparen or tokens[range.end].kind != .rparen) return error.UnsupportedSqlShape;
    if (std.mem.eql(u8, clause, "using")) {
        if (range.start < 2 or !tokens[range.start - 2].matchesKeyword("using")) return error.UnsupportedSqlShape;
        return;
    }
    if (std.mem.eql(u8, clause, "with check")) {
        if (range.start < 3 or !tokens[range.start - 3].matchesKeyword("with") or !tokens[range.start - 2].matchesKeyword("check")) return error.UnsupportedSqlShape;
        return;
    }
    return error.UnsupportedSqlShape;
}

fn validateGeneratedRowSecurityPolicyPlanNames(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    expected_policy_name: []const u8,
    expected_table_name: []const u8,
) !void {
    const policy_range = ast.object_name_tokens orelse return error.UnsupportedSqlShape;
    const table_range = ast.index_table_tokens orelse return error.UnsupportedSqlShape;
    const generated_policy_name = try generatedIdentifierAlloc(alloc, tokens, policy_range);
    defer alloc.free(@constCast(generated_policy_name));
    if (!std.ascii.eqlIgnoreCase(generated_policy_name, expected_policy_name)) return error.UnsupportedSqlShape;
    const generated_table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, table_range);
    defer alloc.free(@constCast(generated_table_name));
    if (!std.ascii.eqlIgnoreCase(generated_table_name, expected_table_name)) return error.UnsupportedSqlShape;
}

fn validateGeneratedRowSecurityPolicyRoleTargets(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    role_targets: []const []const u8,
    allow_absent: bool,
) !void {
    if (!ast.policy_role_targets_present) {
        if (ast.policy_role_targets_public or ast.policy_role_target_items.count != 0) return error.UnsupportedSqlShape;
        if (!allow_absent or role_targets.len != 0) return error.UnsupportedSqlShape;
        return;
    }
    if (ast.policy_role_targets_public) {
        if (role_targets.len != 0 or ast.policy_role_target_items.count != 0) return error.UnsupportedSqlShape;
        return;
    }
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (ast.policy_role_target_items.count == 0) return error.UnsupportedSqlShape;
    const first_role = ast.policy_role_target_items.items[0];
    const last_role = ast.policy_role_target_items.items[ast.policy_role_target_items.count - 1];
    if (first_role.start <= operation.start or last_role.end > operation.end) return error.UnsupportedSqlShape;
    if (!tokens[first_role.start - 1].matchesKeyword("to")) return error.UnsupportedSqlShape;
    try validateGeneratedIdentifierListMatchesNames(alloc, tokens, .{ .start = first_role.start, .end = last_role.end }, &ast.policy_role_target_items, role_targets, false);
}

fn findKeyword(tokens: []const grammar.Token, start: usize, end: usize, keyword: token_mod.TokenKeyword) ?usize {
    var i = start;
    while (i < end and i < tokens.len) : (i += 1) {
        if (tokens[i].matchesKeywordTag(keyword)) return i;
    }
    return null;
}

fn findTopLevelKeyword(tokens: []const grammar.Token, start: usize, end: usize, keyword: token_mod.TokenKeyword) ?usize {
    var depth: usize = 0;
    var i = start;
    while (i < end and i < tokens.len) : (i += 1) {
        switch (tokens[i].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0 and tokens[i].matchesKeywordTag(keyword)) return i,
        }
    }
    return null;
}

fn findTopLevelKeywordText(tokens: []const grammar.Token, start: usize, end: usize, keyword: []const u8) ?usize {
    var depth: usize = 0;
    var i = start;
    while (i < end and i < tokens.len) : (i += 1) {
        switch (tokens[i].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0 and tokens[i].matchesKeyword(keyword)) return i,
        }
    }
    return null;
}

fn findMatchingParen(tokens: []const grammar.Token, open_index: usize, end: usize) ?usize {
    if (open_index >= end or open_index >= tokens.len or tokens[open_index].kind != .lparen) return null;
    var depth: usize = 1;
    var index = open_index + 1;
    while (index < end and index < tokens.len) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => depth += 1,
            .rparen => {
                depth -= 1;
                if (depth == 0) return index;
            },
            else => {},
        }
    }
    return null;
}

fn generatedCreateIndexUsesRuntimeBoundary(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) bool {
    return generatedStatementEnd(tokens, ast.statement_span) != null;
}

fn generatedCreateIndexWhereUsesRuntimeBoundary(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) bool {
    if (range.end > tokens.len or range.start > range.end) return false;
    return range.start < range.end;
}

fn generatedAlterTableUsesRuntimeBoundary(tokens: []const grammar.Token, ast: generated_parser.GeneratedSqlDdlAst) bool {
    const end = generatedStatementEnd(tokens, ast.statement_span) orelse return false;
    const operation_range = ast.alter_table_operation_tokens orelse return false;
    if (!generatedRangeWithinStatement(operation_range, end) or operation_range.start >= operation_range.end) return false;
    validateGeneratedAlterTableOperationItems(tokens, operation_range, &ast.alter_table_operation_items) catch return false;
    validateGeneratedAlterTableOperationConstraintPrefixItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationPrimaryUniqueConstraintPayloadItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationForeignKeyConstraintPayloadItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationCheckConstraintPayloadItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationPeriodPayloadItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationColumnDefinitionItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationInlineConstraintPrefixItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationDefaultValueItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationGeneratedExpressionItems(tokens, &ast) catch return false;
    validateGeneratedAlterTableOperationRewriteExpressionItems(tokens, &ast) catch return false;
    return true;
}

fn validateGeneratedAlterTableOperationItems(
    tokens: []const grammar.Token,
    operation_range: generated_parser.GeneratedSqlTokenRange,
    items: *const generated_parser.GeneratedSqlListAst,
) !void {
    if (operation_range.end > tokens.len or operation_range.start >= operation_range.end) return error.UnsupportedSqlShape;
    if (items.count == 0 or items.items.len != items.count) return error.UnsupportedSqlShape;
    if (items.alias_items.len != 0 or
        items.alias_name_items.len != 0 or
        items.direction_items.len != 0 or
        items.directions.len != 0 or
        items.order_using_operator_items.len != 0 or
        items.nulls_order_items.len != 0 or
        items.nulls_orders.len != 0)
    {
        return error.UnsupportedSqlShape;
    }

    if (!std.meta.eql(items.first_tokens orelse return error.UnsupportedSqlShape, items.items[0])) return error.UnsupportedSqlShape;
    if (!std.meta.eql(items.last_tokens orelse return error.UnsupportedSqlShape, items.items[items.items.len - 1])) return error.UnsupportedSqlShape;

    var expected_start = operation_range.start;
    for (items.items, 0..) |item, item_index| {
        if (item.start != expected_start or item.start >= item.end or item.end > operation_range.end) return error.UnsupportedSqlShape;
        if (!generatedAlterTableOperationSegmentUsesRuntimeBoundary(tokens, item.start, item.end)) return error.UnsupportedSqlShape;
        if (item_index + 1 < items.items.len) {
            if (item.end >= operation_range.end or tokens[item.end].kind != .comma) return error.UnsupportedSqlShape;
            expected_start = item.end + 1;
        } else {
            expected_start = item.end;
        }
    }
    if (expected_start != operation_range.end) return error.UnsupportedSqlShape;
}

fn validateGeneratedAlterTableOperationConstraintPrefixItems(
    tokens: []const grammar.Token,
    ast: *const generated_parser.GeneratedSqlDdlAst,
) !void {
    const name_items = ast.alter_table_operation_constraint_name_items;
    const kind_items = ast.alter_table_operation_constraint_kind_items;
    if (name_items.len == 0 and kind_items.len == 0) {
        for (ast.alter_table_operation_items.items) |item| {
            if (generatedDdlItemLooksLikeTableConstraint(tokens, item)) return error.UnsupportedSqlShape;
        }
        return;
    }
    if (name_items.len != kind_items.len or
        name_items.len != ast.alter_table_operation_items.items.len or
        ast.alter_table_operation_items.items.len != ast.alter_table_operation_items.count)
    {
        return error.UnsupportedSqlShape;
    }
    for (ast.alter_table_operation_items.items, 0..) |item, index| {
        const name_range = name_items[index];
        const kind_range = kind_items[index];
        if (generatedDdlItemLooksLikeTableConstraint(tokens, item)) {
            const kind = kind_range orelse return error.UnsupportedSqlShape;
            if (kind.start < item.start or kind.end > item.end or kind.start >= kind.end or kind.end > tokens.len) return error.UnsupportedSqlShape;
            if (!generatedDdlConstraintKindRangeIsValid(tokens, kind)) return error.UnsupportedSqlShape;
            if (name_range) |name| {
                if (name.start < item.start or name.end > kind.start or name.end != name.start + 1 or name.end > tokens.len) return error.UnsupportedSqlShape;
                if (tokens[name.start].kind != .identifier) return error.UnsupportedSqlShape;
                if (name.start == item.start or !tokens[name.start - 1].matchesKeywordTag(.constraint)) return error.UnsupportedSqlShape;
            }
        } else if (name_range != null or kind_range != null) {
            return error.UnsupportedSqlShape;
        }
    }
}

fn generatedDdlItemLooksLikeTableConstraint(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
) bool {
    if (item.end > tokens.len or item.start >= item.end) return false;
    var cursor = item.start;
    if (tokens[cursor].matchesKeywordTag(.add)) {
        cursor += 1;
        if (cursor >= item.end or tokens[cursor].matchesKeywordTag(.column)) return false;
        if (tokens[cursor].matchesKeyword("period")) return true;
    }
    if (tokens[cursor].matchesKeywordTag(.constraint)) {
        cursor += 2;
        if (cursor > item.end) return false;
    }
    if (cursor >= item.end) return false;
    return tokens[cursor].matchesKeyword("period") or
        tokens[cursor].matchesKeyword("primary") or
        tokens[cursor].matchesKeyword("unique") or
        tokens[cursor].matchesKeyword("foreign") or
        tokens[cursor].matchesKeyword("check");
}

fn generatedDdlConstraintKindRangeIsValid(
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) bool {
    if (range.end > tokens.len or range.start >= range.end) return false;
    if (range.end == range.start + 1) {
        return tokens[range.start].matchesKeyword("period") or
            tokens[range.start].matchesKeyword("unique") or
            tokens[range.start].matchesKeyword("check");
    }
    if (range.end == range.start + 2) {
        return (tokens[range.start].matchesKeyword("primary") or tokens[range.start].matchesKeyword("foreign")) and
            tokens[range.start + 1].matchesKeyword("key");
    }
    return false;
}

fn validateGeneratedAlterTableOperationGeneratedExpressionItems(
    tokens: []const grammar.Token,
    ast: *const generated_parser.GeneratedSqlDdlAst,
) !void {
    const clause_items = ast.alter_table_operation_column_generated_clause_items;
    const expression_items = ast.alter_table_operation_generated_expression_items;
    if (clause_items.len == 0 and expression_items.len == 0) {
        for (ast.alter_table_operation_items.items) |item| {
            if (generatedDdlColumnDefinitionStoredGeneratedClauseRange(tokens, item) != null) return error.UnsupportedSqlShape;
        }
    } else {
