    return null;
}

fn generatedDdlConstraintIncludeRange(
    tokens: []const grammar.Token,
    start: usize,
    end: usize,
) ?generated_parser.GeneratedSqlTokenRange {
    if (start >= end or !tokens[start].matchesKeyword("include")) return null;
