fn validateGeneratedDdlColumnDefinitionTailCovered(
    tokens: []const grammar.Token,
    item: generated_parser.GeneratedSqlTokenRange,
    start: usize,
    ranges: [5]?generated_parser.GeneratedSqlTokenRange,
