        if (generatedDdlColumnInlineConstraintPrefixAt(tokens, item, cursor)) |prefix| {
            cursor = generatedDdlNextInlineConstraintPrefixStart(tokens, item, prefix.kind.end) orelse item.end;
            continue;
        }
        return error.UnsupportedSqlShape;
    }
