    const first = tokens[start];
    if (first.kind == .lparen) {
        const close_index = findGeneratedMatchingParen(tokens, start, item.end) orelse return null;
        if (close_index <= start + 1) return null;
        return .{ .start = start, .end = close_index + 1 };
