    const range = argument.tokens orelse return null;
    if (range.end != range.start + 1 or range.end > tokens.len or tokens[range.start].kind != .identifier) return null;
    return tokens[range.start].text;
}

fn generatedCreateIndexStructuredGeneratedValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    expression: generated_parser.GeneratedSqlExpressionAst,
) !?runtime_schema.RelationalGeneratedValue {
    const unwrapped = generatedCreateIndexUnwrappedExpression(&expression);
    if (unwrapped.kind != .function_call) return null;
    if (unwrapped.argument_distinct_tokens != null or
        unwrapped.argument_order_tokens != null or
        unwrapped.within_group_tokens != null or
        unwrapped.filter_tokens != null or
        unwrapped.over_tokens != null)
    {
        return null;
    }
    const function_name = generatedDdlSingleTokenText(tokens, unwrapped.function_name_tokens orelse return error.UnsupportedSqlShape);
    const op: runtime_schema.RelationalGeneratedOp = if (std.ascii.eqlIgnoreCase(function_name, "concat"))
        .concat
    else if (std.ascii.eqlIgnoreCase(function_name, "concat_ws"))
        .concat_ws
    else
        return null;
    const arguments = unwrapped.argument_items;
    if (!generatedCreateIndexExpressionArgumentsValid(arguments)) return error.UnsupportedSqlShape;
    const first_field_index: usize = if (op == .concat_ws) 1 else 0;
    if (arguments.count < first_field_index + 2) return null;
    var separator: []const u8 = "";
    if (op == .concat_ws) {
        const separator_range = arguments.expression_items[0];
        if (separator_range.end != separator_range.start + 1 or separator_range.end > tokens.len or tokens[separator_range.start].kind != .string) return null;
        separator = tokens[separator_range.start].text;
    }
    var fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (fields.items) |field| alloc.free(field);
        fields.deinit(alloc);
    }
    var index = first_field_index;
    while (index < arguments.count) : (index += 1) {
        if (op == .concat and index > 0 and index + 1 < arguments.count) {
            const maybe_separator_range = arguments.expression_items[index];
            if (maybe_separator_range.end == maybe_separator_range.start + 1 and maybe_separator_range.end <= tokens.len and tokens[maybe_separator_range.start].kind == .string) {
                if (separator.len != 0 and !std.mem.eql(u8, separator, tokens[maybe_separator_range.start].text)) return null;
                separator = tokens[maybe_separator_range.start].text;
                index += 1;
            }
        }
        const field_text = generatedCreateIndexArgumentField(tokens, arguments.expressions[index]) orelse return null;
        try fields.append(alloc, try alloc.dupe(u8, field_text));
    }
    if (fields.items.len < 2) return null;
    const owned_fields = try fields.toOwnedSlice(alloc);
    var fields_transferred = false;
    errdefer if (!fields_transferred) freeStringSlice(alloc, owned_fields);
    const owned_separator = try alloc.dupe(u8, separator);
    fields_transferred = true;
    return .{
        .op = op,
        .fields = owned_fields,
        .separator = owned_separator,
    };
}

fn generatedDerivedIndexFieldPathAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) ![]const u8 {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    var pos = range.start;
    const field = try parseDerivedIndexFieldPathAlloc(alloc, tokens, &pos);
    errdefer alloc.free(field);
    if (pos != range.end) return error.UnsupportedSqlShape;
    return field;
}

fn generatedDerivedIndexExpectedColumnCount(method: DdlIndexMethod) usize {
    return switch (method) {
        .antfly_full_text, .hnsw, .antfly_aknn => 1,
        .antfly_graph => 2,
        .antfly_graph_metric, .antfly_hybrid, .antfly_algebraic => 0,
        .btree, .gin => unreachable,
    };
}

fn generatedDerivedIndexColumnsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    method: DdlIndexMethod,
    elements_range: generated_parser.GeneratedSqlTokenRange,
    elements: generated_parser.GeneratedSqlListAst,
    opclass: *DdlIndexOpClass,
) ![]const []const u8 {
    const expected_count = generatedDerivedIndexExpectedColumnCount(method);
    if (expected_count == 0) {
        if (elements_range.start != elements_range.end or elements.count != 0 or elements.items.len != 0) return error.UnsupportedSqlShape;
        return &.{};
    }
    if (!generatedIndexListCoversRange(elements, elements_range)) return error.UnsupportedSqlShape;
    if (elements.count != expected_count or elements.expression_items.len != elements.count) return error.UnsupportedSqlShape;
    const columns = try alloc.alloc([]const u8, elements.count);
    var initialized: usize = 0;
    errdefer {
        for (columns[0..initialized]) |column| alloc.free(column);
        alloc.free(columns);
    }
    for (elements.items, 0..) |item, index| {
        if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
        const raw_expression_range = elements.expression_items[index];
        const derived_range = try derivedIndexExpressionRangeWithoutOpClass(tokens, method, raw_expression_range);
        const expression_range = derived_range.expression_range;
        if (expression_range.start < item.start or expression_range.end > item.end or expression_range.end > tokens.len) return error.UnsupportedSqlShape;
        if (derived_range.opclass != .default) opclass.* = derived_range.opclass;
        columns[index] = try generatedDerivedIndexFieldPathAlloc(alloc, tokens, expression_range);
        initialized += 1;
    }
    return columns;
}

fn generatedDerivedCreateIndexPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlDdlAst,
    method: DdlIndexMethod,
) !CreateIndexPlan {
    if (ast.unique or ast.index_include_tokens != null or ast.index_include_items.count != 0 or ast.index_where_tokens != null or ast.index_where_expression.tokens != null) return error.UnsupportedSqlShape;
    const elements_range = ast.index_elements_tokens orelse return error.UnsupportedSqlShape;
    const elements = ast.index_element_items;

    var opclass: DdlIndexOpClass = .default;
    const columns = try generatedDerivedIndexColumnsAlloc(alloc, tokens, method, elements_range, elements, &opclass);
    var columns_transferred = false;
    errdefer if (!columns_transferred) freeStringSlice(alloc, columns);

    const options = try parseGeneratedDerivedIndexOptionsAlloc(alloc, tokens, ast.index_options_tokens);
    defer freeDerivedIndexOptions(alloc, options);
    const derived_index_config_json = try derivedIndexConfigJsonFromOptionsAlloc(alloc, method, opclass, columns, options);
    var config_transferred = false;
    errdefer if (!config_transferred) alloc.free(derived_index_config_json);

    const index_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    var index_name_transferred = false;
    errdefer if (!index_name_transferred) alloc.free(index_name);
    const table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.index_table_tokens orelse return error.UnsupportedSqlShape);
    var table_name_transferred = false;
    errdefer if (!table_name_transferred) alloc.free(table_name);

    index_name_transferred = true;
    table_name_transferred = true;
    columns_transferred = true;
    config_transferred = true;
    return .{
        .index_name = index_name,
        .table_name = table_name,
        .if_not_exists = ast.if_not_exists,
        .unique = false,
        .method = method,
        .opclass = opclass,
        .columns = columns,
        .derived_index_config_json = derived_index_config_json,
    };
}

fn generatedCreateIndexPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlDdlAst,
) !?CreateIndexPlan {
    const method = try generatedCreateIndexMethod(tokens, ast);
    if (ddlIndexMethodIsDerived(method)) return try generatedDerivedCreateIndexPlanAlloc(alloc, tokens, ast, method);
    if (ast.index_options_tokens != null) return null;
    const elements_range = ast.index_elements_tokens orelse return error.UnsupportedSqlShape;
    const elements = ast.index_element_items;
    if (!generatedIndexListCoversRange(elements, elements_range)) return error.UnsupportedSqlShape;
    if (elements.expression_items.len != elements.count or elements.directions.len != elements.count or elements.nulls_orders.len != elements.count) return error.UnsupportedSqlShape;

    var where: []const runtime_schema.UniquePredicate = &.{};
    var where_transferred = false;
    errdefer if (!where_transferred) freeDdlUniquePredicates(alloc, where);
    var where_expressions: []const db_mod.types.RelationalRowsExpressionCondition = &.{};
    var where_expressions_transferred = false;
    errdefer if (!where_expressions_transferred) {
        freeExpressionConditions(alloc, where_expressions);
        if (where_expressions.len > 0) alloc.free(where_expressions);
    };
    if (try generatedCreateIndexWherePredicatesAlloc(alloc, tokens, ast)) |predicates| {
        where = predicates;
    } else if (try generatedCreateIndexWhereExpressionConditionsAlloc(alloc, tokens, ast)) |conditions| {
        where_expressions = conditions;
    } else {
        return null;
    }

    const index_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.object_name_tokens orelse return error.UnsupportedSqlShape);
    var index_name_transferred = false;
    errdefer if (!index_name_transferred) alloc.free(index_name);
    const table_name = try generatedSqlObjectIdentifierAlloc(alloc, tokens, ast.index_table_tokens orelse return error.UnsupportedSqlShape);
    var table_name_transferred = false;
    errdefer if (!table_name_transferred) alloc.free(table_name);

    var columns = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (columns.items) |column| alloc.free(column);
        columns.deinit(alloc);
    }
    var index_keys = std.ArrayListUnmanaged(runtime_schema.RelationalIndexKey).empty;
    var has_ordered_index_key_metadata = false;
    errdefer {
        for (index_keys.items) |key| freeDdlRelationalIndexKey(alloc, key);
        index_keys.deinit(alloc);
    }
    var expressions = std.ArrayListUnmanaged(runtime_schema.UniqueExpression).empty;
    errdefer {
        clearDdlUniqueExpressions(alloc, expressions.items);
        expressions.deinit(alloc);
    }
    var generated_expression: ?runtime_schema.RelationalGeneratedValue = null;
    errdefer if (generated_expression) |generated| freeDdlGeneratedValue(alloc, generated);
    var without_overlaps_period: ?[]const u8 = null;
    errdefer if (without_overlaps_period) |period| alloc.free(period);
    var opclass: DdlIndexOpClass = .default;
    for (elements.items, 0..) |item, item_index| {
        if (item.start >= item.end or item.end > tokens.len) return error.UnsupportedSqlShape;
        if (try generatedCreateIndexWithoutOverlapsPeriodAlloc(alloc, tokens, item)) |period| {
            var period_transferred = false;
            errdefer if (!period_transferred) alloc.free(period);
            if (!ast.unique or without_overlaps_period != null) return error.UnsupportedSqlShape;
            without_overlaps_period = period;
            period_transferred = true;
            continue;
        }
        const expression_range = elements.expression_items[item_index];
        if (expression_range.start >= expression_range.end or expression_range.end > tokens.len) return error.UnsupportedSqlShape;
        const generated_gin_column_opclass = method == .gin and item.end == item.start + 2 and tokens[item.start + 1].kind == .identifier;
        if (generatedCreateIndexIdentifierElementSupported(tokens[item.start]) and
            expression_range.start == item.start and
            (expression_range.end == item.start + 1 or generated_gin_column_opclass))
        {
            if (try generatedCreateIndexElementHasWithoutOverlaps(tokens, item, expression_range)) {
                if (!ast.unique or without_overlaps_period != null) return error.UnsupportedSqlShape;
                without_overlaps_period = try generatedIdentifierAlloc(alloc, tokens, expression_range);
                continue;
            }
            const item_opclass = try generatedCreateIndexOpClass(tokens, method, item);
            if (item_opclass != .default) opclass = item_opclass;
            const column_range = if (generated_gin_column_opclass)
                generated_parser.GeneratedSqlTokenRange{ .start = item.start, .end = item.start + 1 }
            else
                expression_range;
            const column = try generatedIdentifierAlloc(alloc, tokens, column_range);
            var column_transferred = false;
            errdefer if (!column_transferred) alloc.free(column);
            const key_column = try alloc.dupe(u8, column);
            var key_column_transferred = false;
            errdefer if (!key_column_transferred) alloc.free(key_column);
            const key_collation = try generatedCreateIndexElementCollationAlloc(alloc, tokens, item, expression_range);
            var key_collation_transferred = false;
            errdefer if (!key_collation_transferred) if (key_collation) |collation| alloc.free(collation);
            if (method != .btree and key_collation != null) return error.UnsupportedSqlShape;
            try columns.append(alloc, column);
            column_transferred = true;
            try index_keys.append(alloc, .{
                .column = key_column,
                .collation = key_collation,
                .direction = generatedRelationalIndexKeyDirection(elements.directions[item_index]),
                .nulls = generatedRelationalIndexKeyNulls(elements.nulls_orders[item_index]),
            });
            key_column_transferred = true;
            key_collation_transferred = true;
            if (elements.directions[item_index] != null or elements.nulls_orders[item_index] != null) has_ordered_index_key_metadata = true;
            continue;
        }
        const simple_expression = try generatedCreateIndexSimpleExpression(tokens, item, expression_range, elements.expressions[item_index]);
        if (ast.unique) {
            if ((try generatedCreateIndexElementCollationRange(tokens, item, expression_range)) != null) return error.UnsupportedSqlShape;
            if (simple_expression) |simple| {
                const field = try alloc.dupe(u8, simple.field);
                var field_transferred = false;
                errdefer if (!field_transferred) alloc.free(field);
                try expressions.append(alloc, .{
                    .op = simple.op,
                    .field = field,
                });
                field_transferred = true;
            } else {
                if (!generatedCreateIndexExpressionItemSuffixSupported(tokens, item, expression_range)) return error.UnsupportedSqlShape;
                const row_expression = (try generatedCreateIndexRowExpressionWithOptionsAlloc(alloc, tokens, elements.expressions[item_index], .{ .allow_current_datetime = false })) orelse return error.UnsupportedSqlShape;
                var row_expression_transferred = false;
                errdefer if (!row_expression_transferred) runtime_schema.freeRelationalRowsExpression(alloc, row_expression);
                try expressions.append(alloc, .{
                    .op = .expression,
                    .expression = row_expression,
                });
                row_expression_transferred = true;
            }
        } else {
            if (generated_expression != null) return error.UnsupportedSqlShape;
            if (!generatedCreateIndexExpressionItemSuffixSupported(tokens, item, expression_range)) return error.UnsupportedSqlShape;
            const row_expression = (try generatedCreateIndexRowExpressionWithOptionsAlloc(alloc, tokens, elements.expressions[item_index], .{ .allow_current_datetime = false })) orelse return error.UnsupportedSqlShape;
            var row_expression_transferred = false;
            errdefer if (!row_expression_transferred) runtime_schema.freeRelationalRowsExpression(alloc, row_expression);
            row_expression_transferred = true;
            generated_expression = .{ .op = .expression, .expression = row_expression };
            const key_column = try alloc.dupe(u8, index_name);
            var key_column_transferred = false;
            errdefer if (!key_column_transferred) alloc.free(key_column);
            const key_collation = try generatedCreateIndexElementCollationAlloc(alloc, tokens, item, expression_range);
            var key_collation_transferred = false;
            errdefer if (!key_collation_transferred) if (key_collation) |collation| alloc.free(collation);
            try index_keys.append(alloc, .{
                .column = key_column,
                .collation = key_collation,
                .direction = generatedRelationalIndexKeyDirection(elements.directions[item_index]),
                .nulls = generatedRelationalIndexKeyNulls(elements.nulls_orders[item_index]),
            });
            key_column_transferred = true;
            key_collation_transferred = true;
            if (elements.directions[item_index] != null or elements.nulls_orders[item_index] != null) has_ordered_index_key_metadata = true;
        }
    }
    if (columns.items.len == 0 and expressions.items.len == 0 and generated_expression == null) return error.UnsupportedSqlShape;
    try grammar.validateSqlIdentifierListUnique(columns.items);
    try expr_type.validateSqlUniqueExpressionListUnique(expressions.items);

    const nulls_policy = try generatedCreateIndexNullsNotDistinct(tokens, ast, end);
    if (nulls_policy != null and !ast.unique) return error.UnsupportedSqlShape;
    const nulls_not_distinct = nulls_policy orelse false;
    if (nulls_not_distinct and without_overlaps_period != null) return error.UnsupportedSqlShape;

    var include_columns: []const []const u8 = &.{};
    var include_columns_owned = false;
    errdefer if (include_columns_owned) freeStringSlice(alloc, include_columns);
    if (ast.index_include_tokens) |include_range| {
        include_columns = try generatedIdentifierListAlloc(alloc, tokens, include_range, ast.index_include_items);
        include_columns_owned = true;
        try grammar.validateSqlIdentifierListsDisjoint(columns.items, include_columns);
    } else if (ast.index_include_items.count != 0) {
        return error.UnsupportedSqlShape;
    }

    const owned_columns = try columns.toOwnedSlice(alloc);
    var columns_transferred = false;
    errdefer if (!columns_transferred) freeStringSlice(alloc, owned_columns);
    const owned_expressions = try expressions.toOwnedSlice(alloc);
    var expressions_transferred = false;
    errdefer if (!expressions_transferred) freeDdlUniqueExpressions(alloc, owned_expressions);
    const preserve_index_keys = method == .btree or has_ordered_index_key_metadata or index_keys.items.len >= 2;
    const owned_index_keys = if (preserve_index_keys) try index_keys.toOwnedSlice(alloc) else empty_keys: {
        for (index_keys.items) |key| freeDdlRelationalIndexKey(alloc, key);
        index_keys.clearRetainingCapacity();
        index_keys.deinit(alloc);
        index_keys = .empty;
        break :empty_keys &.{};
    };
    var index_keys_transferred = false;
    errdefer if (!index_keys_transferred) freeDdlRelationalIndexKeys(alloc, owned_index_keys);

    index_name_transferred = true;
    table_name_transferred = true;
    columns_transferred = true;
    expressions_transferred = true;
    index_keys_transferred = true;
    include_columns_owned = false;
    where_transferred = true;
    where_expressions_transferred = true;
    const period = without_overlaps_period;
    without_overlaps_period = null;
    return .{
        .index_name = index_name,
        .table_name = table_name,
        .if_not_exists = ast.if_not_exists,
        .unique = ast.unique,
        .method = method,
        .opclass = opclass,
        .columns = owned_columns,
        .include_columns = include_columns,
        .index_keys = owned_index_keys,
        .expressions = owned_expressions,
        .generated_expression = generated_expression,
        .without_overlaps_period = period,
        .nulls_not_distinct = nulls_not_distinct,
        .where = where,
        .where_expressions = where_expressions,
    };
}

const DerivedIndexOptionValue = union(enum) {
    string: []const u8,
    number: []const u8,
    boolean: bool,
};

fn parseDerivedIndexFieldPathAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) ![]const u8 {
    const cursor = parser.Cursor.init(tokens, pos);
    const wrapper_count = grammar.consumeDdlIndexExpressionWrappers(tokens, pos);
    const field = if (cursor.peekFunctionCallIf(expr_token.sqlKeywordIsJsonExtractPathFunction))
        try parseDerivedIndexJsonExtractPathFunctionAlloc(alloc, tokens, pos)
    else
        try parseDerivedIndexIdentifierOrJsonOperatorPathAlloc(alloc, tokens, pos);
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    try grammar.closeDdlIndexExpressionWrappers(tokens, pos, wrapper_count);
    try validateDerivedIndexRenderedFieldPath(field);
    field_transferred = true;
    return field;
}

fn parseDerivedIndexIdentifierOrJsonOperatorPathAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) ![]const u8 {
    const cursor = parser.Cursor.init(tokens, pos);
    const root = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
    var root_transferred = false;
    errdefer if (!root_transferred) alloc.free(root);

    const operator: ?parser.TokenKind = if (parseDerivedIndexJsonOperatorKind(tokens, pos.*)) |kind| blk: {
        _ = cursor.matchToken(kind) orelse unreachable;
        break :blk kind;
    } else null;

    if (operator) |kind| {
        const path = try value_mod.parseJsonExtractOperatorPathOwnedAlloc(alloc, tokens, pos, &.{}, kind);
        defer alloc.free(path);
        const field = try joinDerivedIndexJsonFieldPathAlloc(alloc, root, path);
        root_transferred = true;
        alloc.free(root);
        return field;
    }

    root_transferred = true;
    return root;
}

fn parseDerivedIndexJsonOperatorKind(tokens: []const grammar.Token, pos: usize) ?parser.TokenKind {
    if (pos + 1 >= tokens.len) return null;
    const kind = tokens[pos].kind;
    switch (kind) {
        .arrow_json, .arrow_text, .path_arrow_json, .path_arrow_text => {},
        else => return null,
    }
    return switch (tokens[pos + 1].kind) {
        .string, .number, .placeholder => kind,
        else => null,
    };
}

fn parseDerivedIndexJsonExtractPathFunctionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) ![]const u8 {
    const cursor = parser.Cursor.init(tokens, pos);
    _ = cursor.matchIdentifierIf(expr_token.sqlKeywordIsJsonExtractPathFunction) orelse return error.UnsupportedSqlShape;
    try cursor.expectToken(.lparen);
    const root = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
    defer alloc.free(root);
    const path = try value_mod.parseJsonExtractPathSegmentsAlloc(alloc, tokens, pos, &.{});
    defer alloc.free(path);
    try cursor.expectToken(.rparen);
    return try joinDerivedIndexJsonFieldPathAlloc(alloc, root, path);
}

fn joinDerivedIndexJsonFieldPathAlloc(
    alloc: std.mem.Allocator,
    root: []const u8,
    path: []const u8,
) ![]const u8 {
    if (root.len == 0 or path.len == 0) return error.UnsupportedSqlShape;
    try validateDerivedIndexRenderedFieldPath(root);
    try validateDerivedIndexRenderedFieldPath(path);
    return try std.fmt.allocPrint(alloc, "{s}.{s}", .{ root, path });
}

fn validateDerivedIndexRenderedFieldPath(path: []const u8) !void {
    if (path.len == 0) return error.UnsupportedSqlShape;
    if (path[0] == '.' or path[path.len - 1] == '.') return error.UnsupportedSqlShape;
    var prev_dot = false;
    for (path) |ch| {
        if (ch == '.') {
            if (prev_dot) return error.UnsupportedSqlShape;
            prev_dot = true;
        } else {
            prev_dot = false;
        }
    }
}

const DerivedIndexOption = struct {
    name: []const u8,
    value: DerivedIndexOptionValue,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.name);
        switch (self.value) {
            .string => |value| alloc.free(value),
            .number => |value| alloc.free(value),
            .boolean => {},
        }
        self.* = undefined;
    }
};

fn parseDerivedIndexOptionsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) ![]DerivedIndexOption {
    const cursor = parser.Cursor.init(tokens, pos);
    if (!cursor.matchKeyword("with")) return &.{};
    try cursor.expectToken(.lparen);

    var options = std.ArrayListUnmanaged(DerivedIndexOption).empty;
    errdefer {
        for (options.items) |*option| option.deinit(alloc);
        options.deinit(alloc);
    }
    while (true) {
        const name_token = cursor.matchToken(.identifier) orelse return error.UnsupportedSqlShape;
        const name = try alloc.dupe(u8, name_token.text);
        var name_transferred = false;
        errdefer if (!name_transferred) alloc.free(name);
        try cursor.expectToken(.eq);

        const value_token = cursor.matchToken(.string) orelse
            cursor.matchToken(.number) orelse
            cursor.matchToken(.identifier) orelse return error.UnsupportedSqlShape;
        const value: DerivedIndexOptionValue = switch (value_token.kind) {
            .string => .{ .string = try alloc.dupe(u8, value_token.text) },
            .number => .{ .number = try alloc.dupe(u8, value_token.text) },
            .identifier => blk: {
                if (std.ascii.eqlIgnoreCase(value_token.text, "true")) break :blk .{ .boolean = true };
                if (std.ascii.eqlIgnoreCase(value_token.text, "false")) break :blk .{ .boolean = false };
                break :blk .{ .string = try alloc.dupe(u8, value_token.text) };
            },
            else => unreachable,
        };
        var value_transferred = false;
        errdefer if (!value_transferred) switch (value) {
            .string => |owned| alloc.free(owned),
            .number => |owned| alloc.free(owned),
            .boolean => {},
        };

        try options.append(alloc, .{ .name = name, .value = value });
        name_transferred = true;
        value_transferred = true;

        if (cursor.matchToken(.comma) == null) break;
    }
    try cursor.expectToken(.rparen);
    return try options.toOwnedSlice(alloc);
}

fn parseGeneratedDerivedIndexOptionsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    range: ?generated_parser.GeneratedSqlTokenRange,
) ![]DerivedIndexOption {
    const options_range = range orelse return &.{};
    if (options_range.start >= options_range.end or options_range.end > tokens.len) return error.UnsupportedSqlShape;
    var pos = options_range.start;
    const options = try parseDerivedIndexOptionsAlloc(alloc, tokens, &pos);
    errdefer freeDerivedIndexOptions(alloc, options);
    if (pos != options_range.end) return error.UnsupportedSqlShape;
    return options;
}

fn freeDerivedIndexOptions(alloc: std.mem.Allocator, options: []DerivedIndexOption) void {
    for (options) |*option| option.deinit(alloc);
    if (options.len > 0) alloc.free(options);
}

fn derivedIndexOption(options: []const DerivedIndexOption, name: []const u8) ?DerivedIndexOptionValue {
    for (options) |option| {
        if (std.ascii.eqlIgnoreCase(option.name, name)) return option.value;
    }
    return null;
}

fn derivedIndexOptionString(options: []const DerivedIndexOption, name: []const u8) ?[]const u8 {
    const value = derivedIndexOption(options, name) orelse return null;
    return switch (value) {
        .string => |text| text,
        .number => |text| text,
        .boolean => null,
    };
}

fn derivedIndexOptionNumber(options: []const DerivedIndexOption, name: []const u8) ?[]const u8 {
    const value = derivedIndexOption(options, name) orelse return null;
    return switch (value) {
        .number => |text| text,
        else => null,
    };
}

fn appendJsonStringLiteral(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    value: []const u8,
) !void {
    const encoded = try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(value, .{})});
    defer alloc.free(encoded);
    try out.appendSlice(alloc, encoded);
}

fn appendJsonStringField(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    first: *bool,
    name: []const u8,
    value: []const u8,
) !void {
    if (!first.*) try out.append(alloc, ',');
    first.* = false;
    try appendJsonStringLiteral(alloc, out, name);
    try out.append(alloc, ':');
    try appendJsonStringLiteral(alloc, out, value);
}

fn appendJsonBoolField(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    first: *bool,
    name: []const u8,
    value: bool,
) !void {
    if (!first.*) try out.append(alloc, ',');
    first.* = false;
    try appendJsonStringLiteral(alloc, out, name);
    try out.append(alloc, ':');
    try out.appendSlice(alloc, if (value) "true" else "false");
}

fn appendJsonNumberField(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    first: *bool,
    name: []const u8,
    value: []const u8,
) !void {
    if (!first.*) try out.append(alloc, ',');
    first.* = false;
    try appendJsonStringLiteral(alloc, out, name);
    try out.append(alloc, ':');
    try out.appendSlice(alloc, value);
}

fn appendJsonCommaStringArrayField(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    first: *bool,
    name: []const u8,
    csv: []const u8,
) !void {
    if (!first.*) try out.append(alloc, ',');
    first.* = false;
    try appendJsonStringLiteral(alloc, out, name);
    try out.appendSlice(alloc, ":[");
    var split = std.mem.splitScalar(u8, csv, ',');
    var item_index: usize = 0;
    while (split.next()) |raw_item| {
        const item = std.mem.trim(u8, raw_item, " \t\r\n");
        if (item.len == 0) return error.UnsupportedSqlShape;
        if (item_index > 0) try out.append(alloc, ',');
        try appendJsonStringLiteral(alloc, out, item);
        item_index += 1;
    }
    if (item_index == 0) return error.UnsupportedSqlShape;
    try out.append(alloc, ']');
}

fn graphIndexConfigJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    source_field: []const u8,
    target_field: []const u8,
    type_field: ?[]const u8,
    weight_field: ?[]const u8,
) ![]u8 {
    const options = try parseDerivedIndexOptionsAlloc(alloc, tokens, pos);
    defer freeDerivedIndexOptions(alloc, options);
    if (derivedIndexOption(options, "type_field") != null or derivedIndexOption(options, "weight_field") != null) return error.UnsupportedSqlShape;

    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;
    try appendJsonStringField(alloc, &out, &first, "type", "graph");
    try out.append(alloc, ',');
    try appendJsonStringLiteral(alloc, &out, "edge_table");
    try out.appendSlice(alloc, ":{");
    var edge_first = true;
    try appendJsonStringField(alloc, &out, &edge_first, "source_field", source_field);
    try appendJsonStringField(alloc, &out, &edge_first, "target_field", target_field);
    if (type_field) |field| try appendJsonStringField(alloc, &out, &edge_first, "type_field", field);
    if (weight_field) |field| try appendJsonStringField(alloc, &out, &edge_first, "weight_field", field);
    try out.append(alloc, '}');
    try appendJsonStringField(alloc, &out, &first, "edge_policy", derivedIndexOptionString(options, "edge_policy") orelse "all");

    for (options) |option| {
        if (std.ascii.eqlIgnoreCase(option.name, "edge_policy")) continue;
        try appendJsonOptionField(alloc, &out, &first, option);
    }
    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

fn graphExtractionIndexConfigJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    enrichment_name: []const u8,
    input_field: []const u8,
    model: []const u8,
    edges_json_path: []const u8,
    target_path: []const u8,
    type_path: ?[]const u8,
    weight_path: ?[]const u8,
) ![]u8 {
    const options = try parseDerivedIndexOptionsAlloc(alloc, tokens, pos);
    defer freeDerivedIndexOptions(alloc, options);

    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;
    try appendJsonStringField(alloc, &out, &first, "type", "graph");

    try out.append(alloc, ',');
    try appendJsonStringLiteral(alloc, &out, "source");
    try out.appendSlice(alloc, ":{");
    var source_first = true;
    try appendJsonStringField(alloc, &out, &source_first, "kind", "artifact");
    try appendJsonStringField(alloc, &out, &source_first, "artifact", enrichment_name);
    try appendJsonStringField(alloc, &out, &source_first, "path", edges_json_path);
    try appendJsonStringField(alloc, &out, &source_first, "format", "extraction_relation");
    try out.append(alloc, '}');

    try out.append(alloc, ',');
    try appendJsonStringLiteral(alloc, &out, "artifact");
    try out.appendSlice(alloc, ":{");
    var artifact_first = true;
    try appendJsonStringField(alloc, &out, &artifact_first, "name", enrichment_name);
    try appendJsonStringField(alloc, &out, &artifact_first, "kind", "asset");
    try appendJsonStringField(alloc, &out, &artifact_first, "field", input_field);
    try appendJsonStringField(alloc, &out, &artifact_first, "content_type", "application/json");
    try out.append(alloc, ',');
    try appendJsonStringLiteral(alloc, &out, "producer_json");
    try out.appendSlice(alloc, ":{");
    var producer_first = true;
    try appendJsonStringField(alloc, &out, &producer_first, "type", "extractor");
    try appendJsonStringField(alloc, &out, &producer_first, "model", model);
    try out.append(alloc, '}');
    try out.append(alloc, '}');

    try out.append(alloc, ',');
    try appendJsonStringLiteral(alloc, &out, "nodes");
    try out.appendSlice(alloc, ":{");
    var nodes_first = true;
    try appendJsonStringField(alloc, &out, &nodes_first, "model", "document");
    try appendJsonStringField(alloc, &out, &nodes_first, "source", "{{ _doc.key }}");
    const target_template = try std.fmt.allocPrint(alloc, "{{{{ _item.{s} }}}}", .{target_path});
    defer alloc.free(target_template);
    try appendJsonStringField(alloc, &out, &nodes_first, "target", target_template);
    try out.append(alloc, '}');

    if (type_path != null or weight_path != null) {
        try out.append(alloc, ',');
        try appendJsonStringLiteral(alloc, &out, "edge");
        try out.appendSlice(alloc, ":{");
        var edge_first = true;
        if (type_path) |path| {
            const type_template = try std.fmt.allocPrint(alloc, "{{{{ _item.{s} }}}}", .{path});
            defer alloc.free(type_template);
            try appendJsonStringField(alloc, &out, &edge_first, "type", type_template);
        }
        if (weight_path) |path| {
            const weight_template = try std.fmt.allocPrint(alloc, "{{{{ _item.{s} }}}}", .{path});
            defer alloc.free(weight_template);
            try appendJsonStringField(alloc, &out, &edge_first, "weight", weight_template);
        }
        try out.append(alloc, '}');
    }

    try appendJsonStringField(alloc, &out, &first, "edge_policy", derivedIndexOptionString(options, "edge_policy") orelse "all");

    for (options) |option| {
        if (std.ascii.eqlIgnoreCase(option.name, "edge_policy")) continue;
        try appendJsonOptionField(alloc, &out, &first, option);
    }
    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

fn graphMetricIndexConfigJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    graph_index: []const u8,
    metric_name: []const u8,
    algorithm: []const u8,
) ![]u8 {
    const options = try parseDerivedIndexOptionsAlloc(alloc, tokens, pos);
    defer freeDerivedIndexOptions(alloc, options);
    if (derivedIndexOption(options, "graph_index") != null or
        derivedIndexOption(options, "metric") != null or
        derivedIndexOption(options, "algorithm") != null)
    {
        return error.UnsupportedSqlShape;
    }

    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;
    try appendJsonStringField(alloc, &out, &first, "type", "graph_metric");
    try appendJsonStringField(alloc, &out, &first, "graph_index", graph_index);
    try appendJsonStringField(alloc, &out, &first, "metric", metric_name);
    try appendJsonStringField(alloc, &out, &first, "algorithm", algorithm);
    try appendJsonStringField(alloc, &out, &first, "metric_freshness", derivedIndexOptionString(options, "metric_freshness") orelse "published");
    try appendJsonStringField(alloc, &out, &first, "publish", derivedIndexOptionString(options, "publish") orelse "after_max_iterations");

    for (options) |option| {
        if (std.ascii.eqlIgnoreCase(option.name, "metric_freshness") or
            std.ascii.eqlIgnoreCase(option.name, "publish"))
        {
            continue;
        }
        try appendJsonOptionField(alloc, &out, &first, option);
    }

    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

fn createGraphMetricIndexConfigJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    graph_index: []const u8,
    metric_name: []const u8,
) ![]u8 {
    const options = try parseDerivedIndexOptionsAlloc(alloc, tokens, pos);
    defer freeDerivedIndexOptions(alloc, options);
    if (derivedIndexOption(options, "graph_index") != null) return error.UnsupportedSqlShape;
    if (derivedIndexOption(options, "metric") != null and derivedIndexOption(options, "algorithm") != null) return error.UnsupportedSqlShape;
    const algorithm = derivedIndexOptionString(options, "metric") orelse
        derivedIndexOptionString(options, "algorithm") orelse return error.UnsupportedSqlShape;

    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;
    try appendJsonStringField(alloc, &out, &first, "type", "graph_metric");
    try appendJsonStringField(alloc, &out, &first, "graph_index", graph_index);
    try appendJsonStringField(alloc, &out, &first, "metric", metric_name);
    try appendJsonStringField(alloc, &out, &first, "algorithm", algorithm);
    try appendJsonStringField(alloc, &out, &first, "metric_freshness", derivedIndexOptionString(options, "metric_freshness") orelse "published");
    try appendJsonStringField(alloc, &out, &first, "publish", derivedIndexOptionString(options, "publish") orelse "after_max_iterations");

    for (options) |option| {
        if (std.ascii.eqlIgnoreCase(option.name, "metric") or
            std.ascii.eqlIgnoreCase(option.name, "algorithm") or
            std.ascii.eqlIgnoreCase(option.name, "metric_freshness") or
            std.ascii.eqlIgnoreCase(option.name, "publish"))
        {
            continue;
        }
        try appendJsonOptionField(alloc, &out, &first, option);
    }

    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

fn appendJsonOptionField(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    first: *bool,
    option: DerivedIndexOption,
) !void {
    switch (option.value) {
        .string => |value| try appendJsonStringField(alloc, out, first, option.name, value),
        .number => |value| try appendJsonNumberField(alloc, out, first, option.name, value),
        .boolean => |value| try appendJsonBoolField(alloc, out, first, option.name, value),
    }
}

fn appendFullTextIndexConfigOptions(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    first: *bool,
    options: []const DerivedIndexOption,
) !void {
    for (options) |option| {
        if (std.ascii.eqlIgnoreCase(option.name, "analyzer")) {
            switch (option.value) {
                .string => |value| try appendJsonStringField(alloc, out, first, "analyzer", value),
                else => return error.UnsupportedSqlShape,
            }
        } else if (std.ascii.eqlIgnoreCase(option.name, "scoring")) {
            switch (option.value) {
                .string => |value| try appendJsonStringField(alloc, out, first, "scoring", value),
                else => return error.UnsupportedSqlShape,
            }
        } else if (std.ascii.eqlIgnoreCase(option.name, "highlight")) {
            switch (option.value) {
                .boolean => |value| try appendJsonBoolField(alloc, out, first, "highlight", value),
                else => return error.UnsupportedSqlShape,
            }
        } else if (std.ascii.eqlIgnoreCase(option.name, "snippet")) {
            switch (option.value) {
                .boolean => |value| try appendJsonBoolField(alloc, out, first, "snippet", value),
                else => return error.UnsupportedSqlShape,
            }
        } else {
            return error.UnsupportedSqlShape;
        }
    }
}

fn vectorMetricForOpClass(opclass: DdlIndexOpClass) []const u8 {
    return switch (opclass) {
        .vector_l2_ops => "l2_squared",
        .vector_ip_ops => "inner_product",
        .vector_cosine_ops, .default => "cosine",
        .jsonb_path_ops, .array_ops => "cosine",
    };
}

fn derivedIndexConfigJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    method: DdlIndexMethod,
    opclass: DdlIndexOpClass,
    columns: []const []const u8,
) ![]const u8 {
    const options = try parseDerivedIndexOptionsAlloc(alloc, tokens, pos);
    defer freeDerivedIndexOptions(alloc, options);
    return try derivedIndexConfigJsonFromOptionsAlloc(alloc, method, opclass, columns, options);
}

fn derivedIndexConfigJsonFromOptionsAlloc(
    alloc: std.mem.Allocator,
    method: DdlIndexMethod,
    opclass: DdlIndexOpClass,
    columns: []const []const u8,
    options: []const DerivedIndexOption,
) ![]const u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;

    switch (method) {
        .antfly_full_text => {
            try appendJsonStringField(alloc, &out, &first, "type", "full_text");
            try appendJsonStringField(alloc, &out, &first, "field", columns[0]);
            try appendFullTextIndexConfigOptions(alloc, &out, &first, options);
        },
        .hnsw => {
            try appendJsonStringField(alloc, &out, &first, "type", "embeddings");
            try appendJsonStringField(alloc, &out, &first, "field", columns[0]);
            try appendJsonBoolField(alloc, &out, &first, "external", true);
            try appendJsonStringField(alloc, &out, &first, "metric", derivedIndexOptionString(options, "metric") orelse vectorMetricForOpClass(opclass));
            if (derivedIndexOptionNumber(options, "dimension")) |dimension| try appendJsonNumberField(alloc, &out, &first, "dimension", dimension);
        },
        .antfly_aknn => {
            const enrichment_name = derivedIndexOptionString(options, "embedding_name") orelse "embedding";
            try appendJsonStringField(alloc, &out, &first, "type", "embeddings");
            try appendJsonStringField(alloc, &out, &first, "field", columns[0]);
            try appendJsonBoolField(alloc, &out, &first, "external", false);
            try appendJsonStringField(alloc, &out, &first, "metric", derivedIndexOptionString(options, "metric") orelse "cosine");
            if (derivedIndexOptionNumber(options, "dimension")) |dimension| try appendJsonNumberField(alloc, &out, &first, "dimension", dimension);
            try out.append(alloc, ',');
            try appendJsonStringLiteral(alloc, &out, "enrichments");
            try out.appendSlice(alloc, ":[{");
            var enrichment_first = true;
            try appendJsonStringField(alloc, &out, &enrichment_first, "name", enrichment_name);
            try appendJsonStringField(alloc, &out, &enrichment_first, "kind", "embedding");
            try appendJsonStringField(alloc, &out, &enrichment_first, "field", columns[0]);
            if (derivedIndexOptionNumber(options, "dimension")) |dimension| try appendJsonNumberField(alloc, &out, &enrichment_first, "expected_dims", dimension);
            if (derivedIndexOptionString(options, "model")) |model| try appendJsonStringField(alloc, &out, &enrichment_first, "model", model);
            try out.appendSlice(alloc, "}]");
        },
        .antfly_graph => {
            try appendJsonStringField(alloc, &out, &first, "type", "graph");
            try out.append(alloc, ',');
            try appendJsonStringLiteral(alloc, &out, "edge_table");
            try out.appendSlice(alloc, ":{");
            var edge_first = true;
            try appendJsonStringField(alloc, &out, &edge_first, "source_field", columns[0]);
            try appendJsonStringField(alloc, &out, &edge_first, "target_field", columns[1]);
            if (derivedIndexOptionString(options, "type_field")) |type_field| try appendJsonStringField(alloc, &out, &edge_first, "type_field", type_field);
            if (derivedIndexOptionString(options, "weight_field")) |weight_field| try appendJsonStringField(alloc, &out, &edge_first, "weight_field", weight_field);
            try out.append(alloc, '}');
            try appendJsonStringField(alloc, &out, &first, "edge_policy", derivedIndexOptionString(options, "edge_policy") orelse "all");
        },
        .antfly_graph_metric => {
            try appendJsonStringField(alloc, &out, &first, "type", "graph_metric");
            try appendJsonStringField(alloc, &out, &first, "graph_index", derivedIndexOptionString(options, "graph_index") orelse return error.UnsupportedSqlShape);
            try appendJsonStringField(alloc, &out, &first, "metric", derivedIndexOptionString(options, "metric") orelse return error.UnsupportedSqlShape);
            try appendJsonStringField(alloc, &out, &first, "metric_freshness", derivedIndexOptionString(options, "metric_freshness") orelse "published");
            try appendJsonStringField(alloc, &out, &first, "publish", derivedIndexOptionString(options, "publish") orelse "after_max_iterations");
        },
        .antfly_hybrid => {
            try appendJsonStringField(alloc, &out, &first, "type", "hybrid");
            try appendJsonCommaStringArrayField(alloc, &out, &first, "sources", derivedIndexOptionString(options, "sources") orelse return error.UnsupportedSqlShape);
            try appendJsonStringField(alloc, &out, &first, "fusion", derivedIndexOptionString(options, "fusion") orelse "rrf");
        },
        .antfly_algebraic => {
            try appendJsonStringField(alloc, &out, &first, "type", "algebraic");
            if (derivedIndexOption(options, "derive_from_schema")) |value| switch (value) {
                .boolean => |enabled| try appendJsonBoolField(alloc, &out, &first, "derive_from_schema", enabled),
                else => return error.UnsupportedSqlShape,
            } else {
                try appendJsonBoolField(alloc, &out, &first, "derive_from_schema", true);
            }
        },
        .btree, .gin => unreachable,
    }

    for (options) |option| {
        if (std.ascii.eqlIgnoreCase(option.name, "metric") or
            std.ascii.eqlIgnoreCase(option.name, "analyzer") or
            std.ascii.eqlIgnoreCase(option.name, "scoring") or
            std.ascii.eqlIgnoreCase(option.name, "highlight") or
            std.ascii.eqlIgnoreCase(option.name, "snippet") or
            std.ascii.eqlIgnoreCase(option.name, "embedding_name") or
            std.ascii.eqlIgnoreCase(option.name, "dimension") or
            std.ascii.eqlIgnoreCase(option.name, "type_field") or
            std.ascii.eqlIgnoreCase(option.name, "weight_field") or
            std.ascii.eqlIgnoreCase(option.name, "edge_policy") or
            std.ascii.eqlIgnoreCase(option.name, "graph_index") or
            std.ascii.eqlIgnoreCase(option.name, "metric_freshness") or
            std.ascii.eqlIgnoreCase(option.name, "publish") or
            std.ascii.eqlIgnoreCase(option.name, "sources") or
            std.ascii.eqlIgnoreCase(option.name, "fusion") or
            std.ascii.eqlIgnoreCase(option.name, "derive_from_schema"))
        {
            continue;
        }
        if (method == .antfly_algebraic) return error.UnsupportedSqlShape;
        try appendJsonOptionField(alloc, &out, &first, option);
    }

    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

fn parseOptionalDdlAlterColumnRewriteExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    hooks: DdlColumnDefinitionOptions,
) !?AlterColumnRewriteExpression {
    const cursor = parser.Cursor.init(tokens, pos);
    if (!cursor.matchKeyword("using")) return null;
    const expression_start = pos.*;
    const expression_range = generated_parser.GeneratedSqlTokenRange{ .start = expression_start, .end = tokens.len };
    const expression_ast = hooks.rewrite_expression_ast orelse return error.UnsupportedSqlShape;
    const full_tokens = hooks.rewrite_expression_full_tokens orelse return error.UnsupportedSqlShape;
    const expected_range = hooks.rewrite_expression_tokens orelse return error.UnsupportedSqlShape;
    const full_range = generated_parser.GeneratedSqlTokenRange{
        .start = hooks.rewrite_expression_token_offset + expression_range.start,
        .end = hooks.rewrite_expression_token_offset + expression_range.end,
    };
    if (!generatedDdlTokenRangeEqual(full_range, expected_range)) return error.UnsupportedSqlShape;
    if (!generatedDdlTokenRangeEqual(expression_ast.tokens orelse return error.UnsupportedSqlShape, expected_range)) return error.UnsupportedSqlShape;
    const expression = if (try generatedDdlRoutineRowExpressionFromAstAlloc(alloc, full_tokens, expression_ast.*, hooks.expression_options)) |routine_expression|
        routine_expression
    else
        (try generatedCreateIndexRowExpressionAlloc(alloc, full_tokens, expression_ast.*)) orelse return error.UnsupportedSqlShape;
    pos.* = tokens.len;
    errdefer runtime_schema.freeRelationalRowsExpression(alloc, expression);
    return .{ .expression = expression };
}

fn alterTableAddColumnOperationFromParts(
    column: runtime_schema.RelationalColumn,
    if_not_exists: bool,
    unique_constraints: []const runtime_schema.UniqueConstraint,
    foreign_keys: []const runtime_schema.ForeignKey,
    checks: []const runtime_schema.RelationalCheck,
) AlterTableOperation {
    return .{ .add_column = .{
        .column = column,
        .if_not_exists = if_not_exists,
        .unique_constraints = unique_constraints,
        .foreign_keys = foreign_keys,
        .checks = checks,
    } };
}

fn alterTableAddPeriodOperation(period: runtime_schema.RelationalPeriod) AlterTableOperation {
    return .{ .add_period = period };
}

fn alterTableAddPrimaryKeyOperation(primary_key: runtime_schema.PrimaryKey) AlterTableOperation {
    return .{ .add_primary_key = primary_key };
}

fn alterTableAddUniqueConstraintOperation(constraint: runtime_schema.UniqueConstraint) AlterTableOperation {
    return .{ .add_unique_constraint = constraint };
}

fn alterTableAddForeignKeyOperation(foreign_key: runtime_schema.ForeignKey) AlterTableOperation {
    return .{ .add_foreign_key = foreign_key };
}

fn alterTableAddCheckOperation(check: runtime_schema.RelationalCheck) AlterTableOperation {
    return .{ .add_check = check };
}

const DdlConstraintTiming = struct {
    deferrable: bool = false,
    timing: runtime_schema.ForeignKeyTiming = .immediate,
};

const DdlTemporalColumnList = struct {
    columns: []const []const u8,
    without_overlaps_period: ?[]const u8 = null,

    fn deinit(self: @This(), alloc: std.mem.Allocator) void {
        freeStringSlice(alloc, self.columns);
        if (self.without_overlaps_period) |period| alloc.free(@constCast(period));
    }
};

fn parseOptionalDdlConstraintTiming(tokens: []const grammar.Token, pos: *usize) !DdlConstraintTiming {
    const cursor = parser.Cursor.init(tokens, pos);
    var timing: DdlConstraintTiming = .{};
    var saw_deferrability = false;
    var saw_initially = false;
    while (true) {
        if (cursor.matchKeyword("deferrable")) {
            if (saw_deferrability) return error.UnsupportedSqlShape;
            saw_deferrability = true;
            timing.deferrable = true;
            continue;
        }
        if (cursor.peekKeyword("not")) {
            const checkpoint = cursor.checkpoint();
            _ = cursor.matchKeyword("not");
            if (!cursor.matchKeyword("deferrable")) {
                cursor.restore(checkpoint);
                break;
            }
            if (saw_deferrability) return error.UnsupportedSqlShape;
            if (timing.timing == .deferred) return error.UnsupportedSqlShape;
            saw_deferrability = true;
            timing.deferrable = false;
            continue;
        }
        if (!cursor.matchKeyword("initially")) break;
        {
            if (saw_initially) return error.UnsupportedSqlShape;
            saw_initially = true;
            if (cursor.matchKeyword("deferred")) {
                if (saw_deferrability and !timing.deferrable) return error.UnsupportedSqlShape;
                timing.deferrable = true;
                timing.timing = .deferred;
            } else {
                try cursor.expectKeyword("immediate");
                timing.timing = .immediate;
            }
            continue;
        }
    }
    return timing;
}

fn parseDdlColumnListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) ![]const []const u8 {
    const cursor = parser.Cursor.init(tokens, pos);
    try cursor.expectToken(.lparen);
    var columns = std.ArrayListUnmanaged([]const u8).empty;
    errdefer freeStringList(alloc, &columns);
    while (true) {
        const column = try grammar.parseIdentifierOwnedAlloc(alloc, tokens, pos);
        var transferred = false;
        errdefer if (!transferred) alloc.free(column);
        try columns.append(alloc, column);
        transferred = true;
        if (cursor.matchToken(.comma) == null) break;
    }
    try cursor.expectToken(.rparen);
    if (columns.items.len == 0) return error.UnsupportedSqlShape;
    return try columns.toOwnedSlice(alloc);
}

fn parseDdlUniqueColumnListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
) ![]const []const u8 {
    const columns = try parseDdlColumnListAlloc(alloc, tokens, pos);
    errdefer freeStringSlice(alloc, columns);
    try grammar.validateSqlIdentifierListUnique(columns);
    return columns;
}

fn parseOptionalDdlConstraintIncludeAlloc(
    alloc: std.mem.Allocator,
