fn generatedDdlWriteScalarOrderJson(
    writer: *std.Io.Writer,
    tokens: []const grammar.Token,
    list: generated_parser.GeneratedSqlListAst,
    index: usize,
    projection: GeneratedDdlScalarProjection,
) !void {
    const expression_range = list.expression_items[index];
    const field = if (expression_range.end == expression_range.start + 1 and tokens[expression_range.start].kind == .number) blk: {
        if (!std.mem.eql(u8, tokens[expression_range.start].text, "1")) return error.UnsupportedSqlShape;
        break :blk projection.output_field;
    } else blk: {
        const name = generatedDdlSingleTokenText(tokens, expression_range);
        if (projection.projection_alias.len != 0 and std.mem.eql(u8, name, projection.projection_alias)) break :blk projection.output_field;
        break :blk name;
    };
    const direction: []const u8 = if (list.directions[index]) |dir| switch (dir) {
        .asc => "asc",
        .desc => "desc",
    } else "asc";
    if (list.nulls_orders[index]) |nulls_order| {
        try writer.writeByte('{');
        try writer.print("\"field\":{f}", .{std.json.fmt(field, .{})});
        if (nulls_order == .first) try writer.writeAll(",\"direction\":\"desc\"");
        try writer.writeAll(",\"null_test\":\"is_null\"},");
    }
    try writer.writeByte('{');
    try writer.print("\"field\":{f}", .{std.json.fmt(field, .{})});
    if (!std.mem.eql(u8, direction, "asc")) try writer.print(",\"direction\":{f}", .{std.json.fmt(direction, .{})});
    try writer.writeByte('}');
}

fn generatedDdlExpressionFieldName(
    tokens: []const grammar.Token,
    maybe_expression: ?*const generated_parser.GeneratedSqlExpressionAst,
    range: generated_parser.GeneratedSqlTokenRange,
) []const u8 {
    if (maybe_expression) |expression| {
        if (expression.kind != .token_range) return "";
        if (!generatedDdlTokenRangeEqual(expression.tokens orelse return "", range)) return "";
    }
    return generatedDdlSingleTokenText(tokens, range);
}

fn generatedDdlUnaryInnerExpression(expression: generated_parser.GeneratedSqlExpressionAst) ?*const generated_parser.GeneratedSqlExpressionAst {
    if (expression.right_expression) |right| return right;
    return expression.inner_expression;
}

fn generatedDdlComparisonOp(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) ![]const u8 {
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    return switch (tokens[range.start].kind) {
        .eq => "eq",
        .neq => "ne",
        .gt => "gt",
        .gte => "gte",
        .lt => "lt",
        .lte => "lte",
        else => error.UnsupportedSqlShape,
    };
}

fn generatedDdlNegatedComparisonOp(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) ![]const u8 {
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    return switch (tokens[range.start].kind) {
        .eq => "ne",
        .neq => "eq",
        .gt => "lte",
        .gte => "lt",
        .lt => "gte",
        .lte => "gt",
        else => error.UnsupportedSqlShape,
    };
}

fn generatedDdlWriteLiteralListJson(
    writer: *std.Io.Writer,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (range.end <= range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    var list_start = range.start;
    while (list_start < range.end and tokens[list_start].kind != .lparen) : (list_start += 1) {}
    if (list_start >= range.end or tokens[range.end - 1].kind != .rparen) return error.UnsupportedSqlShape;
    const close_index = findMatchingParen(tokens, list_start, range.end) orelse return error.UnsupportedSqlShape;
    if (close_index + 1 != range.end) return error.UnsupportedSqlShape;
    try writer.writeByte('[');
    var index = list_start + 1;
    var count: usize = 0;
    while (index < close_index) {
        if (count > 0) {
            if (tokens[index].kind != .comma) return error.UnsupportedSqlShape;
            index += 1;
            try writer.writeByte(',');
        }
        const literal_start = index;
        if (literal_start >= close_index) return error.UnsupportedSqlShape;
        try generatedDdlWriteLiteralJson(writer, tokens, .{ .start = literal_start, .end = literal_start + 1 });
        index = literal_start + 1;
        count += 1;
    }
    if (count == 0) return error.UnsupportedSqlShape;
    try writer.writeByte(']');
}

fn generatedDdlWriteLiteralJson(
    writer: *std.Io.Writer,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) !void {
    if (range.end != range.start + 1 or range.end > tokens.len) return error.UnsupportedSqlShape;
    const token = tokens[range.start];
    switch (token.kind) {
        .string => try writer.print("{f}", .{std.json.fmt(token.text, .{})}),
        .number => try writer.writeAll(token.text),
        .identifier => {
            if (token.matchesKeywordTag(.true)) try writer.writeAll("true") else if (token.matchesKeywordTag(.false)) try writer.writeAll("false") else if (token.matchesKeywordTag(.null)) try writer.writeAll("null") else return error.UnsupportedSqlShape;
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn generatedDdlArrayConstructorValueJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    expression: generated_parser.GeneratedSqlExpressionAst,
) ![]const u8 {
    if (expression.kind != .array_constructor) return error.UnsupportedSqlShape;
    try expr_generated_validate.validateGeneratedExpressionPayloads(tokens, expression);

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    try generatedDdlWriteArrayConstructorJson(&out.writer, tokens, expression);
    return try out.toOwnedSlice();
}

fn generatedDdlWriteArrayConstructorJson(
    writer: *std.Io.Writer,
    tokens: []const grammar.Token,
    expression: generated_parser.GeneratedSqlExpressionAst,
) anyerror!void {
    const expression_tokens = expression.tokens orelse return error.UnsupportedSqlShape;
    if (expression_tokens.end <= expression_tokens.start + 2 or expression_tokens.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[expression_tokens.start].matchesKeywordTag(.array) or
        tokens[expression_tokens.start + 1].kind != .lbracket or
        tokens[expression_tokens.end - 1].kind != .rbracket)
    {
        return error.UnsupportedSqlShape;
    }

    const array_items = expression.array_items;
    try writer.writeByte('[');
    if (array_items.count == 0) {
        if (expression.array_tokens != null or
            array_items.items.len != 0 or
            array_items.expression_items.len != 0 or
            array_items.expressions.len != 0)
        {
            return error.UnsupportedSqlShape;
        }
    } else {
        const array_tokens = expression.array_tokens orelse return error.UnsupportedSqlShape;
        if (array_tokens.start != expression_tokens.start + 2 or array_tokens.end != expression_tokens.end - 1) return error.UnsupportedSqlShape;
        if (array_items.items.len != array_items.count or
            array_items.expression_items.len != array_items.count or
            array_items.expressions.len != array_items.count)
        {
            return error.UnsupportedSqlShape;
        }
        for (array_items.items, array_items.expression_items, array_items.expressions, 0..) |item, expression_item, item_expression, index| {
            const item_tokens = item_expression.tokens orelse return error.UnsupportedSqlShape;
            if (!generatedDdlTokenRangeEqual(item, expression_item) or !generatedDdlTokenRangeEqual(item, item_tokens)) return error.UnsupportedSqlShape;
            if (item.start < array_tokens.start or item.end > array_tokens.end or item.start >= item.end) return error.UnsupportedSqlShape;
            if (index > 0) {
                const previous = array_items.items[index - 1];
                if (previous.end + 1 != item.start or previous.end >= tokens.len or tokens[previous.end].kind != .comma) return error.UnsupportedSqlShape;
                try writer.writeByte(',');
            }
            try generatedDdlWriteDefaultExpressionJson(writer, tokens, item_expression);
        }
    }
    try writer.writeByte(']');
}

fn generatedDdlWriteDefaultExpressionJson(
    writer: *std.Io.Writer,
    tokens: []const grammar.Token,
    expression: generated_parser.GeneratedSqlExpressionAst,
) anyerror!void {
    switch (expression.kind) {
        .token_range => try generatedDdlWriteLiteralJson(writer, tokens, expression.tokens orelse return error.UnsupportedSqlShape),
        .unary_negative => {
            const operator_tokens = expression.operator_tokens orelse return error.UnsupportedSqlShape;
            if (operator_tokens.end != operator_tokens.start + 1 or operator_tokens.end > tokens.len or tokens[operator_tokens.start].kind != .minus) return error.UnsupportedSqlShape;
            const right = expression.right_expression orelse return error.UnsupportedSqlShape;
            const right_tokens = right.tokens orelse return error.UnsupportedSqlShape;
            if (right.kind != .token_range or right_tokens.start != operator_tokens.end or right_tokens.end != operator_tokens.end + 1 or right_tokens.end > tokens.len) return error.UnsupportedSqlShape;
            if (tokens[right_tokens.start].kind != .number) return error.UnsupportedSqlShape;
            try writer.writeByte('-');
            try writer.writeAll(tokens[right_tokens.start].text);
        },
        .array_constructor => try generatedDdlWriteArrayConstructorJson(writer, tokens, expression),
        else => return error.UnsupportedSqlShape,
    }
}

fn generatedDdlParsePaginationNullableU32(
    tokens: []const grammar.Token,
    expression: generated_parser.GeneratedSqlExpressionAst,
    expected_range: generated_parser.GeneratedSqlTokenRange,
) !?u32 {
    const expression_tokens = expression.tokens orelse return error.UnsupportedSqlShape;
    if (!generatedDdlTokenRangeEqual(expression_tokens, expected_range)) return error.UnsupportedSqlShape;
    switch (expression.kind) {
        .token_range => {
            var pos = expected_range.start;
            const value = try value_mod.parseNullableSqlU32Value(tokens, &pos, &.{});
            if (pos != expected_range.end) return error.UnsupportedSqlShape;
            return value;
        },
        .unary_positive => {
            const operator_tokens = expression.operator_tokens orelse return error.UnsupportedSqlShape;
            if (operator_tokens.start != expected_range.start or operator_tokens.end != expected_range.start + 1) return error.UnsupportedSqlShape;
            if (tokens[operator_tokens.start].kind != .plus) return error.UnsupportedSqlShape;
            const value_range = expression.right_tokens orelse return error.UnsupportedSqlShape;
            if (value_range.start != operator_tokens.end or value_range.end != expected_range.end) return error.UnsupportedSqlShape;
            const right_expression = expression.right_expression orelse return error.UnsupportedSqlShape;
            if (right_expression.kind != .token_range or !generatedDdlTokenRangeEqual(right_expression.tokens orelse return error.UnsupportedSqlShape, value_range)) return error.UnsupportedSqlShape;
            var pos = value_range.start;
            const value = try value_mod.parseNullableSqlU32Value(tokens, &pos, &.{});
            if (pos != value_range.end) return error.UnsupportedSqlShape;
            return value;
        },
        else => return error.UnsupportedSqlShape,
    }
}

fn generatedDdlSingleTokenText(tokens: []const grammar.Token, range: generated_parser.GeneratedSqlTokenRange) []const u8 {
    if (range.end != range.start + 1 or range.end > tokens.len) return "";
    return tokens[range.start].text;
}

fn generatedDdlTokenRangeEqual(a: generated_parser.GeneratedSqlTokenRange, b: generated_parser.GeneratedSqlTokenRange) bool {
    return a.start == b.start and a.end == b.end;
}

fn generatedTokenSliceOffset(full_tokens: []const grammar.Token, sliced_tokens: []const grammar.Token) ?usize {
    if (sliced_tokens.len == 0) return 0;
    if (full_tokens.len == 0) return null;
    const full_start = @intFromPtr(full_tokens.ptr);
    const sliced_start = @intFromPtr(sliced_tokens.ptr);
    if (sliced_start < full_start) return null;
    const byte_offset = sliced_start - full_start;
    if (byte_offset % @sizeOf(grammar.Token) != 0) return null;
    const offset = byte_offset / @sizeOf(grammar.Token);
    if (offset + sliced_tokens.len > full_tokens.len) return null;
    return offset;
}

fn generatedScalarSubqueryDefaultForRange(
    items: []const generated_parser.GeneratedSqlDdlScalarSubqueryDefaultAst,
    default_tokens: generated_parser.GeneratedSqlTokenRange,
) ?generated_parser.GeneratedSqlDdlScalarSubqueryDefaultAst {
    for (items) |item| {
        if (item.default_tokens.start == default_tokens.start and item.default_tokens.end == default_tokens.end) return item;
    }
    return null;
}

fn parseDdlDefaultValueAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    field_type: runtime_schema.AntflyType,
    options: DdlExpressionOptions,
) !runtime_schema.RelationalDefaultValue {
    const full_tokens = options.generated_default_value_full_tokens orelse return error.UnsupportedSqlShape;
    const default_range = options.generated_default_value_tokens orelse return error.UnsupportedSqlShape;
    const expected_start = options.generated_default_value_token_offset + pos.*;
    if (default_range.start != expected_start or default_range.end > full_tokens.len or default_range.end <= default_range.start) return error.UnsupportedSqlShape;
    if (default_range.start < options.generated_default_value_token_offset) return error.UnsupportedSqlShape;
    try validateGeneratedDdlDefaultValueAst(options, full_tokens, default_range);
    const local_end = default_range.end - options.generated_default_value_token_offset;
    if (local_end > tokens.len or local_end <= pos.*) return error.UnsupportedSqlShape;
    const retained_expression = options.generated_default_value_ast orelse return error.UnsupportedSqlShape;
    if (retained_expression.kind == .array_constructor) {
        if (field_type != .array) return error.InvalidSqlCatalog;
        const value_json = try generatedDdlArrayConstructorValueJsonAlloc(alloc, full_tokens, retained_expression.*);
        pos.* = local_end;
        return .{ .kind = .literal, .value_json = value_json };
    }
    const value_tokens = tokens[pos.*..local_end];
    var value_pos: usize = 0;
    const value = try parseDdlDefaultValueWithParamsAlloc(
        alloc,
        value_tokens,
        &value_pos,
        field_type,
        options.params,
        options.realtime_ns,
        options.generated_scalar_subquery_defaults,
        options.generated_scalar_subquery_full_tokens orelse full_tokens,
        default_range.start,
    );
    if (value_pos != value_tokens.len) {
        alloc.free(value.value_json);
        return error.UnsupportedSqlShape;
    }
    pos.* = local_end;
    return value;
}

fn parseDdlRowExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
    require_routine_expression_binding: bool,
) !db_mod.types.RelationalRowsExpression {
    return try expr_row_parse.parseRowExpressionWithDeferredFieldValidationAlloc(
        alloc,
        tokens,
        pos,
        .{
            .function_bindings = options.function_bindings,
            .require_routine_expression_binding = require_routine_expression_binding,
            .context_hooks = options.context_hooks,
            .row_expression_hooks = options.row_expression_hooks,
            .arithmetic_hooks = options.arithmetic_hooks,
            .variadic_hooks = options.variadic_hooks,
        },
    );
}

fn parseDdlRoutineRowExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    options: DdlExpressionOptions,
) !db_mod.types.RelationalRowsExpression {
    if (!expr_row_parse.peekRoutineExpressionCall(tokens, pos.*, options.function_bindings.routine_expressions)) return error.UnsupportedSqlShape;
    const name = tokens[pos.*].text;
    _ = parser.matchToken(tokens, pos, .identifier) orelse return error.UnsupportedSqlShape;
    try parser.expectToken(tokens, pos, .lparen);
    var operands = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
    defer {
        for (operands.items) |operand| runtime_schema.freeRelationalRowsExpression(alloc, operand);
        operands.deinit(alloc);
    }
    if (parser.matchToken(tokens, pos, .rparen) == null) {
        while (true) {
            const arg_start = pos.*;
            const arg_end = ddlRoutineArgumentEnd(tokens, arg_start) orelse return error.UnsupportedSqlShape;
            const operand = try parseDdlRoutineArgumentExpressionAlloc(alloc, tokens[arg_start..arg_end], options);
            var operand_transferred = false;
            errdefer if (!operand_transferred) runtime_schema.freeRelationalRowsExpression(alloc, operand);
            try operands.append(alloc, operand);
            operand_transferred = true;
            pos.* = arg_end;
            if (parser.matchToken(tokens, pos, .comma) != null) continue;
            break;
        }
        try parser.expectToken(tokens, pos, .rparen);
    }
    const binding = try expr_row_parse.routineExpressionBinding(options.function_bindings.routine_expressions, name, operands.items.len) orelse return error.UnsupportedSqlShape;
