    errdefer if (!rhs_transferred and rhs.len > 0) {
        for (rhs) |item| runtime_schema.freeRelationalRowsExpression(alloc, item);
        alloc.free(rhs);
    };

    lhs_transferred = true;
    rhs_transferred = true;
    return .{
        .lhs = lhs,
        .op = op,
        .rhs = rhs,
    };
}

