    if (table_name.end >= end) return error.UnsupportedSqlShape;
    const operation = ast.alter_table_operation_tokens orelse return error.UnsupportedSqlShape;
    if (operation.start != table_name.end or operation.end != end or operation.start >= operation.end) return error.UnsupportedSqlShape;
    try validateGeneratedUnsupportedAlterTableOperationSubject(tokens, end, ast, operation);
}

fn validateGeneratedUnsupportedAlterTableOperationSubject(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlUnsupportedAst,
    operation: generated_parser.GeneratedSqlTokenRange,
) !void {
    const start = operation.start;
    const operation_end = operation.end;
    if (operation_end > end or start >= operation_end) return error.UnsupportedSqlShape;
    switch (ast.kind) {
        .alter_table_access_method => {
            if (operation_end != start + 4 or
                !tokens[start].matchesKeywordTag(.set) or
                !tokens[start + 1].matchesKeywordTag(.access) or
                !tokens[start + 2].matchesKeywordTag(.method))
            {
                return error.UnsupportedSqlShape;
            }
            try validateGeneratedUnsupportedAlterTableSubjectAt(tokens, end, ast, start + 3);
        },
        .alter_table_cluster => {
            if (operation_end == start + 3 and
                tokens[start].matchesKeywordTag(.cluster) and
                tokens[start + 1].matchesKeywordTag(.on))
            {
                try validateGeneratedUnsupportedAlterTableSubjectAt(tokens, end, ast, start + 2);
                return;
            }
            if (operation_end == start + 3 and
                tokens[start].matchesKeywordTag(.set) and
                tokens[start + 1].matchesKeywordTag(.without) and
                tokens[start + 2].matchesKeywordTag(.cluster) and
                ast.alter_table_operation_subject_tokens == null)
            {
                return;
            }
            return error.UnsupportedSqlShape;
        },
        .alter_table_column_statistics => {
            if (ast.alter_table_operation_subject_tokens != null) return error.UnsupportedSqlShape;
            if (!generatedDdlUnsupportedAlterTableColumnStatisticsOperationIsValid(tokens, operation)) return error.UnsupportedSqlShape;
        },
        .alter_table_column_storage => {
            if (ast.alter_table_operation_subject_tokens != null) return error.UnsupportedSqlShape;
            if (!generatedDdlUnsupportedAlterTableColumnStorageOperationIsValid(tokens, operation)) return error.UnsupportedSqlShape;
        },
        .alter_table_inheritance => {
            if (operation_end == start + 2 and tokens[start].matchesKeyword("inherit")) {
                try validateGeneratedUnsupportedAlterTableSubjectAt(tokens, end, ast, start + 1);
                return;
            }
            if (operation_end == start + 3 and tokens[start].matchesKeywordTag(.no) and tokens[start + 1].matchesKeyword("inherit")) {
                try validateGeneratedUnsupportedAlterTableSubjectAt(tokens, end, ast, start + 2);
                return;
            }
            return error.UnsupportedSqlShape;
        },
        .alter_table_owner => {
            if (operation_end != start + 3 or !tokens[start].matchesKeyword("owner") or !tokens[start + 1].matchesKeywordTag(.to)) return error.UnsupportedSqlShape;
            try validateGeneratedUnsupportedAlterTableSubjectAt(tokens, end, ast, start + 2);
        },
        .alter_table_set_schema => {
            if (operation_end != start + 3 or !tokens[start].matchesKeywordTag(.set) or !tokens[start + 1].matchesKeywordTag(.schema)) return error.UnsupportedSqlShape;
            try validateGeneratedUnsupportedAlterTableSubjectAt(tokens, end, ast, start + 2);
        },
        .alter_table_tablespace => {
            if (operation_end != start + 3 or !tokens[start].matchesKeywordTag(.set) or !tokens[start + 1].matchesKeywordTag(.tablespace)) return error.UnsupportedSqlShape;
            try validateGeneratedUnsupportedAlterTableSubjectAt(tokens, end, ast, start + 2);
        },
        else => {
            if (ast.alter_table_operation_subject_tokens != null) return error.UnsupportedSqlShape;
        },
    }
}

fn generatedDdlUnsupportedAlterTableColumnStatisticsOperationIsValid(
    tokens: []const grammar.Token,
    operation: generated_parser.GeneratedSqlTokenRange,
) bool {
    var index = operation.start;
    if (operation.end > tokens.len or index >= operation.end) return false;
    if (!tokens[index].matchesKeywordTag(.alter)) return false;
    index += 1;
    if (index < operation.end and tokens[index].matchesKeywordTag(.column)) index += 1;
    if (index >= operation.end or tokens[index].kind != .identifier) return false;
    index += 1;
    return index + 3 == operation.end and
        tokens[index].matchesKeywordTag(.set) and
        tokens[index + 1].matchesKeyword("statistics") and
        tokens[index + 2].kind == .number;
}

fn generatedDdlUnsupportedAlterTableColumnStorageOperationIsValid(
    tokens: []const grammar.Token,
    operation: generated_parser.GeneratedSqlTokenRange,
) bool {
    var index = operation.start;
    if (operation.end > tokens.len or index >= operation.end) return false;
    if (!tokens[index].matchesKeywordTag(.alter)) return false;
    index += 1;
    if (index < operation.end and tokens[index].matchesKeywordTag(.column)) index += 1;
    if (index >= operation.end or tokens[index].kind != .identifier) return false;
    index += 1;
    return index + 3 == operation.end and
        tokens[index].matchesKeywordTag(.set) and
        tokens[index + 1].matchesKeyword("storage") and
        generatedDdlUnsupportedAlterTableColumnStorageModeIsValid(tokens[index + 2]);
}

fn generatedDdlUnsupportedAlterTableColumnStorageModeIsValid(token: grammar.Token) bool {
    return token.matchesKeywordTag(.default) or
        token.matchesKeyword("plain") or
        token.matchesKeyword("external") or
        token.matchesKeyword("extended") or
        token.matchesKeyword("main");
}

fn validateGeneratedUnsupportedAlterTableSubjectAt(
    tokens: []const grammar.Token,
    end: usize,
    ast: generated_parser.GeneratedSqlUnsupportedAst,
    index: usize,
) !void {
    const subject = ast.alter_table_operation_subject_tokens orelse return error.UnsupportedSqlShape;
    try validateGeneratedSingleIdentifierRangeAt(tokens, end, subject, index);
}

fn generatedUnsupportedCatalogAlterTableOperationKind(kind: generated_parser.GeneratedSqlUnsupportedKind) bool {
    return switch (kind) {
        .alter_table_access_method,
        .alter_table_cluster,
        .alter_table_column_statistics,
        .alter_table_column_storage,
        .alter_table_inheritance,
        .alter_table_owner,
        .alter_table_persistence,
        .alter_table_replica_identity,
        .alter_table_set_schema,
        .alter_table_storage_parameters,
        .alter_table_tablespace,
        .alter_table_trigger_state,
        => true,
        else => false,
    };
}

fn generatedUnsupportedCatalogSubjectRange(
    tokens: []const grammar.Token,
    boundary: GeneratedUnsupportedCatalogBoundary,
    end: usize,
) ?generated_parser.GeneratedSqlTokenRange {
    const start: usize = switch (boundary.family) {
        .update_policy_trigger => switch (boundary.kind) {
            .alter_trigger => 2,
            .create_trigger => if (end > 3 and
                tokens[1].matchesKeyword("or") and
                tokens[2].matchesKeyword("replace") and
                tokens[3].matchesKeyword("trigger"))
                4
            else
                2,
            .drop_trigger => 2,
            else => return null,
        },
        else => 1,
    };
    return if (end > start) .{ .start = start, .end = end } else null;
}

fn catalogDdlPlanFromGeneratedUnsupportedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    pos: *usize,
    ast: generated_parser.GeneratedSqlUnsupportedAst,
    boundary: GeneratedUnsupportedCatalogBoundary,
    options: DdlPlanParserOptions,
) !DdlPlan {
    try validateGeneratedUnsupportedCatalogAst(tokens, ast, boundary);
    if (boundary.family == .maintenance) {
        switch (boundary.kind) {
            .vacuum => {
                pos.* = tokens.len;
                return .{ .maintenance_job = .{ .vacuum = try vacuumMaintenancePlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast) } };
            },
            .analyze => {
                pos.* = tokens.len;
                return .{ .maintenance_job = .{ .analyze = try analyzeMaintenancePlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast) } };
            },
            .reindex => {
                pos.* = tokens.len;
                return .{ .maintenance_job = .{ .reindex = try reindexMaintenancePlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast) } };
            },
            .cluster => {
                pos.* = tokens.len;
                return .{ .maintenance_job = .{ .cluster = try clusterMaintenancePlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast) } };
            },
            else => {},
        }
    }
    if (boundary.family == .notification) {
        pos.* = tokens.len;
        return .{ .notification_channel = try notificationChannelPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast, boundary) };
    }
    if (boundary.family == .procedure_call) {
        pos.* = tokens.len;
        return .{ .procedure_call = try procedureCallPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast) };
    }
    if (boundary.family == .authorization) {
        pos.* = tokens.len;
        return .{ .authorization_catalog = try authorizationCatalogPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast, boundary) };
    }
    if (boundary.family == .bulk_io) {
        pos.* = tokens.len;
        return .{ .bulk_io = try bulkIoPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast, options) };
    }
    if (boundary.family == .comment) {
        pos.* = tokens.len;
        return .{ .comment_metadata = try commentMetadataPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast) };
    }
    if (boundary.family == .transaction_control) {
        pos.* = tokens.len;
        return .{ .transaction_control = try transactionControlPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast, boundary) };
    }
    if (boundary.family == .unsupported_alter_table or boundary.family == .unsupported_routine) {
        return error.UnsupportedSqlShape;
    }
    if (boundary.family == .update_policy_trigger) {
        pos.* = tokens.len;
        return try triggerPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, ast, boundary);
    }
    return error.UnsupportedSqlShape;
}

