fn clusterMaintenancePlanFromGeneratedUnsupportedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    ast: generated_parser.GeneratedSqlUnsupportedAst,
) !ClusterMaintenancePlan {
    if (ast.kind != .cluster) return error.UnsupportedSqlShape;
    if (ast.maintenance_reindex_target != null or ast.maintenance_concurrently) return error.UnsupportedSqlShape;
    const table_name = try generatedMaintenanceObjectNameFromRangeAlloc(alloc, tokens, ast.maintenance_name_tokens orelse return error.UnsupportedSqlShape);
    errdefer alloc.free(table_name);
    var index_name: ?[]const u8 = null;
    errdefer if (index_name) |name| alloc.free(name);
    if (ast.maintenance_secondary_name_tokens) |range| {
        index_name = try generatedMaintenanceObjectNameFromRangeAlloc(alloc, tokens, range);
    }
    const plan = ClusterMaintenancePlan{
        .table_name = table_name,
        .index_name = index_name,
        .verbose = ast.maintenance_verbose,
    };
    index_name = null;
    return plan;
}

fn generatedMaintenanceObjectNameFromRangeAlloc(
    alloc: std.mem.Allocator,
    tokens: []const grammar.Token,
    range: generated_parser.GeneratedSqlTokenRange,
) ![]const u8 {
    if (range.end != range.start + 1 or range.end > tokens.len or tokens[range.start].kind != .identifier) return error.UnsupportedSqlShape;
    return try grammar.normalizeSqlObjectIdentifierAlloc(alloc, tokens[range.start].text);
}

fn reindexMaintenanceTargetFromGenerated(target: generated_parser.GeneratedSqlReindexTarget) !ReindexMaintenanceTarget {
    return switch (target) {
        .index => .index,
        .table => .table,
        .schema => .schema,
        .database => .database,
        .system => .system,
    };
}

fn runtimeDdlPlanAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
) !DdlPlan {
    return try runtimeDdlPlanWithFunctionBindingsAlloc(alloc, sql, .{});
}

fn runtimeDdlPlanWithFunctionBindingsAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    function_bindings: expr_row_parse.SqlFunctionBindings,
) !DdlPlan {
    var parsed_sql = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed_sql.deinit(alloc);

    return try runtimeDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed_sql, function_bindings);
}

fn runtimeDdlPlanParsedSqlAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
) !DdlPlan {
    return try runtimeDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, parsed_sql, .{});
}

pub fn logicalDdlPlanParsedSqlWithFunctionBindingsAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    function_bindings: expr_row_parse.SqlFunctionBindings,
) !binder.LogicalSqlPlan {
    switch (parsed_sql.statement) {
        .unsupported => return error.UnsupportedSqlShape,
        else => {},
    }
    const tokens = parsed_sql.items();
    var state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .function_bindings = function_bindings,
    };
    const options = DdlPlanParserOptions{
        .schema = state.schema,
        .field_expression_qualifiers = state.field_expression_qualifiers,
        .returning_expression_qualifiers = state.returning_expression_qualifiers,
        .defer_row_expression_field_validation = state.defer_row_expression_field_validation,
        .column_definition_options = makeDdlColumnDefinitionOptions(&state),
        .domain_options = parser_context.ParserState.ContextAccessors.ddlDomainOptions(&state),
        .create_index_options = parser_context.ParserState.ContextAccessors.createIndexOptions(&state),
        .row_security_policy_options = parser_context.ParserState.ContextAccessors.rowSecurityPolicyOptions(&state),
    };
    if (parsed_sql.generated_statement) |generated_statement| {
        const generated_ast = try generatedAstOrUnsupported(generated_statement);
        return try planGeneratedLogicalDdlAstAlloc(alloc, parsed_sql, tokens, &state, generated_statement, generated_ast, options);
    }
    return error.UnsupportedSqlShape;
}

fn generatedAstOrUnsupported(generated_statement: tokenized.GeneratedRawSqlStatement) !generated_parser.GeneratedSqlAst {
    return generated_statement.ast orelse error.UnsupportedSqlShape;
}

pub fn planGeneratedLogicalDdlAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    tokens: []const grammar.Token,
    state: *parser_context.ParserState,
    generated_statement: tokenized.GeneratedRawSqlStatement,
    generated_ast: generated_parser.GeneratedSqlAst,
    options: DdlPlanParserOptions,
) !binder.LogicalSqlPlan {
    switch (generated_ast) {
        .session => |session_ast| return try sessionLogicalPlanFromGeneratedAstAlloc(alloc, tokens, session_ast),
        .prepared => |prepared_ast| return .{ .prepared_statement = try preparedStatementPlanFromGeneratedAstAlloc(alloc, parsed_sql, prepared_ast) },
        .prepared_transaction => |prepared_transaction_ast| return .{ .transaction = .{ .prepared = try preparedTransactionPlanFromGeneratedAstAlloc(alloc, tokens, prepared_transaction_ast) } },
        .transaction => |transaction_ast| return .{ .transaction = try transactionLogicalPlanFromGeneratedAstAlloc(alloc, tokens, transaction_ast) },
        .cursor => |cursor_ast| return .{ .cursor = try cursorPortalLogicalPlanFromGeneratedAstAlloc(alloc, tokens, cursor_ast) },
        .ddl, .extension_index => |ddl_ast| {
            if (generatedDdlUsesRuntimeBoundary(tokens, ddl_ast)) {
                return try logicalDdlPlanFromGeneratedAstAlloc(alloc, tokens, ddl_ast, options);
            }
        },
        .graph => |graph_ast| return try graphLogicalDdlPlanFromGeneratedAstAlloc(alloc, tokens, graph_ast),
        .unsupported => |unsupported_ast| {
            if (generatedUnsupportedCatalogBoundary(generated_statement.statement)) |boundary| {
                var generated_catalog_plan = try catalogDdlPlanFromGeneratedUnsupportedAstAlloc(
                    alloc,
                    tokens,
                    &state.pos,
                    unsupported_ast,
                    boundary,
                    options,
                );
                errdefer generated_catalog_plan.deinit(alloc);
                return try logicalPlanFromDdlPlan(&generated_catalog_plan);
            }
        },
        .read => |read_ast| {
            if (try advisoryLockPlanFromGeneratedReadAst(tokens, read_ast)) |advisory_lock| {
                return .{ .transaction = .{ .control = .{ .advisory_lock = advisory_lock } } };
            }
            return error.UnsupportedSqlShape;
        },
        .dml => return error.UnsupportedSqlShape,
    }
    return error.UnsupportedSqlShape;
}

pub fn lowerRoutineTriggerCatalogPlanParsedSqlAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
) !TriggerCatalogPlan {
    const generated_statement = parsed_sql.generated_statement orelse return error.UnsupportedSqlShape;
    const generated_ast = try generatedAstOrUnsupported(generated_statement);
    const unsupported = switch (generated_ast) {
        .unsupported => |unsupported| unsupported,
        else => return error.NotTriggerDdl,
    };
    const boundary = generatedUnsupportedCatalogBoundary(generated_statement.statement) orelse return error.NotTriggerDdl;
    if (boundary.family != .update_policy_trigger) return error.NotTriggerDdl;
    try validateGeneratedUnsupportedCatalogAst(parsed_sql.items(), unsupported, boundary);
    switch (boundary.kind) {
        .create_trigger => {
            const tokens = parsed_sql.items();
            const replace_existing = tokens.len > 3 and
                tokens[1].matchesKeywordTag(.@"or") and
                tokens[2].matchesKeywordTag(.replace) and
                tokens[3].matchesKeywordTag(.trigger);
            var fields = try generatedCreateTriggerFieldsFromUnsupportedAstAlloc(alloc, tokens, unsupported);
            defer fields.deinit(alloc);
            if (fields.argument_value != null) return error.UnsupportedSqlShape;
            return .{ .create = try createRoutineTriggerPlanFromGeneratedFieldsAlloc(alloc, fields, replace_existing) };
        },
        .drop_trigger => {
            var fields = try generatedDropTriggerFieldsFromUnsupportedAstAlloc(alloc, parsed_sql.items(), unsupported);
            defer fields.deinit(alloc);
            return .{ .drop = try dropRoutineTriggerPlanFromGeneratedFieldsAlloc(alloc, fields) };
        },
        else => return error.NotTriggerDdl,
    }
}

fn runtimeDdlPlanParsedSqlWithFunctionBindingsAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    function_bindings: expr_row_parse.SqlFunctionBindings,
) !DdlPlan {
    switch (parsed_sql.statement) {
        .unsupported => return error.UnsupportedSqlShape,
        else => {},
    }
    const tokens = parsed_sql.items();
    var state = parser_context.ParserState{
        .alloc = alloc,
        .tokens = tokens,
        .function_bindings = function_bindings,
    };
    const options = DdlPlanParserOptions{
        .schema = state.schema,
        .field_expression_qualifiers = state.field_expression_qualifiers,
        .returning_expression_qualifiers = state.returning_expression_qualifiers,
        .defer_row_expression_field_validation = state.defer_row_expression_field_validation,
        .column_definition_options = makeDdlColumnDefinitionOptions(&state),
        .domain_options = parser_context.ParserState.ContextAccessors.ddlDomainOptions(&state),
        .create_index_options = parser_context.ParserState.ContextAccessors.createIndexOptions(&state),
        .row_security_policy_options = parser_context.ParserState.ContextAccessors.rowSecurityPolicyOptions(&state),
    };
    if (parsed_sql.generated_statement) |generated_statement| {
        const generated_ast = try generatedAstOrUnsupported(generated_statement);
        return try runtimeDdlPlanFromGeneratedStatementAstAlloc(alloc, parsed_sql, tokens, &state, generated_statement, generated_ast, options);
    }
    return error.UnsupportedSqlShape;
}

fn runtimeDdlPlanFromGeneratedStatementAstAlloc(
    alloc: std.mem.Allocator,
    parsed_sql: *const tokenized.ParsedSql,
    tokens: []const grammar.Token,
    state: *parser_context.ParserState,
    generated_statement: tokenized.GeneratedRawSqlStatement,
    generated_ast: generated_parser.GeneratedSqlAst,
    options: DdlPlanParserOptions,
) !DdlPlan {
    switch (generated_ast) {
        .session => |session_ast| return try sessionDdlPlanFromGeneratedAstAlloc(alloc, tokens, session_ast),
        .prepared => |prepared_ast| return .{ .prepared_statement = try preparedStatementPlanFromGeneratedAstAlloc(alloc, parsed_sql, prepared_ast) },
        .prepared_transaction => |prepared_transaction_ast| return .{ .prepared_transaction = try preparedTransactionPlanFromGeneratedAstAlloc(alloc, tokens, prepared_transaction_ast) },
        .transaction => |transaction_ast| return try transactionControlPlanFromGeneratedAstAlloc(alloc, tokens, transaction_ast),
        .cursor => |cursor_ast| return try cursorPortalPlanFromGeneratedAstAlloc(alloc, tokens, cursor_ast),
        .ddl, .extension_index => |ddl_ast| {
            if (generatedDdlUsesRuntimeBoundary(tokens, ddl_ast)) {
                return try runtimeDdlPlanFromGeneratedAstAlloc(alloc, tokens, ddl_ast, options);
            }
        },
        .graph => |graph_ast| return try graphDdlPlanFromGeneratedAstAlloc(alloc, tokens, graph_ast),
        .unsupported => |unsupported_ast| {
            if (generatedUnsupportedCatalogBoundary(generated_statement.statement)) |boundary| {
                return catalogDdlPlanFromGeneratedUnsupportedAstAlloc(alloc, tokens, &state.pos, unsupported_ast, boundary, options) catch |err| switch (err) {
                    error.UnsupportedSqlShape => return err,
                    else => return err,
                };
            }
        },
        .read => |read_ast| {
            if (try advisoryLockPlanFromGeneratedReadAst(tokens, read_ast)) |advisory_lock| {
                return .{ .transaction_control = .{ .advisory_lock = advisory_lock } };
            }
            return error.UnsupportedSqlShape;
        },
        .dml => return error.UnsupportedSqlShape,
    }
    return error.UnsupportedSqlShape;
}

const runtimeDdlPlanForTestAlloc = runtimeDdlPlanAlloc;
const runtimeDdlPlanWithFunctionBindingsForTestAlloc = runtimeDdlPlanWithFunctionBindingsAlloc;

test "sql adapter ddl plan lowers create table ddl into typed schema plan" {
    const alloc = std.testing.allocator;
    var lowered = try runtimeDdlPlanForTestAlloc(
        alloc,
        \\CREATE TABLE IF NOT EXISTS usage_records (
        \\  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
        \\  tenant_id text NOT NULL,
        \\  amount numeric(18, 2) DEFAULT 0 CHECK (amount >= 0),
        \\  metadata jsonb,
        \\  tags text[] COLLATE "C",
        \\  created_at timestamptz DEFAULT now(),
        \\  email_key text GENERATED ALWAYS AS (lower(tenant_id)) STORED,
        \\  CONSTRAINT usage_records_tenant_key UNIQUE (tenant_id),
        \\  CONSTRAINT usage_records_tenant_fkey FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
        \\);
        ,
    );
    defer lowered.deinit(alloc);

    switch (lowered) {
