            else => return error.TestUnexpectedResult,
        }
    }

    var advisory_lock = try runtimeDdlPlanForTestAlloc(alloc, "SELECT pg_advisory_lock(42);");
    defer advisory_lock.deinit(alloc);
    switch (advisory_lock) {
