            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed, .{}));
}

