const GeneratedPreparedTransactionMetadataMutation = enum {
    malformed_gid,
    stale_kind,
};

fn expectGeneratedPreparedTransactionMetadataMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    mutation: GeneratedPreparedTransactionMetadataMutation,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    if (parsed.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .prepared_transaction => |*prepared_transaction| switch (mutation) {
                .malformed_gid => prepared_transaction.gid_tokens = .{ .start = 1, .end = 2 },
                .stale_kind => prepared_transaction.kind = .rollback,
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlAlloc(alloc, &parsed));
}

test "sql adapter ddl plan lowers prepared transaction ddl plans" {
    const alloc = std.testing.allocator;

    var prepare = try runtimeDdlPlanForTestAlloc(alloc, "PREPARE TRANSACTION 'usage_batch';");
    defer prepare.deinit(alloc);
    switch (prepare) {
        .prepared_transaction => |plan| {
            try std.testing.expectEqual(PreparedTransactionAction.prepare, plan.action);
            try std.testing.expectEqualStrings("usage_batch", plan.gid);
        },
        else => return error.TestUnexpectedResult,
    }

    var commit = try runtimeDdlPlanForTestAlloc(alloc, "COMMIT PREPARED 'usage_batch';");
    defer commit.deinit(alloc);
    switch (commit) {
        .prepared_transaction => |plan| {
            try std.testing.expectEqual(PreparedTransactionAction.commit, plan.action);
            try std.testing.expectEqualStrings("usage_batch", plan.gid);
        },
        else => return error.TestUnexpectedResult,
    }

    var rollback = try runtimeDdlPlanForTestAlloc(alloc, "ROLLBACK PREPARED 'usage_batch';");
    defer rollback.deinit(alloc);
    switch (rollback) {
        .prepared_transaction => |plan| {
            try std.testing.expectEqual(PreparedTransactionAction.rollback, plan.action);
            try std.testing.expectEqualStrings("usage_batch", plan.gid);
        },
        else => return error.TestUnexpectedResult,
    }

    var generated_prepare = try tokenized.ParsedSql.initAlloc(alloc, "PREPARE TRANSACTION 'usage_batch';");
    defer generated_prepare.deinit(alloc);
    var generated_prepare_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &generated_prepare);
    defer generated_prepare_plan.deinit(alloc);
    switch (generated_prepare_plan) {
        .prepared_transaction => |plan| {
            try std.testing.expectEqual(PreparedTransactionAction.prepare, plan.action);
            try std.testing.expectEqualStrings("usage_batch", plan.gid);
        },
        else => return error.TestUnexpectedResult,
    }

    var generated_commit = try tokenized.ParsedSql.initAlloc(alloc, "COMMIT PREPARED 'usage_batch';");
    defer generated_commit.deinit(alloc);
    var generated_commit_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &generated_commit);
    defer generated_commit_plan.deinit(alloc);
    switch (generated_commit_plan) {
        .prepared_transaction => |plan| {
            try std.testing.expectEqual(PreparedTransactionAction.commit, plan.action);
            try std.testing.expectEqualStrings("usage_batch", plan.gid);
        },
        else => return error.TestUnexpectedResult,
    }

    try expectGeneratedPreparedTransactionMetadataMutationFails(alloc, "COMMIT PREPARED 'usage_batch';", .malformed_gid);
    try expectGeneratedPreparedTransactionMetadataMutationFails(alloc, "COMMIT PREPARED 'usage_batch';", .stale_kind);
}

test "sql adapter ddl plan lowers prepared statement cursor and savepoint ddl plans" {
    const alloc = std.testing.allocator;

    var prepare_statement = try runtimeDdlPlanForTestAlloc(alloc, "PREPARE usage_plan(text) AS SELECT id FROM usage_records WHERE status = $1;");
    defer prepare_statement.deinit(alloc);
    switch (prepare_statement) {
        .prepared_statement => |plan| switch (plan) {
            .prepare => |prepare| {
                try std.testing.expectEqualStrings("usage_plan", prepare.statement_name);
                try std.testing.expectEqual(@as(usize, 1), prepare.parameter_count);
                try std.testing.expectEqual(PreparedStatementSubjectKind.read, prepare.statement_kind);
                try std.testing.expectEqual(PreparedStatementStatementKind.read, prepare.statement_family);
                const subject = prepare.subject_parsed_sql orelse return error.TestUnexpectedResult;
                try std.testing.expect(std.mem.indexOf(u8, subject.sql(), "SELECT id FROM usage_records") != null);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    const prepared_cases = [_]struct {
        sql: []const u8,
        family: PreparedStatementStatementKind,
    }{
        .{ .sql = "PREPARE merge_plan AS MERGE INTO usage_records USING source_records ON usage_records.id = source_records.id WHEN MATCHED THEN UPDATE SET status = source_records.status;", .family = .merge },
        .{ .sql = "PREPARE cte_write_plan AS WITH source_rows AS (SELECT id FROM usage_records) UPDATE usage_records SET status = 'done' WHERE id IN (SELECT id FROM source_rows);", .family = .update },
        .{ .sql = "PREPARE recursive_usage_plan AS WITH RECURSIVE source_rows AS (SELECT id FROM usage_records UNION ALL SELECT child.id FROM usage_records AS child JOIN source_rows AS parent ON child.organization_id = parent.id) UPDATE usage_records SET status = 'done' WHERE id IN (SELECT id FROM source_rows);", .family = .update },
    };
    for (prepared_cases) |case| {
        var lowered = try runtimeDdlPlanForTestAlloc(alloc, case.sql);
        defer lowered.deinit(alloc);
        switch (lowered) {
            .prepared_statement => |plan| switch (plan) {
                .prepare => |prepare| {
                    try std.testing.expectEqual(PreparedStatementSubjectKind.write, prepare.statement_kind);
                    try std.testing.expectEqual(case.family, prepare.statement_family);
                },
                else => return error.TestUnexpectedResult,
            },
            else => return error.TestUnexpectedResult,
        }
    }

    var execute_statement = try runtimeDdlPlanForTestAlloc(alloc, "EXECUTE usage_plan('open');");
    defer execute_statement.deinit(alloc);
    switch (execute_statement) {
        .prepared_statement => |plan| switch (plan) {
            .execute => |execute| {
                try std.testing.expectEqualStrings("usage_plan", execute.statement_name);
                try std.testing.expectEqual(@as(usize, 1), execute.argument_count);
                try std.testing.expectEqual(@as(usize, 1), execute.arguments.len);
                try std.testing.expectEqualStrings("open", execute.arguments[0].string);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var deallocate_statement = try runtimeDdlPlanForTestAlloc(alloc, "DEALLOCATE usage_plan;");
    defer deallocate_statement.deinit(alloc);
    switch (deallocate_statement) {
        .prepared_statement => |plan| switch (plan) {
            .deallocate => |deallocate| try std.testing.expectEqualStrings("usage_plan", deallocate.statement_name orelse return error.TestUnexpectedResult),
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var deallocate_all = try runtimeDdlPlanForTestAlloc(alloc, "DEALLOCATE ALL;");
    defer deallocate_all.deinit(alloc);
    switch (deallocate_all) {
        .prepared_statement => |plan| switch (plan) {
            .deallocate => |deallocate| try std.testing.expect(deallocate.all),
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var declare_cursor = try runtimeDdlPlanForTestAlloc(alloc, "DECLARE usage_cursor CURSOR FOR SELECT id FROM usage_records ORDER BY id;");
    defer declare_cursor.deinit(alloc);
    switch (declare_cursor) {
        .cursor_portal => |plan| switch (plan) {
            .declare => |declare| {
                try std.testing.expectEqualStrings("usage_cursor", declare.portal_name);
                try std.testing.expectEqual(CursorScrollMode.default, declare.scroll);
                try std.testing.expect(!declare.binary);
                try std.testing.expect(!declare.hold);
                try std.testing.expectEqual(PreparedStatementSubjectKind.read, declare.statement_kind);
                const subject = declare.subject_parsed_sql orelse return error.TestUnexpectedResult;
                try std.testing.expect(subject.generatedStatementKind() == .read);
                try std.testing.expectEqual(sql_statement_kind.SqlReadStatementKind.query, subject.readStatementKindIncludingGeneratedAst().?);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var declare_scroll_hold = try runtimeDdlPlanForTestAlloc(alloc, "DECLARE usage_scroll_cursor BINARY SCROLL CURSOR WITH HOLD FOR SELECT id FROM usage_records ORDER BY id;");
    defer declare_scroll_hold.deinit(alloc);
    switch (declare_scroll_hold) {
        .cursor_portal => |plan| switch (plan) {
            .declare => |declare| {
                try std.testing.expectEqualStrings("usage_scroll_cursor", declare.portal_name);
                try std.testing.expectEqual(CursorScrollMode.scroll, declare.scroll);
                try std.testing.expect(declare.binary);
                try std.testing.expect(declare.hold);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var declare_merge = try runtimeDdlPlanForTestAlloc(alloc, "DECLARE merge_cursor CURSOR FOR MERGE INTO usage_records USING source_records ON usage_records.id = source_records.id WHEN MATCHED THEN UPDATE SET status = source_records.status;");
    defer declare_merge.deinit(alloc);
    switch (declare_merge) {
        .cursor_portal => |plan| switch (plan) {
            .declare => |declare| {
                try std.testing.expectEqualStrings("merge_cursor", declare.portal_name);
                try std.testing.expectEqual(PreparedStatementSubjectKind.write, declare.statement_kind);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    const fetch_cases = [_]struct {
        sql: []const u8,
        direction: CursorFetchDirection,
        count: ?i64 = null,
    }{
        .{ .sql = "FETCH NEXT FROM usage_cursor;", .direction = .next },
        .{ .sql = "FETCH FORWARD 10 IN usage_cursor;", .direction = .forward, .count = 10 },
        .{ .sql = "FETCH usage_cursor;", .direction = .next },
        .{ .sql = "FETCH 10 usage_cursor;", .direction = .forward, .count = 10 },
        .{ .sql = "FETCH FORWARD usage_cursor;", .direction = .forward },
    };
    for (fetch_cases) |case| {
        var lowered = try runtimeDdlPlanForTestAlloc(alloc, case.sql);
        defer lowered.deinit(alloc);
        switch (lowered) {
            .cursor_portal => |plan| switch (plan) {
                .fetch => |fetch| {
                    try std.testing.expectEqualStrings("usage_cursor", fetch.portal_name);
                    try std.testing.expectEqual(case.direction, fetch.direction);
                    try std.testing.expectEqual(case.count, fetch.count);
                },
                else => return error.TestUnexpectedResult,
            },
            else => return error.TestUnexpectedResult,
        }
    }

    const move_cases = [_]struct {
        sql: []const u8,
        direction: CursorFetchDirection,
        count: ?i64 = null,
    }{
        .{ .sql = "MOVE NEXT FROM usage_cursor;", .direction = .next },
        .{ .sql = "MOVE FORWARD 10 IN usage_cursor;", .direction = .forward, .count = 10 },
        .{ .sql = "MOVE usage_cursor;", .direction = .next },
    };
    for (move_cases) |case| {
        var lowered = try runtimeDdlPlanForTestAlloc(alloc, case.sql);
        defer lowered.deinit(alloc);
        switch (lowered) {
            .cursor_portal => |plan| switch (plan) {
                .move => |move| {
                    try std.testing.expectEqualStrings("usage_cursor", move.portal_name);
                    try std.testing.expectEqual(case.direction, move.direction);
                    try std.testing.expectEqual(case.count, move.count);
                },
                else => return error.TestUnexpectedResult,
            },
            else => return error.TestUnexpectedResult,
        }
    }

    var close_cursor = try runtimeDdlPlanForTestAlloc(alloc, "CLOSE usage_cursor;");
    defer close_cursor.deinit(alloc);
    switch (close_cursor) {
        .cursor_portal => |plan| switch (plan) {
            .close => |close| try std.testing.expectEqualStrings("usage_cursor", close.portal_name orelse return error.TestUnexpectedResult),
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var close_all = try runtimeDdlPlanForTestAlloc(alloc, "CLOSE ALL;");
    defer close_all.deinit(alloc);
    switch (close_all) {
        .cursor_portal => |plan| switch (plan) {
            .close => |close| try std.testing.expect(close.all),
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    const savepoint_cases = [_]struct {
        sql: []const u8,
        tag: std.meta.Tag(SavepointTransactionPlan),
    }{
        .{ .sql = "SAVEPOINT before_retry;", .tag = .savepoint },
        .{ .sql = "RELEASE SAVEPOINT before_retry;", .tag = .release },
        .{ .sql = "RELEASE before_retry;", .tag = .release },
        .{ .sql = "ROLLBACK TO SAVEPOINT before_retry;", .tag = .rollback_to },
        .{ .sql = "ROLLBACK TO before_retry;", .tag = .rollback_to },
    };
    for (savepoint_cases) |case| {
        var lowered = try runtimeDdlPlanForTestAlloc(alloc, case.sql);
        defer lowered.deinit(alloc);
        switch (lowered) {
            .savepoint_transaction => |plan| {
                try std.testing.expectEqual(case.tag, std.meta.activeTag(plan));
                const name = switch (plan) {
                    .savepoint => |savepoint| savepoint.savepoint_name,
                    .release => |release| release.savepoint_name,
                    .rollback_to => |rollback| rollback.savepoint_name,
                };
                try std.testing.expectEqualStrings("before_retry", name);
            },
            else => return error.TestUnexpectedResult,
        }
    }
}

const GeneratedPreparedStatementAstMutation = enum {
    stale_inner_dml_kind,
    stale_inner_ddl_name,
    stale_statement_span,
    stale_command_span,
    stale_prepare_layout,
    stale_deallocate_prepare_layout,
    stale_kind,
};

fn applyGeneratedPreparedStatementAstMutation(
    parsed_len: usize,
    ast: *generated_parser.GeneratedSqlPreparedAst,
    mutation: GeneratedPreparedStatementAstMutation,
) !void {
    switch (mutation) {
        .stale_inner_dml_kind => {
            const inner_ast = ast.inner_statement_ast orelse return error.TestUnexpectedResult;
            switch (inner_ast.*) {
                .dml => |*dml_ast| dml_ast.kind = .delete,
                else => return error.TestUnexpectedResult,
            }
        },
        .stale_inner_ddl_name => {
            const inner_ast = ast.inner_statement_ast orelse return error.TestUnexpectedResult;
            switch (inner_ast.*) {
                .ddl => |*ddl_ast| ddl_ast.object_name_tokens = .{
                    .start = parsed_len,
                    .end = parsed_len + 1,
                },
                else => return error.TestUnexpectedResult,
            }
        },
        .stale_statement_span => ast.statement_span.start += 1,
        .stale_command_span => ast.command_span.end += 1,
        .stale_prepare_layout => ast.inner_statement_tokens.?.start -= 1,
        .stale_deallocate_prepare_layout => ast.name_tokens = .{ .start = 1, .end = 3 },
        .stale_kind => ast.kind = .execute,
    }
}

fn expectGeneratedPreparedStatementAstMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    mutation: GeneratedPreparedStatementAstMutation,
    public_boundary: bool,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    const raw = parsed.generated_statement orelse return error.TestUnexpectedResult;
    if (public_boundary) {
        if (raw.ast) |generated_ast| switch (generated_ast) {
            .prepared => |prepared_ast| {
                var ast = prepared_ast;
                try applyGeneratedPreparedStatementAstMutation(parsed.items().len, &ast, mutation);
                parsed.generated_statement.?.ast = .{ .prepared = ast };
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
        try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlAlloc(alloc, &parsed));
        return;
    }

    var ast = switch (raw.ast orelse return error.TestUnexpectedResult) {
        .prepared => |ast| ast,
        else => return error.TestUnexpectedResult,
    };
    try applyGeneratedPreparedStatementAstMutation(parsed.items().len, &ast, mutation);
    try std.testing.expectError(
        error.UnsupportedSqlShape,
        preparedStatementPlanFromGeneratedAstAlloc(alloc, &parsed, ast),
    );
}

test "sql adapter generated prepared AST lowers to prepared statement plans" {
    const alloc = std.testing.allocator;

    const generated_prepare_sql = "PREPARE usage_plan(text) AS SELECT id FROM usage_records WHERE status = $1;";
    var generated_prepare = try generatedPreparedStatementPlanForTestAlloc(alloc, generated_prepare_sql);
    defer generated_prepare.deinit(alloc);
    switch (generated_prepare) {
        .prepare => |generated| {
            try std.testing.expectEqualStrings("usage_plan", generated.statement_name);
            try std.testing.expectEqual(@as(usize, 1), generated.parameter_count);
            try std.testing.expectEqual(PreparedStatementSubjectKind.read, generated.statement_kind);
            try std.testing.expectEqual(PreparedStatementStatementKind.read, generated.statement_family);
            const subject = generated.subject_parsed_sql orelse return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings("SELECT id FROM usage_records WHERE status = $1", subject.sql());
            try std.testing.expectEqualStrings("SELECT id FROM usage_records WHERE status = $1", subject.statementSql());
        },
        else => return error.TestUnexpectedResult,
    }

    const prepare_family_cases = [_]struct {
        sql: []const u8,
        subject: PreparedStatementSubjectKind,
        family: PreparedStatementStatementKind,
        generated_dml_kind: ?generated_parser.GeneratedSqlDmlKind = null,
    }{
        .{
            .sql = "PREPARE insert_plan(text) AS INSERT INTO usage_records (id) VALUES ($1);",
            .subject = .write,
            .family = .insert,
            .generated_dml_kind = .insert_values,
        },
        .{
            .sql = "PREPARE insert_source_plan AS INSERT INTO usage_records (id) SELECT id FROM incoming_usage;",
            .subject = .write,
            .family = .insert_source,
            .generated_dml_kind = .insert_select,
        },
        .{
            .sql = "PREPARE update_plan AS UPDATE usage_records SET status = 'done' WHERE id = 'u1';",
            .subject = .write,
            .family = .update,
            .generated_dml_kind = .update,
        },
        .{
            .sql = "PREPARE delete_plan AS DELETE FROM usage_records WHERE id = 'u1';",
            .subject = .write,
            .family = .delete,
            .generated_dml_kind = .delete,
        },
        .{
            .sql = "PREPARE truncate_plan AS TRUNCATE usage_records;",
            .subject = .write,
            .family = .truncate,
            .generated_dml_kind = .truncate,
        },
        .{
            .sql = "PREPARE merge_plan AS MERGE INTO usage_records USING source_rows ON usage_records.id = source_rows.id WHEN MATCHED THEN UPDATE SET status = source_rows.status;",
            .subject = .write,
            .family = .merge,
            .generated_dml_kind = .merge,
        },
    };

    for (prepare_family_cases) |case| {
        var generated_case = try generatedPreparedStatementPlanForTestAlloc(alloc, case.sql);
        defer generated_case.deinit(alloc);
        switch (generated_case) {
            .prepare => |prepare| {
                try std.testing.expectEqual(case.subject, prepare.statement_kind);
                try std.testing.expectEqual(case.family, prepare.statement_family);
                if (case.subject == .write) {
                    const subject = prepare.subject_parsed_sql orelse return error.TestUnexpectedResult;
                    try std.testing.expectEqual(generated_parser.GeneratedSqlStatementKind.dml, subject.generatedStatementKind().?);
                    try std.testing.expect(subject.writeStatementKindIncludingGeneratedAst() != null);
                    const generated_statement = subject.generated_statement orelse return error.TestUnexpectedResult;
                    const generated_ast = generated_statement.ast orelse return error.TestUnexpectedResult;
                    switch (generated_ast) {
                        .dml => |dml_ast| try std.testing.expectEqual(case.generated_dml_kind.?, dml_ast.kind),
                        else => return error.TestUnexpectedResult,
                    }
                }
            },
            else => return error.TestUnexpectedResult,
        }
    }

    const prepared_public_boundary_cases = [_]struct {
        sql: []const u8,
        mutation: GeneratedPreparedStatementAstMutation,
    }{
        .{
            .sql = "PREPARE stale_update_plan AS UPDATE usage_records SET status = 'done' WHERE id = 'u1';",
            .mutation = .stale_inner_dml_kind,
        },
        .{
            .sql = "PREPARE stale_create_table_plan AS CREATE TABLE prepared_usage_records (id uuid);",
            .mutation = .stale_inner_ddl_name,
        },
    };
    for (prepared_public_boundary_cases) |case| {
        try expectGeneratedPreparedStatementAstMutationFails(alloc, case.sql, case.mutation, true);
    }

    var generated_prepare_ddl = try generatedPreparedStatementPlanForTestAlloc(
        alloc,
        "PREPARE create_table_plan AS CREATE TABLE prepared_usage_records (id uuid);",
    );
    defer generated_prepare_ddl.deinit(alloc);
    switch (generated_prepare_ddl) {
        .prepare => |prepare| {
            try std.testing.expectEqual(PreparedStatementSubjectKind.ddl, prepare.statement_kind);
            try std.testing.expectEqual(PreparedStatementStatementKind.ddl, prepare.statement_family);
            const subject = prepare.subject_parsed_sql orelse return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings("CREATE TABLE prepared_usage_records (id uuid)", subject.sql());
            try std.testing.expectEqual(generated_parser.GeneratedSqlStatementKind.ddl, subject.generatedStatementKind().?);
        },
        else => return error.TestUnexpectedResult,
    }

    var generated_execute = try generatedPreparedStatementPlanForTestAlloc(alloc, "EXECUTE usage_plan('open', 10);");
    defer generated_execute.deinit(alloc);
    switch (generated_execute) {
        .execute => |generated| {
            try std.testing.expectEqualStrings("usage_plan", generated.statement_name);
            try std.testing.expectEqual(@as(usize, 2), generated.argument_count);
        },
        else => return error.TestUnexpectedResult,
    }

    var generated_deallocate = try generatedPreparedStatementPlanForTestAlloc(alloc, "DEALLOCATE usage_plan;");
    defer generated_deallocate.deinit(alloc);
    switch (generated_deallocate) {
        .deallocate => |generated| {
            try std.testing.expect(!generated.all);
            try std.testing.expectEqualStrings("usage_plan", generated.statement_name orelse return error.TestUnexpectedResult);
        },
        else => return error.TestUnexpectedResult,
    }

    var generated_deallocate_all = try generatedPreparedStatementPlanForTestAlloc(alloc, "DEALLOCATE ALL;");
    defer generated_deallocate_all.deinit(alloc);
    switch (generated_deallocate_all) {
        .deallocate => |generated| try std.testing.expect(generated.all),
        else => return error.TestUnexpectedResult,
    }

    const prepared_direct_cases = [_]struct {
        sql: []const u8,
        mutation: GeneratedPreparedStatementAstMutation,
    }{
        .{ .sql = "PREPARE usage_plan AS SELECT id FROM usage_records;", .mutation = .stale_statement_span },
        .{ .sql = "EXECUTE usage_plan('open');", .mutation = .stale_command_span },
        .{ .sql = "PREPARE usage_plan(text) AS SELECT id FROM usage_records;", .mutation = .stale_prepare_layout },
        .{ .sql = "DEALLOCATE PREPARE usage_plan;", .mutation = .stale_deallocate_prepare_layout },
        .{ .sql = "DEALLOCATE usage_plan;", .mutation = .stale_kind },
    };
    for (prepared_direct_cases) |case| {
        try expectGeneratedPreparedStatementAstMutationFails(alloc, case.sql, case.mutation, false);
    }
}

fn generatedPreparedStatementPlanForTestAlloc(alloc: std.mem.Allocator, sql: []const u8) !PreparedStatementPlan {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    const generated_raw = parsed.generated_statement orelse return error.UnsupportedSqlShape;
    const prepared_ast = switch (generated_raw.ast orelse return error.UnsupportedSqlShape) {
        .prepared => |ast| ast,
        else => return error.UnsupportedSqlShape,
    };
    return try preparedStatementPlanFromGeneratedAstAlloc(alloc, &parsed, prepared_ast);
}

