const GeneratedUnsupportedTriggerAstMutation = enum {
    kind,
    reason,
    command_span,
    missing_subject,
    subject_start,
    subject_end,
    explain_options,
    stale_trigger_payload,
};

fn expectGeneratedUnsupportedTriggerAstMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    expected_kind: generated_parser.GeneratedSqlUnsupportedKind,
    mutation: GeneratedUnsupportedTriggerAstMutation,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);

    if (parsed.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .unsupported => |*unsupported| {
                    try std.testing.expectEqual(expected_kind, unsupported.kind);
                    try std.testing.expectEqual(generatedUnsupportedExpectedReason(expected_kind), unsupported.reason);
                    const subject = unsupported.subject_tokens orelse return error.TestUnexpectedResult;
                    switch (mutation) {
                        .kind => unsupported.kind = switch (expected_kind) {
                            .create_trigger => .alter_trigger,
                            .alter_trigger => .create_trigger,
                            else => return error.TestUnexpectedResult,
                        },
                        .reason => unsupported.reason = switch (expected_kind) {
                            .create_trigger => .alter_trigger_not_planned_by_generated_parser,
                            .alter_trigger => .create_trigger_not_planned_by_generated_parser,
                            else => return error.TestUnexpectedResult,
                        },
                        .command_span => unsupported.command_span.start += 1,
                        .missing_subject => unsupported.subject_tokens = null,
                        .subject_start => unsupported.subject_tokens = .{ .start = subject.start + 1, .end = subject.end },
                        .subject_end => unsupported.subject_tokens = .{ .start = subject.start, .end = subject.end - 1 },
                        .explain_options => unsupported.explain_options_tokens = subject,
                        .stale_trigger_payload => unsupported.routine_name_tokens = subject,
                    }
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;

    try std.testing.expectError(error.UnsupportedSqlShape, logicalDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed, .{}));
}

const GeneratedUnsupportedCatalogPayloadMutation = enum {
    subject_start,
    routine_name_start,
    routine_operation_start,
    stale_routine_argument_count,
    stale_alter_table_payload,
    alter_table_name_start,
    alter_table_operation_start,
    alter_table_operation_kind,
    alter_table_operation_subject_start,
    stale_alter_table_operation_subject_payload,
    stale_routine_payload,
};

fn expectGeneratedUnsupportedCatalogPayloadMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    expected_kind: generated_parser.GeneratedSqlUnsupportedKind,
    mutation: GeneratedUnsupportedCatalogPayloadMutation,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);

    const generated_statement = parsed.generated_statement orelse return error.TestUnexpectedResult;
    const boundary = generatedUnsupportedCatalogBoundary(generated_statement.statement) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(expected_kind, boundary.kind);

    if (parsed.generated_statement) |*mutable_generated_statement| {
        if (mutable_generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .unsupported => |*unsupported| {
                    try std.testing.expectEqual(expected_kind, unsupported.kind);
                    try validateGeneratedUnsupportedCatalogAst(parsed.items(), unsupported.*, boundary);
                    const subject = unsupported.subject_tokens orelse return error.TestUnexpectedResult;
                    switch (mutation) {
                        .subject_start => unsupported.subject_tokens = .{ .start = subject.start + 1, .end = subject.end },
                        .routine_name_start => {
                            const range = unsupported.routine_name_tokens orelse return error.TestUnexpectedResult;
                            unsupported.routine_name_tokens = .{ .start = range.start + 1, .end = range.end };
                        },
                        .routine_operation_start => {
                            const range = unsupported.routine_operation_tokens orelse return error.TestUnexpectedResult;
                            unsupported.routine_operation_tokens = .{ .start = range.start + 1, .end = range.end };
                        },
                        .stale_routine_argument_count => {
                            const metadata = unsupported.routine_metadata orelse return error.TestUnexpectedResult;
                            metadata.argument_items.count += 1;
                        },
                        .stale_alter_table_payload => unsupported.alter_table_name_tokens = subject,
                        .alter_table_name_start => {
                            const range = unsupported.alter_table_name_tokens orelse return error.TestUnexpectedResult;
                            unsupported.alter_table_name_tokens = .{ .start = range.start + 1, .end = range.end };
                        },
                        .alter_table_operation_start => {
                            const range = unsupported.alter_table_operation_tokens orelse return error.TestUnexpectedResult;
                            unsupported.alter_table_operation_tokens = .{ .start = range.start + 1, .end = range.end };
                        },
                        .alter_table_operation_kind => unsupported.alter_table_operation_kind = .alter_table_tablespace,
                        .alter_table_operation_subject_start => {
                            const range = unsupported.alter_table_operation_subject_tokens orelse return error.TestUnexpectedResult;
                            unsupported.alter_table_operation_subject_tokens = .{ .start = range.start - 1, .end = range.end };
                        },
                        .stale_alter_table_operation_subject_payload => unsupported.alter_table_operation_subject_tokens = subject,
                        .stale_routine_payload => unsupported.routine_name_tokens = subject,
                    }
                    try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedUnsupportedCatalogAst(parsed.items(), unsupported.*, boundary));
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;

    try std.testing.expectError(error.UnsupportedSqlShape, logicalDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed, .{}));
}

const GeneratedIndexAstMutation = enum {
    missing_elements,
    corrupt_elements,
    missing_element_items,
    corrupt_element_expression,
    missing_include,
    missing_include_items,
    corrupt_include,
    stale_include,
    missing_options,
    corrupt_options,
    stale_options,
    missing_where,
    corrupt_where,
    corrupt_where_expression,
    stale_where,
    stale_unique,
    stale_if_not_exists,
    stale_drop_if_exists,
    stale_drop_cascade,
};

fn expectGeneratedIndexAstMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    mutation: GeneratedIndexAstMutation,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);

    if (parsed.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .extension_index => |*ddl| switch (mutation) {
                    .missing_elements => ddl.index_elements_tokens = null,
                    .corrupt_elements => ddl.index_elements_tokens = .{ .start = 8, .end = 9 },
                    .missing_element_items => {
                        ddl.index_element_items.deinit(alloc);
                        ddl.index_element_items = .{};
                    },
                    .corrupt_element_expression => {
                        if (ddl.index_element_items.expression_items.len == 0) return error.TestUnexpectedResult;
                        ddl.index_element_items.expression_items[0].start += 1;
                    },
                    .missing_include => ddl.index_include_tokens = null,
                    .missing_include_items => {
                        ddl.index_include_items.deinit(alloc);
                        ddl.index_include_items = .{};
                    },
                    .corrupt_include => ddl.index_include_tokens = .{ .start = 0, .end = 1 },
                    .stale_include => ddl.index_include_tokens = ddl.index_elements_tokens,
                    .missing_options => ddl.index_options_tokens = null,
                    .corrupt_options => ddl.index_options_tokens = .{ .start = 0, .end = 1 },
                    .stale_options => ddl.index_options_tokens = ddl.index_elements_tokens,
                    .missing_where => ddl.index_where_tokens = null,
                    .corrupt_where => ddl.index_where_tokens = .{ .start = 0, .end = 1 },
                    .corrupt_where_expression => {
                        ddl.index_where_expression.kind = .function_call;
                    },
                    .stale_where => ddl.index_where_tokens = ddl.index_elements_tokens,
                    .stale_unique => ddl.unique = !ddl.unique,
                    .stale_if_not_exists => ddl.if_not_exists = !ddl.if_not_exists,
                    .stale_drop_if_exists => ddl.if_exists = !ddl.if_exists,
                    .stale_drop_cascade => ddl.cascade = !ddl.cascade,
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;

    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlAlloc(alloc, &parsed));
    try std.testing.expectError(error.UnsupportedSqlShape, logicalDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed, .{}));
}

