fn generatedGraphDdlPlanForTestAlloc(alloc: std.mem.Allocator, sql: []const u8) !DdlPlan {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    const generated_raw = parsed.generated_statement orelse return error.UnsupportedSqlShape;
    const graph_ast = switch (generated_raw.ast orelse return error.UnsupportedSqlShape) {
        .graph => |ast| ast,
        else => return error.UnsupportedSqlShape,
    };
    return try graphDdlPlanFromGeneratedAstAlloc(alloc, parsed.items(), graph_ast);
}

const GeneratedGraphDdlAstMutation = enum {
    stale_statement_span,
    stale_command_span,
    missing_algorithm,
    missing_edge_target,
    missing_extraction_target,
};

fn expectGeneratedGraphDdlAstMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    mutation: GeneratedGraphDdlAstMutation,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    const raw = parsed.generated_statement orelse return error.TestUnexpectedResult;
    var ast = switch (raw.ast orelse return error.TestUnexpectedResult) {
        .graph => |ast| ast,
        else => return error.TestUnexpectedResult,
    };
    switch (mutation) {
        .stale_statement_span => ast.statement_span.start += 1,
        .stale_command_span => ast.command_span.end += 1,
        .missing_algorithm => ast.algorithm_tokens = null,
        .missing_edge_target => ast.edge_target_tokens = null,
        .missing_extraction_target => ast.extraction_target_tokens = null,
    }
    try std.testing.expectError(
        error.UnsupportedSqlShape,
        graphDdlPlanFromGeneratedAstAlloc(alloc, parsed.items(), ast),
    );
}

test "sql adapter ddl plan lowers generated graph AST into typed index plans" {
    const alloc = std.testing.allocator;

    try std.testing.expectError(error.UnsupportedSqlShape, generatedGraphDdlPlanForTestAlloc(
        alloc,
        "CREATE GRAPH INDEX docs_edge_graph ON doc_edges",
    ));

    const graph_index_sql = "CREATE GRAPH INDEX docs_edge_graph_syntax ON doc_edges EDGE (source_doc -> target_doc) TYPE edge_type WEIGHT confidence WITH (edge_policy = 'all');";
    var generated_graph_index = try generatedGraphDdlPlanForTestAlloc(alloc, graph_index_sql);
    defer generated_graph_index.deinit(alloc);
    switch (generated_graph_index) {
        .create_index => |generated| {
            try std.testing.expectEqual(DdlIndexMethod.antfly_graph, generated.method);
            try std.testing.expectEqualStrings("docs_edge_graph_syntax", generated.index_name);
            try std.testing.expectEqualStrings("doc_edges", generated.table_name);
            try std.testing.expect(!generated.if_not_exists);
            try std.testing.expectEqual(@as(usize, 2), generated.columns.len);
            try std.testing.expectEqualStrings("source_doc", generated.columns[0]);
            try std.testing.expectEqualStrings("target_doc", generated.columns[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    const graph_index_if_not_exists_sql = "CREATE GRAPH INDEX IF NOT EXISTS docs_edge_graph_syntax ON doc_edges EDGE (source_doc -> target_doc);";
    var generated_graph_index_if_not_exists = try generatedGraphDdlPlanForTestAlloc(alloc, graph_index_if_not_exists_sql);
    defer generated_graph_index_if_not_exists.deinit(alloc);
    switch (generated_graph_index_if_not_exists) {
        .create_index => |generated| {
            try std.testing.expect(generated.if_not_exists);
            try std.testing.expectEqualStrings("docs_edge_graph_syntax", generated.index_name);
            try std.testing.expectEqualStrings("doc_edges", generated.table_name);
        },
        else => return error.TestUnexpectedResult,
    }

    const graph_metric_sql = "CREATE GRAPH METRIC docs_pagerank ON docs_edge_graph WITH (metric = 'pagerank', damping = 0.85, max_iterations = 40);";
    var generated_graph_metric = try generatedGraphDdlPlanForTestAlloc(alloc, graph_metric_sql);
    defer generated_graph_metric.deinit(alloc);
    switch (generated_graph_metric) {
        .create_index => |generated| {
            try std.testing.expectEqual(DdlIndexMethod.antfly_graph_metric, generated.method);
            try std.testing.expectEqualStrings("docs_pagerank", generated.index_name);
            try std.testing.expectEqualStrings("", generated.table_name);
            try std.testing.expectEqual(@as(usize, 0), generated.columns.len);
            const config = generated.derived_index_config_json orelse return error.TestUnexpectedResult;
            try std.testing.expect(std.mem.indexOf(u8, config, "\"type\":\"graph_metric\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"graph_index\":\"docs_edge_graph\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"metric\":\"docs_pagerank\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"algorithm\":\"pagerank\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"damping\":0.85") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"max_iterations\":40") != null);
        },
        else => return error.TestUnexpectedResult,
    }

    const graph_extraction_sql = "CREATE GRAPH INDEX docs_rel_graph ON docs SOURCE ENRICHMENT relations_v1 FROM body USING extractor MODEL 'relations' EDGES JSON_PATH '$.relations[*]' SOURCE _id TARGET target.document_id TYPE type WEIGHT confidence WITH (edge_policy = 'all');";
    var generated_graph_extraction = try generatedGraphDdlPlanForTestAlloc(alloc, graph_extraction_sql);
    defer generated_graph_extraction.deinit(alloc);
    switch (generated_graph_extraction) {
        .create_index => |generated| {
            try std.testing.expectEqual(DdlIndexMethod.antfly_graph, generated.method);
            try std.testing.expectEqualStrings("docs_rel_graph", generated.index_name);
            try std.testing.expectEqualStrings("docs", generated.table_name);
            try std.testing.expectEqual(@as(usize, 1), generated.columns.len);
            try std.testing.expectEqualStrings("body", generated.columns[0]);
            const config = generated.derived_index_config_json orelse return error.TestUnexpectedResult;
            try std.testing.expect(std.mem.indexOf(u8, config, "\"artifact\":\"relations_v1\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"field\":\"body\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"target\":\"{{ _item.target.document_id }}\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"edge_policy\":\"all\"") != null);
        },
        else => return error.TestUnexpectedResult,
    }

    const graph_alter_metric_sql = "ALTER GRAPH INDEX docs_edge_graph ADD METRIC pagerank_v1 USING pagerank WITH (damping = 0.85, max_iterations = 40);";
    var generated_graph_alter_metric = try generatedGraphDdlPlanForTestAlloc(alloc, graph_alter_metric_sql);
    defer generated_graph_alter_metric.deinit(alloc);
    switch (generated_graph_alter_metric) {
        .create_index => |generated| {
            try std.testing.expectEqual(DdlIndexMethod.antfly_graph_metric, generated.method);
            try std.testing.expectEqualStrings("pagerank_v1", generated.index_name);
            try std.testing.expectEqualStrings("", generated.table_name);
            const config = generated.derived_index_config_json orelse return error.TestUnexpectedResult;
            try std.testing.expect(std.mem.indexOf(u8, config, "\"graph_index\":\"docs_edge_graph\"") != null);
            try std.testing.expect(std.mem.indexOf(u8, config, "\"algorithm\":\"pagerank\"") != null);
        },
        else => return error.TestUnexpectedResult,
    }

    const graph_metadata_cases = [_]struct {
        sql: []const u8,
        mutation: GeneratedGraphDdlAstMutation,
    }{
        .{ .sql = graph_index_sql, .mutation = .stale_statement_span },
        .{ .sql = graph_alter_metric_sql, .mutation = .stale_command_span },
        .{ .sql = graph_alter_metric_sql, .mutation = .missing_algorithm },
        .{ .sql = graph_index_sql, .mutation = .missing_edge_target },
        .{ .sql = graph_extraction_sql, .mutation = .missing_extraction_target },
    };
    for (graph_metadata_cases) |case| {
        try expectGeneratedGraphDdlAstMutationFails(alloc, case.sql, case.mutation);
    }
}

fn expectGeneratedDdlExpressionKindMutationFailsAtPublicBoundaries(
    alloc: std.mem.Allocator,
    sql: []const u8,
    expression_index: usize,
    expected_kind: generated_parser.GeneratedSqlExpressionKind,
    mutated_kind: generated_parser.GeneratedSqlExpressionKind,
    function_bindings: expr_row_parse.SqlFunctionBindings,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    if (parsed.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .ddl => |*ddl| {
                if (ddl.alter_table_operation_generated_expressions.len <= expression_index) return error.TestUnexpectedResult;
                try std.testing.expectEqual(expected_kind, ddl.alter_table_operation_generated_expressions[expression_index].kind);
                ddl.alter_table_operation_generated_expressions[expression_index].kind = mutated_kind;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed, function_bindings));
    try std.testing.expectError(error.UnsupportedSqlShape, logicalDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed, function_bindings));
}

test "sql adapter ddl plan lowers routine expression bindings into ddl plans" {
    const alloc = std.testing.allocator;

    const normalize_operands = [_]db_mod.types.RelationalRowsExpression{.{ .kind = .field, .field = "arg1" }};
    const normalize_expression = db_mod.types.RelationalRowsExpression{
        .kind = .lower,
        .operands = &normalize_operands,
    };
    const bindings = [_]expr_row_parse.RoutineExpressionBinding{.{
        .sql_name = "normalize_status",
        .arity = 1,
        .expression = normalize_expression,
    }};

    try std.testing.expectError(
        error.UnsupportedSqlShape,
        runtimeDdlPlanForTestAlloc(
            alloc,
            "CREATE TABLE usage_records (id text PRIMARY KEY, status text, status_key text GENERATED ALWAYS AS (normalize_status(status)) STORED);",
        ),
    );

    var generated_table = try runtimeDdlPlanWithFunctionBindingsForTestAlloc(
        alloc,
        "CREATE TABLE usage_records (id text PRIMARY KEY, status text, status_key text GENERATED ALWAYS AS (normalize_status(status)) STORED);",
        .{ .routine_expressions = &bindings },
    );
    defer generated_table.deinit(alloc);
    const generated_create = switch (generated_table) {
        .create_table => |create| create,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 3), generated_create.columns.len);
    const generated = generated_create.columns[2].generated orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(runtime_schema.RelationalGeneratedOp.expression, generated.op);
    const generated_expression = generated.expression orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, generated_expression.kind);
    try std.testing.expectEqual(@as(usize, 1), generated_expression.operands.len);
    try std.testing.expectEqualStrings("status", generated_expression.operands[0].field);

    try expectGeneratedDdlExpressionKindMutationFailsAtPublicBoundaries(
        alloc,
        "CREATE TABLE usage_records (id text PRIMARY KEY, status text, status_key text GENERATED ALWAYS AS (normalize_status(status)) STORED);",
        2,
        .function_call,
        .token_range,
        .{ .routine_expressions = &bindings },
    );

    var rewrite_table = try runtimeDdlPlanWithFunctionBindingsForTestAlloc(
        alloc,
        "ALTER TABLE usage_records ALTER COLUMN status TYPE text USING normalize_status(status);",
        .{ .routine_expressions = &bindings },
    );
    defer rewrite_table.deinit(alloc);
    const rewrite_alter = switch (rewrite_table) {
        .alter_table => |alter| alter,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), rewrite_alter.operations.len);
    const rewrite_expression = switch (rewrite_alter.operations[0]) {
        .alter_column_type => |operation| (operation.rewrite_expression orelse return error.TestUnexpectedResult).expression,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, rewrite_expression.kind);
    try std.testing.expectEqual(@as(usize, 1), rewrite_expression.operands.len);
    try std.testing.expectEqualStrings("status", rewrite_expression.operands[0].field);

    var checked_table = try runtimeDdlPlanWithFunctionBindingsForTestAlloc(
        alloc,
        "CREATE TABLE usage_records (id text PRIMARY KEY, status text, CONSTRAINT usage_records_status_check CHECK (normalize_status(status) != 'deleted'));",
        .{ .routine_expressions = &bindings },
    );
    defer checked_table.deinit(alloc);
    const checked_create = switch (checked_table) {
        .create_table => |create| create,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), checked_create.checks.len);
    try std.testing.expectEqualStrings("usage_records_status_check", checked_create.checks[0].name);
    const checked_expression = checked_create.checks[0].expression orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, checked_expression.lhs.kind);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, checked_expression.op);
    try std.testing.expectEqualStrings("status", checked_expression.lhs.operands[0].field);
    try std.testing.expectEqualStrings("\"deleted\"", checked_expression.rhs[0].value_json);

    var routine_policy = try runtimeDdlPlanWithFunctionBindingsForTestAlloc(
        alloc,
        "CREATE POLICY usage_records_normalized_policy ON usage_records USING (normalize_status(status) = 'active');",
        .{ .routine_expressions = &bindings },
    );
    defer routine_policy.deinit(alloc);
    const routine_policy_create = switch (routine_policy) {
        .row_security_catalog => |catalog_plan| switch (catalog_plan) {
            .create_policy => |create| create,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    const routine_policy_expression = switch (routine_policy_create.predicate) {
        .expression => |predicate| predicate,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, routine_policy_expression.lhs.kind);
    try std.testing.expectEqualStrings("status", routine_policy_expression.lhs.operands[0].field);
}

const GeneratedMaterializedViewMetadataMutation = enum {
    corrupt_create_columns,
    missing_create_query,
    missing_create_population,
    corrupt_create_data_clause,
    stale_drop_cascade,
    missing_refresh_operation,
    missing_refresh_concurrently,
    stale_refresh_population,
    stale_kind,
    corrupt_subject,
};

fn applyGeneratedMaterializedViewMetadataMutation(
    parsed_len: usize,
    ddl: *generated_parser.GeneratedSqlDdlAst,
    mutation: GeneratedMaterializedViewMetadataMutation,
) !void {
    switch (mutation) {
        .corrupt_create_columns => (ddl.view_metadata orelse return error.TestUnexpectedResult).column_items.items[0].start += 1,
        .missing_create_query => (ddl.view_metadata orelse return error.TestUnexpectedResult).query_tokens = null,
        .missing_create_population => ddl.materialized_view_populate = null,
        .corrupt_create_data_clause => ddl.materialized_view_data_clause_tokens.?.start += 1,
        .stale_drop_cascade => ddl.cascade = false,
        .missing_refresh_operation => ddl.alter_table_operation_tokens = null,
        .missing_refresh_concurrently => ddl.materialized_view_concurrently = null,
        .stale_refresh_population => ddl.materialized_view_populate = false,
        .stale_kind => ddl.kind = .drop_materialized_view,
        .corrupt_subject => ddl.object_name_tokens = .{ .start = 2, .end = parsed_len },
    }
}

fn expectGeneratedMaterializedViewMetadataMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    mutation: GeneratedMaterializedViewMetadataMutation,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    if (parsed.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .ddl => |*ddl| try applyGeneratedMaterializedViewMetadataMutation(parsed.items().len, ddl, mutation),
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlAlloc(alloc, &parsed));
}

test "sql adapter generated materialized view DDL AST lowers to catalog plans" {
    const alloc = std.testing.allocator;

    var create_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "CREATE MATERIALIZED VIEW users_mv(user_id, contact_email) AS SELECT id, email FROM users WITH NO DATA;",
    );
    defer create_sql.deinit(alloc);
    var create_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &create_sql);
    defer create_plan.deinit(alloc);
    switch (create_plan) {
        .materialized_view_catalog => |catalog| switch (catalog) {
            .create => |create| {
                try std.testing.expectEqualStrings("users_mv", create.view_name);
                try std.testing.expectEqualStrings("users", create.source_table_name);
                try std.testing.expectEqualStrings("user_id", create.output_fields[0]);
                try std.testing.expect(!create.populate_on_create);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var create_replace_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "CREATE OR REPLACE MATERIALIZED VIEW users_mv AS SELECT id FROM users WITH NO DATA;",
    );
    defer create_replace_sql.deinit(alloc);
    var create_replace_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &create_replace_sql);
    defer create_replace_plan.deinit(alloc);
    switch (create_replace_plan) {
        .materialized_view_catalog => |catalog| switch (catalog) {
            .create => |create| {
                try std.testing.expectEqualStrings("users_mv", create.view_name);
                try std.testing.expect(create.replace_existing);
                try std.testing.expect(!create.populate_on_create);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    const materialized_view_metadata_cases = [_]struct {
        sql: []const u8,
        mutation: GeneratedMaterializedViewMetadataMutation,
    }{
        .{ .sql = "CREATE MATERIALIZED VIEW users_mv(user_id, contact_email) AS SELECT id, email FROM users;", .mutation = .corrupt_create_columns },
        .{ .sql = "CREATE MATERIALIZED VIEW users_mv AS SELECT id FROM users;", .mutation = .missing_create_query },
        .{ .sql = "CREATE MATERIALIZED VIEW users_mv AS SELECT id FROM users WITH NO DATA;", .mutation = .missing_create_population },
        .{ .sql = "CREATE MATERIALIZED VIEW users_mv AS SELECT id FROM users WITH NO DATA;", .mutation = .corrupt_create_data_clause },
        .{ .sql = "DROP MATERIALIZED VIEW IF EXISTS users_mv CASCADE;", .mutation = .stale_drop_cascade },
        .{ .sql = "REFRESH MATERIALIZED VIEW CONCURRENTLY users_mv WITH NO DATA;", .mutation = .missing_refresh_operation },
        .{ .sql = "REFRESH MATERIALIZED VIEW CONCURRENTLY users_mv WITH NO DATA;", .mutation = .missing_refresh_concurrently },
        .{ .sql = "REFRESH MATERIALIZED VIEW users_mv;", .mutation = .stale_refresh_population },
        .{ .sql = "CREATE MATERIALIZED VIEW users_mv AS SELECT id FROM users;", .mutation = .stale_kind },
        .{ .sql = "DROP MATERIALIZED VIEW users_mv;", .mutation = .corrupt_subject },
    };
    for (materialized_view_metadata_cases) |case| {
        try expectGeneratedMaterializedViewMetadataMutationFails(alloc, case.sql, case.mutation);
    }

    var drop_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "DROP MATERIALIZED VIEW IF EXISTS users_mv CASCADE;",
    );
    defer drop_sql.deinit(alloc);
    var drop_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &drop_sql);
    defer drop_plan.deinit(alloc);
    switch (drop_plan) {
        .materialized_view_catalog => |catalog| switch (catalog) {
            .drop => |drop| {
                try std.testing.expectEqualStrings("users_mv", drop.view_name);
                try std.testing.expect(drop.if_exists);
                try std.testing.expect(drop.cascade);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var refresh_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "REFRESH MATERIALIZED VIEW CONCURRENTLY users_mv WITH NO DATA;",
    );
    defer refresh_sql.deinit(alloc);
    var refresh_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &refresh_sql);
    defer refresh_plan.deinit(alloc);
    switch (refresh_plan) {
        .materialized_view_catalog => |catalog| switch (catalog) {
            .refresh => |refresh| {
                try std.testing.expectEqualStrings("users_mv", refresh.view_name);
                try std.testing.expect(refresh.concurrently);
                try std.testing.expect(!refresh.populate);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var unsupported_alter_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "ALTER MATERIALIZED VIEW users_mv RENAME TO users_mv_v2;",
    );
    defer unsupported_alter_sql.deinit(alloc);
    switch (unsupported_alter_sql.statement) {
        .unsupported => {},
        else => return error.TestUnexpectedResult,
    }
    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlAlloc(alloc, &unsupported_alter_sql));
}

const GeneratedViewMetadataMutation = enum {
    corrupt_create_columns,
    missing_create_query,
    missing_query_read,
    stale_query_read,
    missing_rename_target,
    stale_replace,
    stale_alter_operation,
};

fn applyGeneratedViewMetadataMutation(
    alloc: std.mem.Allocator,
    parsed_len: usize,
    ddl: *generated_parser.GeneratedSqlDdlAst,
    mutation: GeneratedViewMetadataMutation,
) !void {
    switch (mutation) {
        .corrupt_create_columns => (ddl.view_metadata orelse return error.TestUnexpectedResult).column_items.items[0].start += 1,
        .missing_create_query => (ddl.view_metadata orelse return error.TestUnexpectedResult).query_tokens = null,
        .missing_query_read => {
            const metadata = ddl.view_metadata orelse return error.TestUnexpectedResult;
            const read = metadata.query_read orelse return error.TestUnexpectedResult;
            read.deinit(alloc);
            alloc.destroy(read);
            metadata.query_read = null;
        },
        .stale_query_read => {
            const metadata = ddl.view_metadata orelse return error.TestUnexpectedResult;
            const read = metadata.query_read orelse return error.TestUnexpectedResult;
            read.projection_items.count += 1;
        },
        .missing_rename_target => ddl.rename_target_tokens = null,
        .stale_replace => ddl.replace_existing = false,
        .stale_alter_operation => ddl.alter_table_operation_tokens = .{ .start = 2, .end = parsed_len },
    }
}

fn expectGeneratedViewMetadataMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    mutation: GeneratedViewMetadataMutation,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    if (parsed.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .ddl => |*ddl| try applyGeneratedViewMetadataMutation(alloc, parsed.items().len, ddl, mutation),
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlAlloc(alloc, &parsed));
}

test "sql adapter generated view DDL AST lowers to catalog plans" {
