}

test "sql adapter generated row policy DDL AST lowers to catalog plans" {
    const alloc = std.testing.allocator;

    var create_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "CREATE POLICY usage_records_targeted_policy ON usage_records AS RESTRICTIVE FOR SELECT TO app_reader, app_writer USING (tenant_id = current_setting('app.tenant_id')) WITH CHECK (status = 'active');",
    );
    defer create_sql.deinit(alloc);
    var create_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &create_sql);
    defer create_plan.deinit(alloc);
    switch (create_plan) {
        .row_security_catalog => |catalog| switch (catalog) {
            .create_policy => |create| {
                try std.testing.expectEqualStrings("usage_records_targeted_policy", create.policy_name);
                try std.testing.expectEqualStrings("usage_records", create.table_name);
                try std.testing.expectEqual(RowSecurityPolicyMode.restrictive, create.mode.?);
                try std.testing.expectEqual(RowSecurityPolicyCommand.select, create.command.?);
                try std.testing.expectEqual(@as(usize, 2), create.role_targets.len);
                try std.testing.expectEqualStrings("app_reader", create.role_targets[0]);
                try std.testing.expectEqualStrings("app_writer", create.role_targets[1]);
                switch (create.predicate) {
                    .current_setting_equals => |predicate| {
                        try std.testing.expectEqualStrings("tenant_id", predicate.field);
                        try std.testing.expectEqualStrings("app.tenant_id", predicate.setting_name);
                    },
                    else => return error.TestUnexpectedResult,
                }
                switch (create.check_predicate orelse return error.TestUnexpectedResult) {
                    .literal_equals => |predicate| {
                        try std.testing.expectEqualStrings("status", predicate.field);
                        try std.testing.expectEqualStrings("\"active\"", predicate.value_json);
                    },
                    else => return error.TestUnexpectedResult,
                }
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var alter_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "ALTER POLICY usage_records_tenant_policy ON usage_records WITH CHECK (status = 'ready');",
    );
    defer alter_sql.deinit(alloc);
    var alter_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &alter_sql);
    defer alter_plan.deinit(alloc);
    switch (alter_plan) {
        .row_security_catalog => |catalog| switch (catalog) {
            .alter_policy => |alter| {
                try std.testing.expectEqualStrings("usage_records_tenant_policy", alter.policy_name);
                try std.testing.expectEqualStrings("usage_records", alter.table_name);
                try std.testing.expect(!alter.role_targets_present);
                try std.testing.expect(alter.predicate == null);
                switch (alter.check_predicate orelse return error.TestUnexpectedResult) {
                    .literal_equals => |predicate| {
                        try std.testing.expectEqualStrings("status", predicate.field);
                        try std.testing.expectEqualStrings("\"ready\"", predicate.value_json);
                    },
                    else => return error.TestUnexpectedResult,
                }
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var drop_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "DROP POLICY usage_records_tenant_policy ON usage_records;",
    );
    defer drop_sql.deinit(alloc);
    var drop_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &drop_sql);
    defer drop_plan.deinit(alloc);
    switch (drop_plan) {
        .row_security_catalog => |catalog| switch (catalog) {
            .drop_policy => |drop| {
                try std.testing.expectEqualStrings("usage_records_tenant_policy", drop.policy_name);
                try std.testing.expectEqualStrings("usage_records", drop.table_name);
                try std.testing.expect(!drop.if_exists);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    const create_policy_using_sql = "CREATE POLICY usage_records_targeted_policy ON usage_records USING (tenant_id = 'tenant-a');";
    const create_policy_roles_sql = "CREATE POLICY usage_records_targeted_policy ON usage_records TO app_reader, app_writer USING (tenant_id = current_setting('app.tenant_id'));";
    const alter_policy_check_sql = "ALTER POLICY usage_records_tenant_policy ON usage_records WITH CHECK (status = 'ready');";
    const row_policy_metadata_cases = [_]struct {
        sql: []const u8,
        mutation: GeneratedRowPolicyMetadataMutation,
    }{
        .{ .sql = create_policy_using_sql, .mutation = .stale_kind },
        .{ .sql = "DROP POLICY usage_records_tenant_policy ON usage_records;", .mutation = .malformed_table },
        .{ .sql = "CREATE POLICY usage_records_targeted_policy ON usage_records AS RESTRICTIVE USING (tenant_id = 'tenant-a');", .mutation = .missing_mode },
        .{ .sql = "CREATE POLICY usage_records_targeted_policy ON usage_records FOR SELECT USING (tenant_id = 'tenant-a');", .mutation = .missing_command },
        .{ .sql = create_policy_using_sql, .mutation = .missing_using },
        .{ .sql = "CREATE POLICY usage_records_targeted_policy ON usage_records USING (tenant_id = 'tenant-a') WITH CHECK (status = 'active');", .mutation = .missing_check },
        .{ .sql = create_policy_roles_sql, .mutation = .missing_roles },
        .{ .sql = create_policy_roles_sql, .mutation = .corrupt_roles },
        .{ .sql = alter_policy_check_sql, .mutation = .stale_alter_roles },
    };
    for (row_policy_metadata_cases) |case| {
        try expectGeneratedRowPolicyMetadataMutationFails(alloc, case.sql, case.mutation);
    }

    try expectGeneratedRowPolicyLogicalUsingMissingFails(alloc, create_policy_using_sql);
}

const GeneratedCommentMetadataMutation = enum {
    stale_target,
    missing_value,
    missing_constraint_parent,
    stale_function_signature,
};

fn applyGeneratedCommentMetadataMutation(
    ddl: *generated_parser.GeneratedSqlDdlAst,
    mutation: GeneratedCommentMetadataMutation,
) !void {
    switch (mutation) {
        .stale_target => ddl.comment_target = .index,
        .missing_value => ddl.comment_value_tokens = null,
