    var default_grant_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "ALTER DEFAULT PRIVILEGES FOR ROLE app_owner IN SCHEMA public GRANT SELECT, INSERT ON TABLES TO readonly, app_writer WITH GRANT OPTION;",
