        else => return error.TestUnexpectedResult,
    }
    var logical_plan = try logicalDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &parsed, .{});
    defer logical_plan.deinit(alloc);
    switch (logical_plan) {
        .maintenance => |maintenance| switch (maintenance) {
            .vacuum => |vacuum| {
                try std.testing.expectEqualStrings("usage_records", vacuum.table_name);
                try std.testing.expect(!vacuum.full);
                try std.testing.expect(!vacuum.freeze);
                try std.testing.expect(!vacuum.verbose);
                try std.testing.expect(!vacuum.analyze);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    try expectGeneratedMaintenanceUnsupportedLogicalSubjectMutationFails(alloc, "VACUUM usage_records;");

    var reindex = try tokenized.ParsedSql.initAlloc(
        alloc,
        "REINDEX INDEX CONCURRENTLY usage_records_status_idx;",
    );
    defer reindex.deinit(alloc);
    var reindex_logical = try logicalDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &reindex, .{});
    defer reindex_logical.deinit(alloc);
    switch (reindex_logical) {
        .maintenance => |maintenance| switch (maintenance) {
            .reindex => |plan| {
                try std.testing.expectEqual(ReindexMaintenanceTarget.index, plan.target);
                try std.testing.expectEqualStrings("usage_records_status_idx", plan.name);
                try std.testing.expect(plan.concurrently);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var cluster = try tokenized.ParsedSql.initAlloc(
        alloc,
        "CLUSTER usage_records USING usage_records_status_idx;",
    );
    defer cluster.deinit(alloc);
    var cluster_logical = try logicalDdlPlanParsedSqlWithFunctionBindingsAlloc(alloc, &cluster, .{});
    defer cluster_logical.deinit(alloc);
    switch (cluster_logical) {
        .maintenance => |maintenance| switch (maintenance) {
            .cluster => |plan| {
                try std.testing.expectEqualStrings("usage_records", plan.table_name);
                try std.testing.expectEqualStrings("usage_records_status_idx", plan.index_name orelse return error.TestUnexpectedResult);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }

    var stripped_generated = try tokenized.ParsedSql.initAlloc(
        alloc,
        "VACUUM usage_records;",
    );
    defer stripped_generated.deinit(alloc);
    if (stripped_generated.generated_statement) |*generated_statement| {
        generated_statement.deinit(alloc);
        stripped_generated.generated_statement = null;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlAlloc(alloc, &stripped_generated));
}

const GeneratedCursorSavepointMetadataMutation = enum {
    stale_fetch_kind,
    malformed_cursor_tail,
    missing_cursor_portal,
    stale_cursor_subject,
    missing_cursor_subject_ast,
    malformed_savepoint_name,
};

fn expectGeneratedCursorSavepointMetadataMutationFails(
    alloc: std.mem.Allocator,
    sql: []const u8,
    mutation: GeneratedCursorSavepointMetadataMutation,
) !void {
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, sql);
    defer parsed.deinit(alloc);
    if (parsed.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .cursor => |*cursor| switch (mutation) {
                .stale_fetch_kind => cursor.kind = .close,
                .malformed_cursor_tail => cursor.tail_tokens = .{ .start = 0, .end = parsed.items().len },
                .missing_cursor_portal => cursor.portal_name_tokens = null,
                .stale_cursor_subject => cursor.subject_tokens = cursor.tail_tokens,
                .missing_cursor_subject_ast => {
                    if (cursor.subject_ast) |subject_ast| {
                        subject_ast.deinit(alloc);
                        alloc.destroy(subject_ast);
                    }
                    cursor.subject_ast = null;
                },
                .malformed_savepoint_name => return error.TestUnexpectedResult,
            },
            .transaction => |*transaction| switch (mutation) {
                .malformed_savepoint_name => transaction.name_tokens = .{ .start = 0, .end = parsed.items().len },
                else => return error.TestUnexpectedResult,
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, runtimeDdlPlanParsedSqlAlloc(alloc, &parsed));
}

test "sql adapter generated cursor and savepoint transaction AST lowers to catalog plans" {
    const alloc = std.testing.allocator;

    var declare_sql = try tokenized.ParsedSql.initAlloc(
        alloc,
        "DECLARE usage_cursor CURSOR FOR SELECT id FROM usage_records ORDER BY id;",
    );
    defer declare_sql.deinit(alloc);
    var declare_plan = try runtimeDdlPlanParsedSqlAlloc(alloc, &declare_sql);
    defer declare_plan.deinit(alloc);
    switch (declare_plan) {
        .cursor_portal => |cursor| switch (cursor) {
            .declare => |declare| {
                try std.testing.expectEqualStrings("usage_cursor", declare.portal_name);
                try std.testing.expectEqual(CursorScrollMode.default, declare.scroll);
                try std.testing.expect(!declare.binary);
                try std.testing.expect(!declare.hold);
                try std.testing.expectEqual(PreparedStatementSubjectKind.read, declare.statement_kind);
                const subject = declare.subject_parsed_sql orelse return error.TestUnexpectedResult;
                try std.testing.expectEqual(generated_parser.GeneratedSqlStatementKind.read, subject.generatedStatementKind().?);
